def _in_base(p, search_path=False):
    """Relative paths from .env (e.g. ZSIGN_PATH=zsign) are resolved
    against the bot folder, not the process cwd. subprocess does NOT
    look in cwd for a bare command name, only in PATH, which caused
    "[Errno 2] No such file or directory: 'zsign'". A bare command
    name that is not in the bot folder is kept as-is for a PATH lookup."""
    p = (p or "").strip()
    if not p or os.path.isabs(p):
        return p
    cand = os.path.join(BASE_DIR, p)
    if os.path.exists(cand):
        return cand
    if search_path and os.sep not in p:
        return p
    return cand


