def load_anisette():
    try:
        with open(ANISETTE_FILE, encoding="utf-8") as f:
            data = json.load(f)
        url = (data.get("url") or "").strip()
        if url.startswith("https://") or url.startswith("http://"):
            return {"url": url.rstrip("/"), "preset": data.get("preset", "custom")}
    except Exception:
        pass
    return {"url": ANISETTE_URL, "preset": "env"}

def save_anisette(url, preset):
    try:
        tmp = ANISETTE_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"url": url.rstrip("/"), "preset": preset}, f, ensure_ascii=False, indent=1)
        os.replace(tmp, ANISETTE_FILE)
        return True
    except Exception:
        return False

def effective_anisette_url():
    return load_anisette()["url"]

def validate_anisette_url(url):
    url = (url or "").strip().rstrip("/")
    if not url.startswith("https://") or " " in url or "." not in url:
        return None
    return url


