    try:
        if not url:
            try:
                os.remove(OTA_URL_FILE)
            except Exception:
                pass
            return True
        tmp = OTA_URL_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"url": url.rstrip("/")}, f, ensure_ascii=False, indent=1)
        os.replace(tmp, OTA_URL_FILE)
        return True
    except Exception:
        return False


