def load_admins():
    try:
        with open(ADMIN_FILE, encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and isinstance(data.get("admins"), list):
            return [int(x) for x in data["admins"]]
    except Exception:
        pass
    return []

def save_admins(admins):
    try:
        tmp = ADMIN_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"admins": [int(x) for x in admins]}, f, ensure_ascii=False, indent=1)
        os.replace(tmp, ADMIN_FILE)
        return True
    except Exception:
        return False

def is_authorized(user_id):
    try:
        uid = int(user_id)
    except Exception:
        return False
    return uid == OWNER_ID or uid in load_admins()


def _loop_allows(msg, chat_id):
    """Polling-loop gate for plain messages. Owner/admins always.
    Anyone may present an invite payload (/start pf_...) -- the
    token itself is the authorization, validated in handle_text.
    A consumed invite's chat may write: handle_text and
    handle_document enforce the guest file-only rules from there.
    Everyone else gets owner_only, as before."""
    if is_authorized((msg.get("from") or {}).get("id")):
        return True
    if (msg.get("text") or "").strip().startswith("/start pf_"):
        return True
    return _is_guest_chat(chat_id)

def is_owner(user_id):
    try:
        return int(user_id) == OWNER_ID
    except Exception:
        return False

