def _load_lang():
    try:
        with open(LANG_FILE, encoding="utf-8") as f:
            lang = json.load(f).get("lang", "uk")
        return lang if lang in LANGS else "uk"
    except Exception:
        return "uk"

CUR_LANG = _load_lang()

def save_lang(lang):
    global CUR_LANG
    CUR_LANG = lang
    try:
        with open(LANG_FILE, "w", encoding="utf-8") as f:
            json.dump({"lang": lang}, f)
    except Exception:
        pass

