def commands_text():
    _lines = [tr("commands_title"), ""]
    for _cmd, _desc in COMMANDS:
        _lines.append("/%s — %s" % (_cmd, _desc.get(CUR_LANG, _desc["en"])))
    return "\n".join(_lines)


def register_bot_commands():
    """Register the command list in Telegram's own command menu
    (the '/' button), once per language. Best effort: a failure
    here must never stop the bot."""
    try:
        for _lang in ("uk", "ru", "de", "en"):
            _payload = [{"command": _cmd, "description": _desc[_lang][:256]}
                        for _cmd, _desc in COMMANDS]
            _res = api("setMyCommands", commands=json.dumps(_payload, ensure_ascii=False),
                       language_code=_lang)
            print("setMyCommands %s: %s" % (_lang, bool(_res.get("ok"))), flush=True)
        _payload = [{"command": _cmd, "description": _desc["en"][:256]}
                    for _cmd, _desc in COMMANDS]
        _res = api("setMyCommands", commands=json.dumps(_payload, ensure_ascii=False))
        print("setMyCommands default: %s" % bool(_res.get("ok")), flush=True)
    except Exception as e:
        print("setMyCommands failed: %s" % e, flush=True)


def btn(action):
    return BTN_LABELS[action][CUR_LANG]

def btn_action(text):
    for action, labels in BTN_LABELS.items():
        if text in labels.values():
            # Label keys that differ from the screen action they
            # sit on: the Yes/No pair is reused by the profile and
            # admin delete confirms, and Rename/Sign-out sit on
            # the profiles screen under list actions. last_actions
            # (the current screen) wins in handle_text; these
            # aliases are the stale-keyboard fallback.
            if action == "prof_del_no":
                return "profiles"
            if action == "prof_rename":
                return "profiles_rename"
            if action == "prof_signout":
                return "profiles_signout"
            if action == "prof_edit":
                return "profiles_edit"
            if action in ("prof_edit_label", "prof_edit_appleid", "prof_edit_password", "prof_edit_udid"):
                return "profiles"
            if action == "find_rescan":
                return "find_phone"
            if action == "signopts_mode_install":
                return "install_phone"
            return action
    return None

