def tr(key):
    d = TEXT.get(key, {})
    t = d.get(CUR_LANG, d.get("uk", key))
    if os.name != "nt" and isinstance(t, str):
        # Linux port: point leftover Windows mentions at Linux helpers.
        t = (t.replace("pair-helper\\build.bat", "pair-helper/build.sh")
              .replace("build.bat", "build.sh")
              .replace("start-bot.bat", "start-bot.sh")
              .replace("telegram-iloader-pair.exe", "telegram-iloader-pair")
              .replace("telegram-iloader-provision.exe", "telegram-iloader-provision")
              .replace("zsign.exe", "zsign")
              .replace("ipatool.exe", "ipatool"))
    return t


def _dpapi_blob(data, protect):
    """Windows DPAPI only (CryptProtectData / CryptUnprotectData,
    UI forbidden). Returns bytes or None. On any other system, or
    on any failure, returns None — the caller falls back to
    plaintext storage with an explicit warning, never silently."""
    try:
        import ctypes
        from ctypes import wintypes
        crypt32 = ctypes.windll.crypt32
        kernel32 = ctypes.windll.kernel32

        class DATA_BLOB(ctypes.Structure):
            _fields_ = [("cbData", wintypes.DWORD),
                        ("pbData", ctypes.POINTER(ctypes.c_byte))]

        buf = ctypes.create_string_buffer(data, len(data))
        in_blob = DATA_BLOB(len(data), ctypes.cast(buf, ctypes.POINTER(ctypes.c_byte)))
        out_blob = DATA_BLOB()
        fn = crypt32.CryptProtectData if protect else crypt32.CryptUnprotectData
        ok = fn(ctypes.byref(in_blob), None, None, None, None, 1, ctypes.byref(out_blob))
        if not ok:
            return None
        try:
            return bytes(bytearray(out_blob.pbData[:out_blob.cbData]))
        finally:
            kernel32.LocalFree(out_blob.pbData)
    except Exception:
        return None


def _dpapi_protect(data):
    return _dpapi_blob(data, True)


def _dpapi_unprotect(data):
    return _dpapi_blob(data, False)


def load_profiles():
    try:
        with open(PROFILES_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and isinstance(data.get("profiles"), list):
            return data["profiles"]
    except Exception:
        pass
    return []


def save_profiles(profiles):
    try:
        tmp = PROFILES_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"profiles": profiles}, f, ensure_ascii=False, indent=1)
        os.replace(tmp, PROFILES_PATH)
        try:
            os.chmod(PROFILES_PATH, 0o600)
        except Exception:
            pass
        return True
    except Exception:
        return False


def profile_password(profile):
    """(password or None, needs_reentry bool). Never logs anything."""
    if not profile:
        return None, False
    pw = profile.get("pw", "")
    if not pw:
        return None, True
    if profile.get("pw_enc"):
        raw = _dpapi_unprotect(base64.b64decode(pw))
        if raw is None:
            return None, True
        return raw.decode("utf-8", errors="replace"), False
    return pw, False


def store_password(password):
    """(stored_value, encrypted_bool). DPAPI on WINDOWS only: on
    Linux/Minish (no ctypes.windll) encryption is never available, so
    the value is kept in plain text with encrypted_bool False and every
    caller warns about it. Accepted risk there (a 0600 file, Minis runs
    one app per phone); do not describe it as encrypted."""
    enc = _dpapi_protect(password.encode("utf-8"))
    if enc is not None:
        return base64.b64encode(enc).decode(), True
    return password, False


def find_profile(profiles, pid):
    for p in profiles:
        if str(p.get("id")) == str(pid):
            return p
    return None


def find_profile_by_label(profiles, label):
    for p in profiles:
        if (p.get("label") or "").lower() == (label or "").lower():
            return p
    return None


def upsert_profile(apple_id, password, udid):
    """Save or update a profile by Apple ID. Returns
    (profile, was_existing, password_encrypted)."""
    profiles = load_profiles()
    existing = None
    for p in profiles:
        if (p.get("apple_id") or "").lower() == apple_id.lower() or \
                (not p.get("apple_id") and (p.get("label") or "").lower() == apple_id.lower()):
            existing = p
            break
    stored, enc = store_password(password)
    if existing:
        existing["apple_id"] = apple_id
        existing["udid"] = udid
        existing["pw"] = stored
        existing["pw_enc"] = enc
        save_profiles(profiles)
        return existing, True, enc
    nid = 1
    for p in profiles:
        try:
            nid = max(nid, int(p.get("id", 0)) + 1)
        except Exception:
            pass
    prof = {"id": nid, "label": apple_id, "apple_id": apple_id,
            "udid": udid, "pw": stored, "pw_enc": enc}
    profiles.append(prof)
    save_profiles(profiles)
    return prof, False, enc


def delete_profile(pid):
    profiles = load_profiles()
    kept = [p for p in profiles if str(p.get("id")) != str(pid)]
    if len(kept) == len(profiles):
        return False
    save_profiles(kept)
    return True


_API_TLS = threading.local()


class _StaleConn(Exception):
    """Keep-alive connection went stale before the request ran."""


def _drop_api_conn():
    conn = getattr(_API_TLS, "conn", None)
    _API_TLS.conn = None
    _API_TLS.uses = 0
    if conn is not None:
        try:
            conn.close()
        except Exception:
            pass


def _api_urllib(method, params):
    data = urllib.parse.urlencode(params).encode("utf-8")
    req = urllib.request.Request(API + "/" + method, data=data)
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        # Telegram returns the real reason in the error BODY, e.g.
        # {"ok": false, "description": "Bad Request: file is too big"}.
        # urlopen raises and discards it by default, which is why
        # earlier diagnostics only showed "HTTP Error 400".
        # Return the parsed body so callers can see the description.
        try:
            return json.loads(e.read().decode("utf-8", errors="ignore"))
        except Exception:
            raise


def _api_keepalive(method, params):
    """Same call over one persistent connection per thread.

    urllib opens a fresh TLS connection per call, which is what
    made idle taps intermittently slow. A stale pooled connection
    raises before the request runs; that one case is retried once
    on a fresh connection. Telegram/proxies also close an idle
    pooled TLS connection mid-read (ssl.SSLError /
    UNEXPECTED_EOF_WHILE_READING) — that is the same stale case
    and is retried once too. Anything else (e.g. a read timeout)
    propagates exactly like the urllib path: no silent resend.
    """
    parts = urllib.parse.urlparse(API)
    host = parts.hostname or "api.telegram.org"
    port = parts.port
    use_https = parts.scheme != "http"
    prefix = parts.path.rstrip("/")
    body = urllib.parse.urlencode(params).encode("utf-8")
    last_exc = None
    for _attempt in (0, 1):
        conn = getattr(_API_TLS, "conn", None)
        try:
            if conn is None:
                if use_https:
                    conn = http.client.HTTPSConnection(host, port, timeout=60)
                else:
                    conn = http.client.HTTPConnection(host, port, timeout=60)
                _API_TLS.conn = conn
                _API_TLS.uses = 0
            conn.request("POST", "%s/%s" % (prefix, method), body=body,
                         headers={"Content-Type": "application/x-www-form-urlencoded"})
            resp = conn.getresponse()
            data = resp.read()
            _API_TLS.uses = getattr(_API_TLS, "uses", 0) + 1
            if _API_TLS.uses > 200:
                _drop_api_conn()
            if resp.status != 200:
                try:
                    return json.loads(data.decode("utf-8", errors="ignore"))
                except Exception:
                    raise http.client.HTTPException("HTTP %s" % resp.status)
            return json.loads(data.decode("utf-8"))
        except (http.client.RemoteDisconnected, ConnectionResetError,
                BrokenPipeError, ssl.SSLError) as e:
            last_exc = e
            _drop_api_conn()
            continue
        except Exception:
            _drop_api_conn()
            raise
    raise _StaleConn(str(last_exc))


def api(method, **params):
    if LOCAL_ONLY or not BOT_TOKEN:
        return {"ok": False, "description": "local-only mode"}
    try:
        _res = _api_keepalive(method, params)
    except _StaleConn:
        # Stale pooled connection, already retried once: fall back
        # to a fresh urllib call, exactly the old behaviour.
        _res = _api_urllib(method, params)
    if method != "getUpdates":
        _dbg("api %s ok=%s" % (method, bool(isinstance(_res, dict) and _res.get("ok"))))
    return _res


def send_message(chat_id, text, reply_markup=None):
    try:
        params = {"chat_id": chat_id, "text": text}
        if reply_markup is not None:
            params["reply_markup"] = json.dumps(reply_markup, ensure_ascii=False)
        api("sendMessage", **params)
    except Exception as e:
        print("sendMessage failed: %s" % e, flush=True)


def send_html_message(chat_id, text):
    """sendMessage with parse_mode=HTML, no link preview. Used for
    tappable custom-scheme links (livecontainer://, sidestore://,
    altstore://): a text_link entity in the message body opens the
    URL through the OS, while an InlineKeyboardButton with the same
    URL is routed to the browser — the Bot API allows url buttons
    only for HTTP(S) or tg:// URLs, so a scheme link as a button
    lands in Safari instead of the target app (reported live
    2026-11-08: LiveContainer button -> browser)."""
    try:
        res = api("sendMessage", chat_id=chat_id, text=text,
                  parse_mode="HTML", disable_web_page_preview=True)
        return bool(isinstance(res, dict) and res.get("ok"))
    except Exception as e:
        print("sendHtmlMessage failed: %s" % e, flush=True)
        return False


def reply_kb(rows):
    # A row entry may be a plain label or a full KeyboardButton
    # dict (e.g. {"text": ..., "web_app": {"url": ...}} for the
    # SideBot KeyboardButton — see show_screen).
    def _btn(t):
        return t if isinstance(t, dict) else {"text": t}
    return {"keyboard": [[_btn(t) for t in row] for row in rows],
            "resize_keyboard": True}


def inline_kb(rows):
    return {"inline_keyboard": [[{"text": t, "callback_data": c} for (t, c) in row] for row in rows]}


def action_rows(actions, wide=False):
    step = 1 if wide else 2
    return [actions[i:i + step] for i in range(0, len(actions), step)]


def edit_inline(chat_id, message_id, text, actions, wide=False):
    try:
        res = api("editMessageText", chat_id=chat_id, message_id=message_id, text=text,
                  reply_markup=json.dumps(inline_kb(action_rows(actions, wide)), ensure_ascii=False))
        # api() returns the error body instead of raising, so an
        # ok:false reply (e.g. "message is not modified") must
        # count as failure, or the caller believes the edit stuck.
        return bool(isinstance(res, dict) and res.get("ok"))
    except Exception:
        return False


def send_inline(chat_id, text, actions, wide=False):
    try:
        res = api("sendMessage", chat_id=chat_id, text=text,
                  reply_markup=json.dumps(inline_kb(action_rows(actions, wide)), ensure_ascii=False))
        try:
            return res["result"]["message_id"]
        except Exception:
            return None
    except Exception as e:
        print("sendInline failed: %s" % e, flush=True)
        return None


def main_menu_text():
    return tr("menu_text")


_TOGGLEABLE_BTNS = (
    "miniapp", "menu_install", "ipatool", "appstore", "profiles", "menu_device",
    "prov", "siboot", "iloader", "refresh_install", "install_method",
    "programs", "appdata", "feather", "pair", "pairings", "anisette",
    "user_custom", "otaurl", "bridge", "status", "deps", "logs",
    "otafile", "botupdate", "admins", "commands", "ai", "lang",
    "widgets", "cancel", "hide_kbd",
)


def _hidden_btns():
    _h = _ms_get("hidden_buttons")
    return set(_h) if isinstance(_h, list) else set()


def _filter_menu(acts):
    _h = _hidden_btns()
    if not _h:
        return acts
    return [(lbl, act) for lbl, act in acts if act not in _h or act in ("menu", "menu_system", "menu_customize")]


def main_menu_actions():
    _acts = []
    if _tunnel_available():
        _acts.append((btn("miniapp"), "miniapp"))
    _acts += [
        (btn("menu_install"), "menu_install"),
        (btn("ipatool"), "ipatool"),
        (btn("appstore"), "appstore"),
        (btn("profiles"), "profiles"),
        (btn("menu_device"), "menu_device"),
        (btn("menu_system"), "menu_system"),
        (btn("hide_kbd"), "hide_kbd"),
    ]
    return _filter_menu(_acts)


def show_screen(chat_id, text, actions, via, message_id=None, wide=False):
    """One screen, both surfaces, same actions: via 'reply' sends
    the text with a Reply keyboard, via 'inline' edits the tapped
    message in place (or sends a new one when there is nothing to
    edit). The (message_id, text) guard stops a repeated tap on
    the same inline menu from duplicating it."""
    if via == "inline" and message_id:
        if job.get("last_screen") == (message_id, text):
            return
        if edit_inline(chat_id, message_id, text, actions, wide):
            job["last_screen"] = (message_id, text)
            return
        _mid = send_inline(chat_id, text, actions, wide)
        # The fallback message is the visible one: record ITS id,
        # or later edits (Back included) target the stale message
        # and the visible screen looks frozen.
        job["last_screen"] = (_mid or message_id, text)
        return
    if via == "inline":
        _mid = send_inline(chat_id, text, actions, wide)
        if _mid:
            job["last_screen"] = (_mid, text)
        return
    job["last_actions"] = {label: action for label, action in actions}
    _rows = action_rows(actions, wide)
    _murl = None
    _murl_appstore = None
    if any(a[1] in ("miniapp", "appstore") for _r in _rows for a in _r):
        # Mini App (web_app button) only when the tunnel is up:
        # without a public URL there is nothing to point it at.
        # Tapping the plain label first starts the tunnel (see
        # handle_action "miniapp"); the re-rendered menu then
        # carries the real web_app button. A KeyboardButton
        # launch is REQUIRED: Telegram delivers sendData to the
        # bot ONLY for keyboard-launched apps (the dead-buttons
        # bug, 2026-11-11) — an inline web_app button would open
        # the page but every command would silently die.
        try:
            _murl = _miniapp_url()
            _murl_appstore = _appstore_url()
            if _murl:
                _dbg("miniapp url len=%d base=%s" % (len(_murl), _murl[:64]))
        except Exception as _e:
            _dbg("miniapp_url err: %s" % _e)
            _murl = None
            _murl_appstore = None
    rows = []
    for _r in _rows:
        _row = []
        for _label, _act in _r:
            if _act == "miniapp" and _murl:
                _row.append({"text": _label, "web_app": {"url": _murl}})
            elif _act == "appstore" and _murl_appstore:
                _row.append({"text": _label, "web_app": {"url": _murl_appstore}})
            else:
                _row.append(_label)
        rows.append(_row)
    send_message(chat_id, text, reply_markup=reply_kb(rows))


def send_prompt(chat_id, text, via, message_id=None, actions=None):
    """An input prompt in the current surface, with only Cancel
    unless explicit actions are given (label, action) pairs."""
    if via == "inline":
        send_inline(chat_id, text, actions or [(btn("cancel"), "cancel")])
    else:
        send_message(chat_id, text, reply_markup=reply_kb(
            [[label] for label, _ in actions] if actions else [[btn("cancel")]]))


def send_document(chat_id, path, caption=""):
    if LOCAL_ONLY or not BOT_TOKEN:
        return {"ok": False, "description": "local-only mode"}
    # Streaming upload, not f.read() into RAM: the old code loaded
    # the whole IPA into memory, which made large files very slow
    # and could swap/hang the PC. Now the file is sent in 1 MB
    # chunks with a correct Content-Length, timeout 3600 s for
    # a 2000 MB file on a slow connection.
    # RETRY 2026-11-02: one retry on a transport drop mid-upload
    # (ssl.SSLError / RemoteDisconnected / reset / broken pipe --
    # the live UNEXPECTED_EOF_WHILE_READING failure). A fresh
    # connection is opened and the file is re-read from the start
    # on each attempt, so a half-sent first attempt cannot corrupt
    # the second. Telegram JSON errors (ok=False, e.g. file too
    # big) are NOT retried: the server received the request.
    # A retry after the response was lost can rarely deliver the
    # document twice; that is harmless and better than losing it.
    import http.client
    _last_exc = None
    try:
        boundary = "----telegram-iloader----"
        head = []
        head.append(("--%s\r\n" % boundary).encode())
        head.append(('Content-Disposition: form-data; name="chat_id"\r\n\r\n').encode())
        head.append(("%s\r\n" % chat_id).encode())
        if caption:
            head.append(("--%s\r\n" % boundary).encode())
            head.append(('Content-Disposition: form-data; name="caption"\r\n\r\n').encode())
            head.append((caption + "\r\n").encode())
        head.append(("--%s\r\n" % boundary).encode())
        head.append(('Content-Disposition: form-data; name="document"; filename="%s"\r\n' % os.path.basename(path)).encode())
        head.append(b"Content-Type: application/octet-stream\r\n\r\n")
        head_bytes = b"".join(head)
        foot_bytes = ("\r\n--%s--\r\n" % boundary).encode()
        file_size = os.path.getsize(path)
        total = len(head_bytes) + file_size + len(foot_bytes)
        parsed = urllib.parse.urlparse(BOT_API_BASE)
        host = parsed.hostname
        port = parsed.port or (443 if parsed.scheme == "https" else 80)
        conn_cls = http.client.HTTPSConnection if parsed.scheme == "https" else http.client.HTTPConnection
        for _attempt in (1, 2):
            _conn = None
            try:
                _conn = conn_cls(host, port, timeout=3600)
                _conn.putrequest("POST", parsed.path.rstrip("/") + "/bot%s/sendDocument" % BOT_TOKEN)
                _conn.putheader("Content-Type", "multipart/form-data; boundary=%s" % boundary)
                _conn.putheader("Content-Length", str(total))
                _conn.endheaders()
                _conn.send(head_bytes)
                with open(path, "rb") as f:
                    while True:
                        chunk = f.read(1024 * 1024)
                        if not chunk:
                            break
                        _conn.send(chunk)
                _conn.send(foot_bytes)
                resp = _conn.getresponse()
                data = resp.read()
                _conn.close()
                return json.loads(data.decode("utf-8"))
            except (ssl.SSLError, http.client.RemoteDisconnected,
                    ConnectionResetError, BrokenPipeError) as e:
                _last_exc = e
                try:
                    if _conn is not None:
                        _conn.close()
                except Exception:
                    pass
                if _attempt == 1:
                    _dbg("sendDocument retry attempt=%s err=%s" % (_attempt, type(e).__name__))
                    time.sleep(2)
                    continue
                break
            except Exception as e:
                _last_exc = e
                try:
                    if _conn is not None:
                        _conn.close()
                except Exception:
                    pass
                break
    except Exception as e:
        _last_exc = e
    print("sendDocument failed: %s" % _last_exc, flush=True)
    return None


LAST_GETFILE_ERROR = ""

def telegram_file_url(file_id):
    """Direct download URL of a file the bot sent, via getFile.
    NOTE: this URL contains BOT_TOKEN. Never print it, never log
    it, and warn the user never to forward the install link that
    embeds it. Returns None on failure."""
    global LAST_GETFILE_ERROR
    try:
        info = api("getFile", file_id=file_id)
        if not info.get("ok"):
            LAST_GETFILE_ERROR = str(info)
            print("getFile failed: %s" % info, flush=True)
            return None
        path = info["result"]["file_path"]
        return "%s/%s" % (FILE_API_BASE, path)
    except Exception as e:
        LAST_GETFILE_ERROR = str(e)
        print("getFile exception: %s" % e, flush=True)
        return None


def read_ipa_info(ipa_path):
    """(bundle_id, version, title) from the IPA's Info.plist.
    Returns (None, None, None) when the plist cannot be read."""
    try:
        with zipfile.ZipFile(ipa_path) as z:
            names = [n for n in z.namelist()
                     if n.startswith("Payload/") and n.count("/") == 2
                     and n.endswith(".app/Info.plist")]
            if not names:
                names = [n for n in z.namelist()
                         if n.startswith("Payload/") and n.endswith(".app/Info.plist")]
            if not names:
                return None, None, None
            info = plistlib.loads(z.read(names[0]))
        bundle_id = info.get("CFBundleIdentifier")
        version = info.get("CFBundleShortVersionString") or info.get("CFBundleVersion") or "1.0"
        title = info.get("CFBundleDisplayName") or info.get("CFBundleName")
        return bundle_id, version, title
    except Exception:
        return None, None, None


def read_signed_ipa_parts(ipa_path):
    """(bundle_id, profile_dict, error_text) from a signed IPA.

    profile_dict is the embedded.mobileprovision plist. The profile
    inside a signed IPA is a CMS-signed blob; the plist XML sits
    inside it, so it is extracted by byte search, never by running
    anything on it. error_text is None on success.
    """
    try:
        with zipfile.ZipFile(ipa_path) as z:
            names = z.namelist()
            app_prefix = None
            for n in names:
                if n.startswith("Payload/") and n.endswith(".app/Info.plist") and n.count("/") == 2:
                    app_prefix = n[: -len("Info.plist")]
                    break
            if app_prefix is None:
                for n in names:
                    if n.startswith("Payload/") and n.endswith(".app/Info.plist"):
                        app_prefix = n[: -len("Info.plist")]
                        break
            if app_prefix is None:
                return None, None, tr("l10n_ipa_no_plist")
            info = plistlib.loads(z.read(app_prefix + "Info.plist"))
            bundle_id = info.get("CFBundleIdentifier")
            prov_name = app_prefix + "embedded.mobileprovision"
            if prov_name not in names:
                return bundle_id, None, tr("l10n_ipa_no_mobileprov")
            blob = z.read(prov_name)
        start = blob.find(b"<?xml")
        end = blob.find(b"</plist>")
        if start < 0 or end < 0:
            return bundle_id, None, tr("ver_no_profile")
        prov = plistlib.loads(blob[start:end + len(b"</plist>")])
        return bundle_id, prov, None
    except Exception:
        return None, None, tr("l10n_ipa_open_fail")


def verify_signed_ipa(ipa_path, expected_bundle, expected_udid):
    """Check the signed IPA's embedded profile against the app and device.

    Returns (report_lines, ok): report_lines are Ukrainian strings for
    Telegram. Privacy: the UDID value is never printed, only whether
    it is present in the profile; the profile name and bundle ids are
    the app's own, not secrets.
    """
    bundle_id, prov, err = read_signed_ipa_parts(ipa_path)
    if err or prov is None:
        return ["❌ " + (err or tr("ver_no_profile"))], False
    lines = []
    ok = True
    if not bundle_id:
        lines.append("❌ " + tr("ver_no_bundle"))
        ok = False
    elif expected_bundle and bundle_id != expected_bundle:
        lines.append("❌ " + tr("ver_wrong_file") % (bundle_id, expected_bundle))
        ok = False
    else:
        lines.append("✅ " + tr("ver_app_in_ipa") % bundle_id)
    ent = prov.get("Entitlements") or {}
    app_id = ent.get("application-identifier") or ""
    app_id_bundle = app_id.split(".", 1)[1] if "." in app_id else app_id
    if bundle_id:
        if app_id_bundle != bundle_id and not app_id_bundle.startswith(bundle_id + "."):
            lines.append("❌ " + tr("ver_profile_wrong_app") % (app_id_bundle, bundle_id))
            ok = False
        else:
            lines.append("✅ " + tr("ver_profile_ok") % (app_id_bundle or "?"))
    devices = prov.get("ProvisionedDevices") or []
    if expected_udid:
        if expected_udid in devices:
            lines.append("✅ " + tr("ver_phone_in"))
        else:
            lines.append("❌ " + tr("ver_phone_not_in") % len(devices))
            ok = False
    exp = prov.get("ExpirationDate")
    if exp is not None:
        try:
            exp_utc = exp if exp.tzinfo else exp.replace(tzinfo=timezone.utc)
            if exp_utc <= datetime.now(timezone.utc):
                lines.append("❌ " + tr("ver_profile_expired") % exp.strftime("%Y-%m-%d"))
                ok = False
            else:
                lines.append("✅ " + tr("ver_profile_valid") % exp.strftime("%Y-%m-%d"))
        except Exception:
            lines.append(tr("l10n_prof_expiry_unknown"))
    # App Group check: LiveContainer requires an App Group, a free
    # Apple profile cannot contain one, and strict on-device
    # strict on-device signers refuse with "Development profile
    # must contain an App Group with a bundle ID". Our bot does
    # NOT fail on this: zsign signs with the profile's own
    # entitlements, so the bot never throws that error. This is
    # a warning only, and it does NOT block the install link:
    # a bot-signed IPA installed via USB/OTA can still work,
    # while the same p12+profile imported into another signer
    # will be refused again. For other signers, the free-account
    # path is SideStore's own LiveContainer, not the standalone IPA.
    # A paid Developer Program account is the only way to get
    # a profile that actually contains an App Group; isideload
    # exposes no App Group API, and Apple rejects App Group
    # capability for free accounts, so no code in this bot can
    # invent one.
    groups = ent.get("com.apple.security.application-groups") or ent.get("application-groups") or []
    if expected_bundle == "com.kdt.livecontainer":
        if groups:
            lines.append("✅ " + tr("ver_profile_groups") % ", ".join(groups))
        else:
            lines.append(tr("l10n_no_app_group"))
    pname = prov.get("Name")
    if pname:
        lines.append(tr("l10n_profile_line") % pname)
    return lines, ok


def _cert_team_from_subject(subj_text):
    """Team of a cert from its openssl subject line.

    Returns (team, cn_team, ou_team). Apple puts the selected team in
    the OU field; for multi-team certs the CN parens hold the personal
    team instead, so OU wins when present and the CN parens are only
    a fallback. Team is None when neither is found.
    """
    tm = re.search(r"\(([A-Z0-9]{10})\)", subj_text)
    cn_team = tm.group(1) if tm else None
    ou_m = re.search(r"\bOU\s*=\s*([A-Z0-9]{10})\b", subj_text)
    ou_team = ou_m.group(1) if ou_m else None
    return (ou_team or cn_team, cn_team, ou_team)


def verify_cert_binding(ipa_path, p12_path, p12_password):
    """Check the signing certificate against the embedded profile.

    iOS rejects an install when the cert used for signing is not listed
    in the profile's DeveloperCertificates, or belongs to another team
    than the profile. The p12 password goes to openssl via stdin only,
    never on a command line, never printed. Returns (report_lines, ok):
    when openssl is missing on Linux the check is skipped openly
    (ok=True) instead of blocking the link on a missing tool.
    """
    bundle_id, prov, err = read_signed_ipa_parts(ipa_path)
    if err or prov is None:
        return ["❌ " + tr("ver_cert_impossible_tpl") % (err or tr("ver_no_profile_dot"))], False
    if not p12_path or not os.path.exists(p12_path):
        return ["❌ " + tr("ver_cert_no_p12")], False
    # openssl location: PATH only on Linux.
    _openssl_cmd = shutil.which("openssl")  # Linux: PATH only (apk/pacman/apt: openssl).
    if _openssl_cmd is None:
        return [tr("l10n_cert_skip_openssl")], True
    try:
        pkcs12 = subprocess.run(
            [_openssl_cmd, "pkcs12", "-in", p12_path, "-nokeys", "-clcerts", "-passin", "stdin"],
            input=((p12_password or "") + "\n").encode(), capture_output=True, timeout=60)
        pem = pkcs12.stdout
        if pkcs12.returncode != 0 or b"BEGIN CERTIFICATE" not in pem:
            return ["❌ " + tr("ver_cert_read_fail")], False
        fp = subprocess.run(
            [_openssl_cmd, "x509", "-fingerprint", "-sha1", "-noout"],
            input=pem, capture_output=True, timeout=60)
        subj = subprocess.run(
            [_openssl_cmd, "x509", "-subject", "-noout"],
            input=pem, capture_output=True, timeout=60)
        fm = re.search(r"=([0-9A-Fa-f:]{59})", fp.stdout.decode("utf-8", errors="ignore"))
        if not fm:
            return ["❌ " + tr("ver_cert_fp_fail")], False
        fingerprint = fm.group(1).replace(":", "").lower()
        cert_team, cn_team, ou_team = _cert_team_from_subject(subj.stdout.decode("utf-8", errors="ignore"))
    except Exception:
        return ["❌ " + tr("ver_cert_failed")], False
    lines = []
    ok = True
    certs = prov.get("DeveloperCertificates") or []
    fps = set()
    for der in certs:
        try:
            fps.add(hashlib.sha1(bytes(der)).hexdigest())
        except Exception:
            pass
    if fingerprint in fps:
        lines.append("✅ " + tr("ver_cert_in_profile"))
    else:
        lines.append("❌ " + tr("ver_cert_not_in_profile") % len(certs))
        ok = False
    ent = prov.get("Entitlements") or {}
    app_id = ent.get("application-identifier") or ""
    prof_team = app_id.split(".", 1)[0] if "." in app_id else ""
    if cert_team and prof_team:
        if cn_team and ou_team and cn_team != ou_team:
            lines.append(tr("l10n_team_cn_ou") % (cn_team, ou_team))
        if cert_team == prof_team:
            lines.append("✅ " + tr("ver_cert_same_team") % cert_team)
        else:
            lines.append("❌ " + tr("ver_cert_team_mismatch") % (cert_team, prof_team))
            ok = False
    return lines, ok


