# LOCKDOWN INSTALL 2026-10-27: install a signed IPA from the PC
# directly via lockdown (USB / Wi-Fi, like 3uTools), no manifest,
# no HTTPS, no Telegram link. The signed IPA is already on Linux
# after signing, so the bot keeps a copy in last-signed.ipa before
# the job temp dir is deleted, and the install button uses that copy.
LAST_SIGNED = {"path": "", "bundle": "", "title": ""}


def save_last_signed(output_path, bundle="", title=""):
    try:
        dest = os.path.join(BASE_DIR, "last-signed.ipa")
        shutil.copyfile(output_path, dest)
        LAST_SIGNED["path"] = dest
        LAST_SIGNED["bundle"] = bundle or ""
        LAST_SIGNED["title"] = title or ""
        return dest
    except Exception as e:
        print("save_last_signed failed: %s" % e, flush=True)
        return ""


PAIRING_FILE_ENV = ENV.get("PAIRING_FILE", "").strip()


def pairing_candidates(udid=""):
    """Where an Apple Lockdown pairing record may live, in order.

    The record is created once by iTunes / Apple Mobile Device
    Service when the phone trusts the PC over USB. The bot only
    checks existence, kind and size -- it never reads the key
    material into a message, log or Telegram upload."""
    cands = []
    if PAIRING_FILE_ENV:
        cands.append(PAIRING_FILE_ENV)
    if udid:
        cands.append(os.path.join(BASE_DIR, "pairing", udid + ".plist"))
        cands.append(os.path.join(BASE_DIR, udid + ".plist"))
    cands.append(os.path.join(BASE_DIR, "pairing", "pairing.plist"))
    cands.append(os.path.join(BASE_DIR, "pairing.plist"))
    # Linux: usbmuxd / libimobiledevice system records + pymobiledevice3 homes.
    _home = os.path.expanduser("~")
    for _d in ("/var/lib/lockdown",
               os.path.join(_home, ".config", "libimobiledevice"),
               os.path.join(_home, ".local", "share", "pymobiledevice3"),
               os.path.join(_home, ".config", "pymobiledevice3")):
        if udid:
            cands.append(os.path.join(_d, udid + ".plist"))
        else:
            cands.append(os.path.join(_d, "pairing.plist"))
    for _base in (os.environ.get("ALLUSERSPROFILE", ""), os.environ.get("ProgramData", "")):
        if _base and udid:
            cands.append(os.path.join(_base, "Apple", "Lockdown", udid + ".plist"))
    return [c for c in cands if c]


def _pairing_kind(path):
    """'apple' = Apple Lockdown record, 'sidestore' = on-device
    .mobiledevicepairing file (different format, for SideStore),
    'unknown' = present but not recognisable. Only key names
    are inspected, never secret values."""
    if path.lower().endswith(".mobiledevicepairing"):
        return "sidestore"
    try:
        with open(path, "rb") as f:
            data = plistlib.load(f)
        keys = set(data.keys()) if isinstance(data, dict) else set()
        if "HostCertificate" in keys or "HostPrivateKey" in keys:
            return "apple"
        return "unknown"
    except Exception:
        return "unknown"


def find_pairing_file(udid=""):
    """(path, kind) or ('', ''). Without a UDID, scans the
    pairing/ folder and the system Lockdown folder for any
    record, so /status can report pairing before a profile
    is chosen."""
    for cand in pairing_candidates(udid):
        if cand and os.path.exists(cand):
            return cand, _pairing_kind(cand)
    if not udid:
        for _d in [os.path.join(BASE_DIR, "pairing")]:
            try:
                for _n in sorted(os.listdir(_d)):
                    if _n.lower().endswith((".plist", ".mobiledevicepairing")):
                        _p = os.path.join(_d, _n)
                        return _p, _pairing_kind(_p)
            except Exception:
                pass
        for _d in ["/var/lib/lockdown",
                   os.path.join(os.path.expanduser("~"), ".config", "libimobiledevice")]:
            try:
                for _n in sorted(os.listdir(_d)):
                    if _n.lower().endswith(".plist"):
                        _p = os.path.join(_d, _n)
                        return _p, _pairing_kind(_p)
            except Exception:
                pass
        for _base in (os.environ.get("ALLUSERSPROFILE", ""), os.environ.get("ProgramData", "")):
            _d = os.path.join(_base, "Apple", "Lockdown") if _base else ""
            try:
                for _n in sorted(os.listdir(_d)):
                    if _n.lower().endswith(".plist"):
                        _p = os.path.join(_d, _n)
                        return _p, _pairing_kind(_p)
            except Exception:
                pass
    return "", ""


INSTALLED_PATH = os.path.join(BASE_DIR, "installed_apps.json")


def load_installed():
    try:
        with open(INSTALLED_PATH, encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, list) else []
    except Exception:
        return []


def save_installed(records):
    try:
        tmp = INSTALLED_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(records, f, ensure_ascii=False, indent=1)
        os.replace(tmp, INSTALLED_PATH)
        return True
    except Exception:
        return False


def record_installed(bundle, title, source, profile_expires=""):
    """Remember one signed app so /refresh can re-sign + reinstall
    it a week later. source: {kind: preset|import, key, url,
    original_path}. Only metadata is stored -- no passwords,
    no p12, no profile contents."""
    if not bundle:
        return
    records = [r for r in load_installed() if r.get("bundle") != bundle]
    _src = dict(source or {})
    if job.get("original_path"):
        _src.setdefault("original_path", job.get("original_path"))
    rec = {
        "bundle": bundle,
        "title": title or bundle,
        "source": _src,
        "udid": job.get("udid", ""),
        "apple_id": job.get("apple_id", ""),
        "profile_id": job.get("profile_id", ""),
        "signed_at": datetime.now(timezone.utc).isoformat(),
        "profile_expires": profile_expires or "",
        "signed_path": LAST_SIGNED.get("path", ""),
    }
    records.append(rec)
    save_installed(records)


def save_original_ipa(input_path, bundle, title):
    """Keep the UNSIGNED original IPA for refresh: re-signing a
    signed IPA is wrong, and the job tmpdir is deleted after
    signing. Presets can be re-downloaded, but an uploaded /
    imported IPA has no other copy."""
    try:
        d = os.path.join(BASE_DIR, "originals")
        os.makedirs(d, exist_ok=True)
        safe = re.sub(r"[^A-Za-z0-9._-]", "", (bundle or title or "app").replace(" ", ""))
        dest = os.path.join(d, (safe or "app") + ".ipa")
        shutil.copyfile(input_path, dest)
        return dest
    except Exception as e:
        print("save_original_ipa failed: %s" % e, flush=True)
        return ""


def _dbg_mask_cmd(full):
    """Command list for _dbg with the UDID value masked to its tail:
    the full command is logged, the full UDID never is."""
    _out = list(full or [])
    for _i, _a in enumerate(_out):
        if _a == "--udid" and _i + 1 < len(_out):
            _out[_i + 1] = "…" + str(_out[_i + 1])[-4:]
    return _out


def _run_pmd(cmd, timeout=300, keep=900):
    """Run pymobiledevice3, via its exe if present, else via
    `python -m pymobiledevice3`. Returns (rc, output). keep = how
    many trailing characters to return (0 = all of it). The
    verify-after-install check needs the FULL `apps query` output:
    the bundle id sits near the START of the app's info dump, so a
    900-char tail made a successful install look 'NOT verified'."""
    exe = shutil.which("pymobiledevice3")
    full = ([exe] + cmd) if exe else ([sys.executable, "-m", "pymobiledevice3"] + cmd)
    if cmd and cmd[0] == "apps":
        _dbg("pmd request cmd=%s" % _dbg_mask_cmd(full))
    try:
        r = subprocess.run(full, capture_output=True, text=True, timeout=timeout)
        _out = (r.stdout or "") + "\n" + (r.stderr or "")
        if cmd and cmd[0] == "apps":
            _dbg("pmd response rc=%s out=%s" % (r.returncode, _out.replace("\n", " | ")))
        return r.returncode, (_out[-keep:] if keep else _out)
    except Exception as e:
        return -1, str(e)


def _append_full_log(title, text):
    """Keep the full pymobiledevice3 output in install-full-log.txt
    (the chat message and install-log.txt only keep the tail)."""
    try:
        _p = os.path.join(BASE_DIR, "install-full-log.txt")
        with open(_p, "a", encoding="utf-8") as _lf:
            _lf.write("%s %s\n%s\n---\n" % (datetime.now(timezone.utc).isoformat(), title, (text or "")[-20000:]))
        try:
            os.chmod(_p, 0o600)
        except OSError:
            pass
    except Exception:
        pass


def _rsd_bundle_present(bundle, addr, port, tries=6, delay=10):
    """Poll `apps query` over the RSD tunnel until the bundle shows
    up. iOS finishes an install asynchronously, so the app can
    appear a few seconds after the install command returns.
    Returns (present, output)."""
    last = ""
    for _i in range(tries):
        _rc, _out = _run_pmd(["apps", "query", bundle, "--rsd", addr, port], timeout=120, keep=0)
        last = _out
        _dbg("verify try=%s/%s rc=%s found=%s out=%s" % (_i + 1, tries, _rc, bundle in _out, _out.replace("\n", " | ")))
        if bundle in _out:
            return True, _out
        if _i < tries - 1:
            time.sleep(delay)
    return False, last


def _resolve_udid(udid=""):
    """Find the phone UDID when the current job has none. The
    install button after signing runs in a job that may not
    carry the UDID, and start-tunnel with two phones on the
    network then stops at the interactive chooser and exits
    ("Pass --udid ..."), which looked like a tunnel failure.
    Sources, in order: the given UDID, the current job, the
    most recent installed record, the pairing-file filename
    (<UDID>.plist). Returns '' when nothing is found."""
    if udid:
        return udid
    _u = job.get("udid", "") or ""
    if _u:
        return _u
    try:
        _recs = load_installed()
        if _recs:
            _u = _recs[-1].get("udid", "") or ""
            if _u:
                return _u
    except Exception:
        pass
    try:
        _path, _kind = find_pairing_file("")
        if _path:
            _stem = os.path.splitext(os.path.basename(_path))[0]
            if re.fullmatch(r"[0-9A-Fa-f]{8}-[0-9A-Fa-f]{16}|[0-9A-Fa-f]{40}", _stem):
                return _stem
            try:
                with open(_path, "rb") as _pf:
                    _pl = plistlib.load(_pf)
                for _k in ("UDID", "udid", "UniqueDeviceID"):
                    _val = str(_pl.get(_k) or "").strip()
                    if re.fullmatch(r"[0-9A-Fa-f]{8}-[0-9A-Fa-f]{16}|[0-9A-Fa-f]{40}", _val):
                        return _val
            except Exception:
                pass
    except Exception:
        pass
    try:
        _du = os.path.join(BASE_DIR, "device_udid.txt")
        if os.path.isfile(_du):
            _v = open(_du, "r", encoding="utf-8", errors="ignore").read().strip()
            if re.fullmatch(r"[0-9A-Fa-f]{8}-[0-9A-Fa-f]{16}|[0-9A-Fa-f]{40}", _v):
                return _v
    except Exception:
        pass
    return ""


_RSD_ADDR_RE = re.compile(r"RSD Address:\s*(\S+)")
_RSD_PORT_RE = re.compile(r"RSD Port:\s*(\d+)")
_RSD_OPT_RE = re.compile(r"--rsd\s+(\S+)\s+(\d+)")


def _start_rsd_tunnel(udid="", timeout=60):
    """Start `pymobiledevice3 remote start-tunnel -t wifi` and wait
    for its RSD address/port. Returns (proc, addr, port, log) or
    (None, '', '', log) when it never becomes usable. --udid is
    passed so the interactive device chooser never appears (it
    appeared even with one device). stdin is DEVNULL for the same
    reason: a chooser must fail fast, not hang the bot. The
    tunnel process must stay alive while install/query run; the
    caller stops it with _stop_rsd_tunnel. On Linux the tunnel
    creates a network interface and needs administrator rights."""
    exe = shutil.which("pymobiledevice3")
    full = ([exe] if exe else [sys.executable, "-m", "pymobiledevice3"]) + [
        "remote", "start-tunnel", "-t", "wifi"]
    if udid:
        full += ["--udid", udid]
    _env = dict(os.environ)
    if udid:
        _env["PYMOBILEDEVICE3_UDID"] = udid
    _lines = []
    _state = {"addr": "", "port": ""}

    def _reader():
        try:
            for _line in proc.stdout:
                _lines.append(_line.rstrip("\n"))
                _dbg("rsd-cli: %s" % _line.rstrip("\n"))
                _m = _RSD_ADDR_RE.search(_line)
                if _m:
                    _state["addr"] = _m.group(1)
                _m = _RSD_PORT_RE.search(_line)
                if _m:
                    _state["port"] = _m.group(1)
                _m = _RSD_OPT_RE.search(_line)
                if _m and not _state["addr"]:
                    _state["addr"] = _m.group(1)
                    _state["port"] = _m.group(2)
        except Exception:
            pass

    _dbg("rsd-cli request cmd=%s" % _dbg_mask_cmd(full))
    try:
        proc = subprocess.Popen(full, stdout=subprocess.PIPE,
                                stderr=subprocess.STDOUT,
                                stdin=subprocess.DEVNULL,
                                text=True, bufsize=1, env=_env)
    except Exception as e:
        return None, "", "", str(e)
    _t = threading.Thread(target=_reader, daemon=True)
    _t.start()
    _deadline = time.time() + timeout
    while time.time() < _deadline:
        if _state["addr"] and _state["port"]:
            return proc, _state["addr"], _state["port"], "\n".join(_lines)
        if proc.poll() is not None:
            _t.join(timeout=2)
            return None, "", "", "\n".join(_lines)[-600:]
        time.sleep(0.2)
    _stop_rsd_tunnel(proc)
    _t.join(timeout=2)
    return None, "", "", "\n".join(_lines)[-600:] or "rsd tunnel timed out"


def _stop_rsd_tunnel(proc):
    try:
        proc.terminate()
        proc.wait(timeout=5)
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass


def _start_direct_tunnel(udid="", host="", timeout=90):
    """Start direct_tunnel.py: the RSD tunnel WITHOUT Bonjour
    _remotepairing discovery. The helper connects straight to the
    phone's RemotePairing service at (host, 49152) -- or, with no
    host, to every address the phone advertises via mobdev2, IPv4
    first -- using the stored pairing record, then prints the same
    RSD Address/Port markers as the stock CLI and stays alive.
    Same return contract as _start_rsd_tunnel. stdin DEVNULL so
    nothing can hang on a prompt. Returns (proc, addr, port, log)
    or (None, '', '', log)."""
    if not udid or not os.path.exists(DIRECT_TUNNEL_PY):
        return None, "", "", "direct tunnel unavailable (no UDID or no direct_tunnel.py)"
    full = [sys.executable, DIRECT_TUNNEL_PY, "--udid", udid]
    if host:
        full += ["--host", host]
    _env = dict(os.environ)
    _env["PYMOBILEDEVICE3_UDID"] = udid
    _lines = []
    _state = {"addr": "", "port": ""}

    def _reader():
        try:
            for _line in proc.stdout:
                _lines.append(_line.rstrip("\n"))
                _dbg("direct: %s" % _line.rstrip("\n"))
                _m = _RSD_ADDR_RE.search(_line)
                if _m:
                    _state["addr"] = _m.group(1)
                _m = _RSD_PORT_RE.search(_line)
                if _m:
                    _state["port"] = _m.group(1)
                _m = _RSD_OPT_RE.search(_line)
                if _m and not _state["addr"]:
                    _state["addr"] = _m.group(1)
                    _state["port"] = _m.group(2)
        except Exception:
            pass

    _dbg("direct request cmd=%s" % _dbg_mask_cmd(full))
    try:
        proc = subprocess.Popen(full, stdout=subprocess.PIPE,
                                stderr=subprocess.STDOUT,
                                stdin=subprocess.DEVNULL,
                                text=True, bufsize=1, env=_env)
    except Exception as e:
        return None, "", "", str(e)
    _t = threading.Thread(target=_reader, daemon=True)
    _t.start()
    _deadline = time.time() + timeout
    while time.time() < _deadline:
        if _state["addr"] and _state["port"]:
            return proc, _state["addr"], _state["port"], "\n".join(_lines)
        if proc.poll() is not None:
            _t.join(timeout=2)
            return None, "", "", "\n".join(_lines)[-600:]
        time.sleep(0.2)
    _stop_rsd_tunnel(proc)
    _t.join(timeout=2)
    return None, "", "", "\n".join(_lines)[-600:] or "direct tunnel timed out"


def _bridge_tailnet_ip():
    """Phone tailnet IP from the captured bridge config, or ''."""
    try:
        _script, _config, _log = _resolve_bridge_paths()
        if not _config or not os.path.exists(_config):
            return ""
        with open(_config, encoding="utf-8") as _f:
            return str(json.load(_f).get("phone_tailnet_ip", "") or "").strip()
    except Exception:
        return ""


def _bridge_tailnet_ips():
    """Candidate phone tailnet IPs, in try order. The bridge config
    holds one phone_tailnet_ip (IPv4 on the current captures); the
    phone's Tailscale IPv6 -- the address a working direct-tailnet
    tunnel reports, e.g. fdfc:240b:fea4::1 -- is resolved from
    `tailscale status --json` by matching the peer that owns the
    config IPv4, or read from an optional phone_tailnet_ipv6 field
    in the config. Never raises; [] when nothing is known. The
    IPv6 attempt matters on the road: IPv4 to :49152 can time out
    while the same phone answers over its tailnet IPv6."""
    _ips = []
    _cfg_ip = ""
    _cfg_v6 = ""
    try:
        _script, _config, _log = _resolve_bridge_paths()
        if _config and os.path.exists(_config):
            with open(_config, encoding="utf-8") as _f:
                _cfg = json.load(_f)
            _cfg_ip = str(_cfg.get("phone_tailnet_ip", "") or "").strip()
            _cfg_v6 = str(_cfg.get("phone_tailnet_ipv6", "") or "").strip()
    except Exception:
        pass
    if _cfg_ip:
        _ips.append(_cfg_ip)
    if _cfg_v6 and _cfg_v6 not in _ips:
        _ips.append(_cfg_v6)
    if _cfg_ip and ":" not in _cfg_ip:
        try:
            _tailscale = shutil.which("tailscale")
            if _tailscale:
                _r = subprocess.run([_tailscale, "status", "--json"],
                                    capture_output=True, text=True, timeout=10)
                _peers = (json.loads(_r.stdout or "{}").get("Peer") or {})
                for _peer in _peers.values():
                    _addrs = _peer.get("TailscaleIPs") or []
                    if _cfg_ip in _addrs:
                        for _a in _addrs:
                            _a = str(_a).strip()
                            if ":" in _a and _a not in _ips:
                                _ips.append(_a)
                        break
        except Exception:
            pass
    return _ips


def _start_tunnel_any(udid=""):
    """RSD tunnel by any working path. Order: (0) stock CLI over
    Bonjour discovery (proven 2026-10-27); (1) direct tunnel to the
    addresses the phone advertises via mobdev2 -- no _remotepairing
    announcement needed; (2) direct tunnel to the phone's tailnet IPs
    through the bridge relay (remote case, bridge must be running):
    the config IPv4 first, then the phone's Tailscale IPv6.
    Returns (proc, addr, port, log, via, pair_suspect); via is
    'cli', 'direct' or 'direct-tailnet'. pair_suspect is True when
    a reachable phone rejected the pairing record (direct helper
    pair-mismatch / terminated-abruptly) -- the fix is re-pairing,
    not another tunnel attempt. The caller stops the process with
    _stop_rsd_tunnel. All three paths feed the same install/query
    code, so a tunnel built any way is verified the same way."""
    if MINIS_MODE:
        return None, "", "", "minis: pymobiledevice3 tunnel needs TUN/root, not available in Minis - use the Rust install-helper to 10.7.0.1", "", False
    udid = _resolve_udid(udid)
    _dbg("tunnel start udid_tail=%s" % udid[-4:])
    _logs = []
    _dbg("tunnel try cli")
    proc, addr, port, log = _start_rsd_tunnel(udid)
    if proc is not None:
        _dbg("tunnel cli ok addr=%s port=%s" % (addr, port))
        return proc, addr, port, log, "cli", False
    _logs.append(log or "")
    _dbg("tunnel cli failed log=%s" % (log or "").replace("\n", " | "))
    _dbg("tunnel try direct")
    proc, addr, port, log = _start_direct_tunnel(udid)
    if proc is not None:
        _dbg("tunnel direct ok addr=%s port=%s" % (addr, port))
        return proc, addr, port, log, "direct", False
    _logs.append(log or "")
    _dbg("tunnel direct failed log=%s" % (log or "").replace("\n", " | "))
    _bstate = _bridge_state()[0]
    if _bstate == "running":
        _tips = _bridge_tailnet_ips()
        _dbg("tunnel try direct-tailnet hosts=%s" % _tips)
        for _tip in _tips:
            proc, addr, port, log = _start_direct_tunnel(udid, host=_tip)
            if proc is not None:
                _dbg("tunnel direct-tailnet ok host=%s addr=%s port=%s" % (_tip, addr, port))
                return proc, addr, port, log, "direct-tailnet", False
            _logs.append(log or "")
            _dbg("tunnel direct-tailnet host=%s failed log=%s" % (_tip, (log or "").replace("\n", " | ")))
    else:
        _dbg("tunnel direct-tailnet skipped bridge=%s" % _bstate)
    _combined = "\n".join(_logs)
    _dbg("tunnel all failed log=%s" % _combined.replace("\n", " | "))
    _suspect = ("DIRECT_PAIR_SUSPECT" in _combined or "pair-mismatch" in _combined
                or "terminated abruptly" in _combined)
    return None, "", "", _combined[-600:], "", _suspect


def install_via_rsd_tunnel(ipa_path, udid="", bundle=""):
    """Install over the RSD tunnel (iOS 17+): start the tunnel,
    install with --developer --rsd, then VERIFY with apps query
    over the same tunnel before reporting success. A bare
    returncode 0 is not proof -- earlier Wi-Fi installs reported
    success while the app never appeared on the phone. Returns
    (ok, details). The tunnel is always stopped before return."""
    udid = _resolve_udid(udid)
    proc, addr, port, log, via, pair_suspect = _start_tunnel_any(udid)
    _dbg("rsd tunnel via=%s addr=%s port=%s" % (via, addr, port))
    if proc is None:
        return False, "rsd-tunnel: " + (log or "no RSD address/port")[-240:], pair_suspect, False
    _pfx = "direct" if via != "cli" else "rsd"
    try:
        rc, out = _run_pmd(["apps", "install", ipa_path, "--developer",
                            "--rsd", addr, port], timeout=300, keep=6000)
        _dbg("rsd install rc=%s" % rc)
        _dbg("rsd install out=%s" % out.replace("\n", " | "))
        _append_full_log("rsd-install rc=%s" % rc, out)
        if rc != 0:
            # A non-zero exit does not always mean the install failed
            # (it can fail while printing the result). Ask the phone.
            if bundle:
                _present, _o2 = _rsd_bundle_present(bundle, addr, port, tries=3, delay=8)
                if _present:
                    return True, _pfx + ": the install command returned an error, but the app IS on the phone. Error tail: " + out[-160:], False, False
            return False, "rsd-install: " + out[-240:], False, False
        if not bundle:
            return True, _pfx + ": " + out[-400:], False, False
        _present, out2 = _rsd_bundle_present(bundle, addr, port)
        _dbg("rsd verify present=%s bundle=%s" % (_present, bundle))
        if _present:
            return True, _pfx + ": " + out[-300:] + " | verify: found on phone", False, False
        _dbg("rsd verify out=%s" % out2.replace("\n", " | "))
        _append_full_log("verify failed for %s" % bundle, out2)
        # installd accepted the package but the verify query did
        # not see it (tunnel closed, slow registration). The app
        # is most likely installed -- report it honestly instead
        # of a flat failure (proven live 2026-10-28 over the
        # tailnet bridge: installed, bot said "failed").
        return False, _pfx + ": installed but NOT verified on phone (full output in install-full-log.txt): " + out2[-300:], False, True
    finally:
        _stop_rsd_tunnel(proc)


def install_via_lockdown(ipa_path, udid="", bundle=""):
    """Install via pymobiledevice3. Order: (0) RSD tunnel over
    Wi-Fi -- the only path proven on iOS 27, with verify-after-
    install; (1) Bonjour/mobdev2 Wi-Fi; (2) USB fallback;
    (3) ideviceinstaller. --developer is required for a
    developer package. Returns (ok, details, pair_suspect,
    unverified): pair_suspect is True when a reachable phone
    rejected the pairing record -- re-pairing (/repair) is the
    fix, not another install attempt. unverified is True when
    the RSD install went through but the verify query did not
    see the app -- the app is most likely installed, so the
    caller must report it honestly and NOT run the fallbacks
    (their failure noise would bury the installed fact)."""
    if not ipa_path or not os.path.exists(ipa_path):
        return False, "signed file not found on PC", False, False
    udid = _resolve_udid(udid)
    errors = []
    # 0. RSD tunnel (iOS 17+): proven 2026-10-27 -- the legacy
    # direct connection on port 62078 and --mobdev2 both fail
    # on iOS 27, the RSD tunnel answers installation_proxy
    # over Wi-Fi. Verified inside.
    _ok, _det, _suspect, _unv = install_via_rsd_tunnel(ipa_path, udid, bundle)
    if _ok:
        return True, _det, False, False
    if _unv:
        return False, _det, _suspect, True
    errors.append(_det)
    # 1. Wi-Fi: Bonjour/mobdev2 discovery, developer pkg.
    _cmd = ["apps", "install", ipa_path, "--developer", "--mobdev2"]
    if udid:
        _cmd += ["--udid", udid]
    rc, out = _run_pmd(_cmd)
    _dbg("install wifi rc=%s out=%s" % (rc, out.replace("\n", " | ")))
    if rc == 0:
        return True, "wifi: " + out, False, False
    errors.append("wifi: " + out)
    # 2. USB fallback: same command, usbmux discovery. The goal
    # remains Wi-Fi; no cable is required for attempts 0-1.
    _cmd = ["apps", "install", ipa_path, "--developer"]
    if udid:
        _cmd += ["--udid", udid]
    rc, out = _run_pmd(_cmd)
    _dbg("install usb rc=%s out=%s" % (rc, out.replace("\n", " | ")))
    if rc == 0:
        return True, "usb: " + out, False, False
    errors.append("usb: " + out)
    # 3. ideviceinstaller (libimobiledevice, USB only, if present).
    _idev = shutil.which("ideviceinstaller")
    if _idev:
        try:
            _cmd = [_idev, "-i", ipa_path]
            if udid:
                _cmd += ["-u", udid]
            r = subprocess.run(_cmd, capture_output=True, text=True, timeout=300)
            _out = ((r.stdout or "") + "\n" + (r.stderr or ""))[-900:]
            _dbg("install ideviceinstaller rc=%s out=%s" % (r.returncode, _out.replace("\n", " | ")))
            if r.returncode == 0:
                return True, "ideviceinstaller: " + _out, False, False
            errors.append("ideviceinstaller: " + _out)
        except Exception as e:
            errors.append("ideviceinstaller: %s" % e)
    # Cap EACH attempt, not the joined tail: on 2026-10-27 the
    # joined [-900:] cut off the first (RSD) attempt entirely,
    # so its reason never reached Telegram and the RSD hint
    # check never fired. The RSD reason must survive.
    return False, " | ".join(e[-280:] for e in errors)[-900:], _suspect, False


def check_phone_apps(udid="", bundle=""):
    """Ask the phone itself, via pymobiledevice3 apps query, whether
    bundle is installed. Returns (found, output). A bot 'installed'
    message alone is not proof -- pymobiledevice3 may exit 0 with
    no output, or install to a different/placeholder target."""
    if not bundle:
        return False, "no bundle"
    # 0. RSD tunnel: the only path that reaches the phone on iOS 27
    # (--mobdev2 / USB below fail with "Device is not connected").
    try:
        _proc, _addr, _port, _tlog, _via, _sus = _start_tunnel_any(_resolve_udid(udid))
    except Exception:
        _proc = None
    if _proc is not None:
        try:
            _present, _o = _rsd_bundle_present(bundle, _addr, _port, tries=1, delay=0)
            return _present, _o[-600:]
        finally:
            _stop_rsd_tunnel(_proc)
    for _extra in (["--mobdev2"], []):
        _cmd = ["apps", "query", bundle] + _extra
        if udid:
            _cmd += ["--udid", udid]
        rc, out = _run_pmd(_cmd, timeout=120, keep=0)
        if bundle in out:
            return True, out[-600:]
        if rc == 0 and out.strip():
            return False, out[-600:]
    rc, out = _run_pmd(["apps", "query", bundle] + (["--udid", udid] if udid else []), timeout=120, keep=0)
    return False, out[-600:]


def _pairing_dir():
    return os.path.join(BASE_DIR, "pairing")


def _list_pairings():
    """Pairing files the pair helper saved on Linux. Only *.plist
    inside pairing/; kind from the filename (.remote. = Remote
    pairing, anything else = Lockdown)."""
    _d = _pairing_dir()
    _out = []
    try:
        for _name in sorted(os.listdir(_d)):
            if not _name.endswith(".plist"):
                continue
            _p = os.path.join(_d, _name)
            if not os.path.isfile(_p):
                continue
            _st = os.stat(_p)
            _out.append({"name": _name, "path": _p,
                         "kind": "Remote" if ".remote." in _name else "Lockdown",
                         "size": _st.st_size,
                         "mtime": datetime.fromtimestamp(_st.st_mtime, tz=timezone.utc).strftime("%Y-%m-%d %H:%M")})
    except Exception:
        pass
    return _out


def _list_logs():
    """Log files the bot and its helpers write on Linux: the five
    in the bot folder plus bridge-log.txt next to the bridge
    script (usually the same folder -- deduped by path). Only
    these fixed names are ever listed or sent."""
    _names = ["install-log.txt", "pair-log.txt", "repair-log.txt",
              "stage-log.txt", "ota-access-log.txt"]
    _seen = set()
    _out = []
    _cands = [os.path.join(BASE_DIR, _n) for _n in _names]
    try:
        _script, _config, _log = _resolve_bridge_paths()
        if _log:
            _cands.append(_log)
    except Exception:
        pass
    for _p in _cands:
        _ap = os.path.abspath(_p)
        if _ap in _seen:
            continue
        _seen.add(_ap)
        if not os.path.isfile(_p):
            continue
        _st = os.stat(_p)
        _out.append({"name": os.path.basename(_p), "path": _p,
                     "size": _st.st_size,
                     "mtime": datetime.fromtimestamp(_st.st_mtime, tz=timezone.utc).strftime("%Y-%m-%d %H:%M")})
    return sorted(_out, key=lambda d: d["name"])


def _send_pairing_file(chat_id, path):
    """Send one pairing file to the owner chat with the warning
    caption. Owner-only: the caller chain is owner-gated, and the
    path must stay inside pairing/. Returns True when Telegram
    accepted the upload."""
    try:
        if os.path.abspath(path).startswith(os.path.abspath(_pairing_dir()) + os.sep) and os.path.isfile(path):
            _res = send_document(chat_id, path, tr("pairing_file_caption") % os.path.basename(path))
            return isinstance(_res, dict) and bool(_res.get("ok"))
    except Exception:
        pass
    return False


_UDID_RE = re.compile(r"[0-9A-Fa-f]{8}-[0-9A-Fa-f]{16}|[0-9A-Fa-f]{40}")
_APPLE_PAIR_KEYS = {"DeviceCertificate", "HostCertificate", "HostPrivateKey",
                    "RootCertificate", "EscrowBag", "SystemBUID", "HostID", "WiFiMACAddress"}
_RP_PAIR_KEYS = {"identifier", "Identifier", "public_key", "PublicKey",
                 "private_key", "PrivateKey", "publicKey", "privateKey"}


def _analyze_pairing_bytes(data, filename=""):
    """Inspect pairing-file bytes and report ONLY metadata: kind,
    UDID, UDID source and key NAMES -- never values. kind is
    'lockdown' (Apple certificate record), 'rp' (RPPairing bytes
    from the Rust helper / SideStore family), 'plist' (a plist
    that is neither) or 'binary' (not a plist at all). UDID comes
    from the record content first, the file name second."""
    _keys = set()
    _udid = ""
    _kind = "binary"
    _top = None
    try:
        _top = plistlib.loads(data)
    except Exception:
        _top = None
    if isinstance(_top, dict):
        _d = _top
        if not (_APPLE_PAIR_KEYS & set(_d)) and not (_RP_PAIR_KEYS & set(_d)):
            for _v in _d.values():
                if isinstance(_v, dict) and ((_APPLE_PAIR_KEYS | _RP_PAIR_KEYS) & set(_v)):
                    _d = _v
                    break
        _keys = set(_d.keys())
        for _k in ("UDID", "UniqueDeviceID"):
            _v = _d.get(_k)
            if isinstance(_v, str) and _UDID_RE.fullmatch(_v.strip()):
                _udid = _v.strip()
                break
        if _APPLE_PAIR_KEYS & _keys:
            _kind = "lockdown"
        elif _RP_PAIR_KEYS & _keys:
            _kind = "rp"
        else:
            _kind = "plist"
    elif _top is not None:
        _kind = "plist"
    _src = "content" if _udid else ""
    if not _udid and filename:
        _m = _UDID_RE.search(os.path.basename(filename))
        if _m:
            _udid = _m.group(0)
            _src = "filename"
    return {"kind": _kind, "udid": _udid, "udid_source": _src, "keys": sorted(_keys)}


def _pmd3_config_dir():
    """Where pymobiledevice3 keeps its records, including the
    remote_<UDID>.plist its Wi-Fi discovery reads. On the PC this
    is ~/.pymobiledevice3 (proven by the records `remote
    pair-host` / `lockdown remotepairing --pair` created there)."""
    return os.path.join(os.path.expanduser("~"), ".pymobiledevice3")


def _backup_existing(path):
    """Move an existing file aside with a timestamped .bak name.
    Returns the backup path, or '' when nothing was there."""
    if not os.path.exists(path):
        return ""
    _bak = "%s.bak-%s" % (path, datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S"))
    os.replace(path, _bak)
    return _bak


def _place_pairing_record(data, info, orig_name):
    """Write the received bytes where each tool expects them.
    pairing/ always gets a normalized copy. The pymobiledevice3
    config dir gets remote_<UDID>.plist ONLY for a full Lockdown
    record whose UDID came from the content itself -- an
    RPPairing file is a different format and must never be
    passed off as that record. Existing targets are backed up,
    never silently overwritten. Returns (placed, backups):
    display strings only, no content."""
    _udid = info["udid"]
    _placed, _backups = [], []
    os.makedirs(_pairing_dir(), exist_ok=True)
    if _udid and info["kind"] in ("lockdown", "rp", "plist"):
        _name = _udid + (".remote.plist" if info["kind"] == "rp" else ".plist")
    else:
        _safe = re.sub(r"[^A-Za-z0-9._-]+", "_", os.path.basename(orig_name) or "pairing-file")
        _name = "received-" + datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S") + "-" + _safe
        if not _name.endswith((".plist", ".mobiledevicepairing")):
            _name += ".plist"
    _dest = os.path.join(_pairing_dir(), _name)
    _bak = _backup_existing(_dest)
    if _bak:
        _backups.append((os.path.basename(_dest), os.path.basename(_bak)))
    with open(_dest, "wb") as f:
        f.write(data)
    _placed.append("pairing/" + _name)
    if MINIS_MODE and info["kind"] in ("rp", "lockdown", "plist"):
        try:
            os.makedirs(SIBOOT_HOME, exist_ok=True)
            os.chmod(SIBOOT_HOME, 0o700)
            _sb_target = os.path.join(SIBOOT_HOME, "rp_pairing_file.plist")
            _sb_bak = _backup_existing(_sb_target)
            if _sb_bak:
                _backups.append((os.path.basename(_sb_target), os.path.basename(_sb_bak)))
            with open(_sb_target, "wb") as f:
                f.write(data)
            _placed.append(".siboot/rp_pairing_file.plist")
        except Exception:
            pass
    if info["kind"] == "lockdown" and _udid and info["udid_source"] == "content":
        _d = _pmd3_config_dir()
        os.makedirs(_d, exist_ok=True)
        _target = os.path.join(_d, "remote_%s.plist" % _udid)
        _bak = _backup_existing(_target)
        if _bak:
            _backups.append((os.path.basename(_target), os.path.basename(_bak)))
        with open(_target, "wb") as f:
            f.write(data)
        _placed.append("pymobiledevice3: remote_%s.plist" % _udid)
    return _placed, _backups


def _place_own_pairing_record(data, info):
    """Owner replacing HIS OWN record: write it where the tunnel
    actually reads it. Unlike _place_pairing_record (which never
    passes an RPPairing file off as the pymobiledevice3 record),
    this is the owner's own remote_<UDID>.plist created by
    `pymobiledevice3 remote pair-host` on his PC -- that file IS
    the pymobiledevice3 record, so it belongs in
    ~/.pymobiledevice3/remote_<UDID>.plist as well as in
    pairing/. The caller already verified the UDID matches the
    bot's phone and the record holds its private key. Existing
    targets are backed up, never silently overwritten. Returns
    (placed, backups): display strings only, no content."""
    _udid = info["udid"]
    _placed, _backups = [], []
    os.makedirs(_pairing_dir(), exist_ok=True)
    _name = _udid + (".remote.plist" if info["kind"] == "rp" else ".plist")
    _dest = os.path.join(_pairing_dir(), _name)
    _bak = _backup_existing(_dest)
    if _bak:
        _backups.append((os.path.basename(_dest), os.path.basename(_bak)))
    with open(_dest, "wb") as f:
        f.write(data)
    _placed.append("pairing/" + _name)
    _d = _pmd3_config_dir()
    os.makedirs(_d, exist_ok=True)
    _target = os.path.join(_d, "remote_%s.plist" % _udid)
    _bak = _backup_existing(_target)
    if _bak:
        _backups.append((os.path.basename(_target), os.path.basename(_bak)))
    with open(_target, "wb") as f:
        f.write(data)
    _placed.append("pymobiledevice3: remote_%s.plist" % _udid)
    return _placed, _backups


def _looks_like_pairing_file(name):
    """File names that can only be pairing files, for the
    forward-without-a-button fallback. Manifests, IPAs and
    profiles never match."""
    _n = os.path.basename(name or "").lower()
    return (_n.endswith(".remote.plist") or _n.endswith(".mobiledevicepairing")
            or _n == "pairingfile.plist" or _n == "rp_pairing_file.plist" or "altpairingfile" in _n
            or (_n.startswith("remote_") and _n.endswith(".plist")))


def _parse_ios_version(text):
    try:
        _parts = str(text or "").strip().split(".")
        return (int(_parts[0]), int(_parts[1]) if len(_parts) > 1 else 0)
    except Exception:
        return None


def _run_probe_handshake(addr, port, timeout=60):
    """Run probe_handshake.py over the live RSD tunnel. Returns
    (ok, values, error): values holds name/ios/model/udid strings
    only -- no record bytes ever come back through here."""
    if not os.path.exists(PROBE_HANDSHAKE_PY):
        return False, {}, "no probe_handshake.py next to the bot"
    try:
        r = subprocess.run([sys.executable, PROBE_HANDSHAKE_PY,
                            "--rsd-addr", addr, "--rsd-port", str(port)],
                           capture_output=True, text=True, timeout=timeout)
    except Exception as e:
        return False, {}, str(e)
    _out = (r.stdout or "") + "\n" + (r.stderr or "")
    for _line in _out.splitlines():
        if _line.startswith("PROBE_OK "):
            try:
                _vals = json.loads(_line[len("PROBE_OK "):].strip())
                if isinstance(_vals, dict):
                    return True, {k: str(v) for k, v in _vals.items()}, ""
            except Exception:
                pass
    _errs = [l for l in _out.splitlines() if l.startswith("PROBE_ERROR:")]
    if _errs:
        return False, {}, _errs[-1][len("PROBE_ERROR: "):].strip()[-200:]
    return False, {}, (_out.strip()[-200:] or "probe failed")


def _list_usb_udids():
    """UDIDs of phones on USB, from `pymobiledevice3 usbmux list`.
    Tolerant parse: only UDID-shaped tokens count, so a missing
    subcommand or an unexpected table layout yields [] instead
    of a crash. No trust needed for the listing itself."""
    rc, out = _run_pmd(["usbmux", "list"], timeout=30)
    if rc != 0:
        return []
    found = []
    for line in (out or "").splitlines():
        for m in _UDID_RE.finditer(line):
            u = m.group(0)
            if u not in found:
                found.append(u)
    return found


def _list_record_udids():
    """UDIDs known from pairing records on Linux: pairing/*.plist
    and ~/.pymobiledevice3/remote_*.plist. UDID from the record
    content first, the file name second (same rule as the
    pairfile intake). No values are read out, only the UDID."""
    found = []

    def _scan_dir(d):
        try:
            names = sorted(os.listdir(d))
        except Exception:
            return
        for name in names:
            if not name.endswith(".plist"):
                continue
            try:
                with open(os.path.join(d, name), "rb") as f:
                    info = _analyze_pairing_bytes(f.read(), name)
                u = info.get("udid", "")
                if u and u not in found:
                    found.append(u)
            except Exception:
                pass

    _scan_dir(_pairing_dir())
    _scan_dir(_pmd3_config_dir())
    return found


def _browse_visible_phones():
    """Phones announcing on the LAN right now, via the capture
    script's --list-only mode. Returns [{name, ip, host}]. The
    bridge's own replay (host tailnet-bridge.local) is dropped:
    it is an echo of an already-captured announcement, not a
    second phone. The bridge is stopped for the browse and
    restarted after, like the scan-first capture."""
    _script, _config, _log = _resolve_bridge_paths()
    if not _script:
        return []
    _cap = BRIDGE_CAPTURE_PY or os.path.join(os.path.dirname(_script), "capture_remotepairing.py")
    if not os.path.exists(_cap):
        return []
    _was_running = _bridge_state()[0] == "running"
    _stop_bridge()
    try:
        _proc = subprocess.run([sys.executable, _cap, "--list-only", "--timeout", "10"],
                               capture_output=True, text=True, timeout=60,
                               cwd=os.path.dirname(_script))
        _out = ((_proc.stdout or "") + (_proc.stderr or "")).strip()
    except Exception:
        _out = ""
    if _was_running:
        _ensure_bridge()
    out = []
    for line in _out.splitlines():
        m = re.match(r"^\[\d+\]\s+instance=(.+?)\s+host=(\S+)(?:\s+port=\d+\s+addrs=(.*))?", line.strip())
        if not m:
            continue
        if m.group(2) == "tailnet-bridge.local":
            continue
        _ip = ""
        for _tok in (m.group(3) or "").split(","):
            _tok = _tok.strip()
            if re.fullmatch(r"\d+\.\d+\.\d+\.\d+", _tok):
                _ip = _tok
                break
        _entry = {"name": _bridge_phone_name(m.group(1)), "ip": _ip, "host": m.group(2)}
        if _entry not in out:
            out.append(_entry)
    return out


def _browse_mobdev2(timeout=45):
    """Phones answering _apple-mobdev2 on the LAN, via the
    pymobiledevice3 CLI: `pymobiledevice3 bonjour mobdev2`.
    Unlike the capture-script browse (instance/host/IP only),
    the CLI output carries the UDID itself (UniqueDeviceID)
    plus name, model and iOS version -- no pairing record and
    no RSD tunnel needed to learn the UDID. Returns
    [{name, udid, model, ios, ip}]; udid may be "" -- the CLI
    has been seen reporting UniqueDeviceID null (locked
    phone), and such entries are visible context only. Runs
    its own subprocess: _run_pmd truncates output to 900
    chars, which would cut a two-phone JSON array. Empty list
    on any failure; the caller falls back to the
    record/probe path."""
    exe = shutil.which("pymobiledevice3")
    full = ([exe, "bonjour", "mobdev2"] if exe else
            [sys.executable, "-m", "pymobiledevice3", "bonjour", "mobdev2"])
    try:
        r = subprocess.run(full, capture_output=True, text=True, timeout=timeout)
        out = r.stdout or ""
    except Exception:
        return []
    if r.returncode != 0 and not out.strip():
        return []
    _start = out.find("[")
    _end = out.rfind("]")
    if _start < 0 or _end <= _start:
        return []
    try:
        _items = json.loads(out[_start:_end + 1])
    except Exception:
        return []
    if not isinstance(_items, list):
        return []
    out_list = []
    _seen = set()
    for _it in _items:
        if not isinstance(_it, dict):
            continue
        _raw = _it.get("UniqueDeviceID")
        if _raw is None or str(_raw).strip() == "":
            # Announced but no UDID (e.g. locked phone): visible
            # context only, never a pick candidate.
            _udid = ""
        else:
            _udid = str(_raw).strip()
            if not _UDID_RE.fullmatch(_udid):
                continue
        _entry = {"name": str(_it.get("DeviceName") or "").strip(),
                  "udid": _udid,
                  "model": str(_it.get("ProductType") or "").strip(),
                  "ios": str(_it.get("ProductVersion") or "").strip(),
                  "ip": str(_it.get("ip") or _it.get("Identifier") or "").strip()}
        if _udid:
            if _udid in _seen:
                continue
            _seen.add(_udid)
        else:
            _key = ("", _entry["name"], _entry["ip"])
            if _key in _seen:
                continue
            _seen.add(_key)
        out_list.append(_entry)
    return out_list


def _probe_phone_udid(udid, timeout=30):
    """Full identity of one phone over an RSD tunnel (Wi-Fi via the
    bridge replay, or USB). Returns the probe dict or None when
    the phone does not answer. Read-only, tunnel always stopped."""
    proc, addr, port, _log = _start_rsd_tunnel(udid, timeout=timeout)
    if not proc or not addr or not port:
        return None
    try:
        ok, vals, _err = _run_probe_handshake(addr, port, timeout=timeout)
        return vals if ok else None
    finally:
        _stop_rsd_tunnel(proc)


def _find_phone_thread(chat_id, via):
    """Find-phone scan for the add-profile UDID step. Candidates
    keyed by UDID come from USB and from pairing records; each
    is probed for full info (name/model/iOS/serial). Phones only
    visible on Wi-Fi without a record are listed separately --
    their UDID cannot be learned without one. Never touches the
    job: the add flow's Apple ID/password stay intact."""
    if job.get("step") in ("prov_running", "prov_2fa_waiting", "pair_running", "repair_running"):
        send_message(chat_id, tr("prov_guard"))
        return
    _srcs = {}
    for _u in _list_usb_udids():
        _srcs.setdefault(_u, set()).add("usb")
    for _u in _list_record_udids():
        _srcs.setdefault(_u, set()).add("record")
    _results = []
    for _udid in list(_srcs)[:4]:
        _results.append({"udid": _udid, "srcs": _srcs[_udid],
                         "info": _probe_phone_udid(_udid)})
    _visible = _browse_visible_phones()
    _known_names = {(r["info"] or {}).get("name", "").lower() for r in _results if (r["info"] or {}).get("name")}
    _visible = [v for v in _visible if v["name"].lower() not in _known_names]
    if not _results and not _visible:
        send_message(chat_id, tr("find_phone_empty"))
        return
    _lines = [tr("find_phone_title")]
    _acts = []
    for _r in _results:
        _info = _r["info"] or {}
        _tags = " + ".join(tr("find_phone_src_usb") if s == "usb" else tr("find_phone_src_record")
                           for s in sorted(_r["srcs"]))
        if _info:
            _parts = []
            if _info.get("name"):
                _parts.append(_info["name"])
            if _info.get("model"):
                _parts.append(_info["model"])
            if _info.get("ios"):
                _parts.append("iOS " + _info["ios"])
            _parts.append("UDID " + _r["udid"])
            if _info.get("serial"):
                _parts.append(tr("find_phone_serial") + " " + _info["serial"])
            _lines.append("📱 " + ", ".join(_parts) + " (%s)" % _tags)
            _label = _info.get("name") or ("UDID …" + _r["udid"][-4:])
        else:
            _lines.append("📱 UDID %s (%s, %s)" % (_r["udid"], _tags, tr("find_phone_offline")))
            _label = "UDID …" + _r["udid"][-4:]
        _acts.append(("📱 %s (…%s)" % (_label, _r["udid"][-4:]), "find_pick:" + _r["udid"]))
    if _visible:
        _lines.append("")
        _lines.append(tr("find_phone_visible_now"))
        for _v in _visible:
            _lines.append("• %s — %s" % (_v["name"], _v["ip"] or "?"))
    _acts.append((btn("find_rescan"), "find_phone"))
    _acts.append((btn("menu"), "menu"))
    show_screen(chat_id, "\n".join(_lines), _acts, via, None, wide=True)


def _send_edit_udid_prompt(chat_id, prof, via, message_id=None):
    """The edit-UDID prompt with discovery buttons. Manual typing
    stays: the prompt text asks for a typed UDID, the buttons are
    an alternative, not a replacement."""
    send_prompt(chat_id, tr("profile_edit_prompt_udid") % prof.get("label", ""), via, message_id,
                actions=[(btn("edit_find_wifi"), "edit_find_wifi"),
                         (btn("edit_find_usb"), "edit_find_usb"),
                         (btn("cancel"), "cancel")])


def _apply_edit_udid(chat_id, prof_id, udid, via):
    """Apply a UDID found by discovery, with the same format check
    as typed input and the same post-save screen (the edit menu,
    whose card carries the re-sign warning). Returns True when
    saved. Only tails ever reach chat text here; the full UDID
    travels in the button payload and the saved profile only."""
    _profiles = load_profiles()
    _prof = find_profile(_profiles, prof_id)
    if not _prof:
        send_message(chat_id, tr("profile_not_found_open"))
        return False
    _val = (udid or "").strip()
    if len(_val) not in (25, 40) or " " in _val:
        send_message(chat_id, tr("not_udid"))
        return False
    _prof["udid"] = _val
    save_profiles(_profiles)
    reset_job()
    send_message(chat_id, tr("profile_edited") % _prof.get("label", ""))
    show_profile_edit(chat_id, _prof, via, None)
    return True


def _edit_find_thread(chat_id, via, mode, edit_id):
    """UDID discovery for the edit-UDID step, in a thread like the
    other long operations. Cable: usbmux list. Wi-Fi: `bonjour
    mobdev2` first -- its announcement carries the UDID itself,
    so no pairing record and no tunnel are needed to know it;
    phones whose announcement carried no UDID stay as visible
    context only. When mobdev2 yields no UDID at all, fall back
    to pairing records probed over the tunnel plus the same LAN
    browse the bridge capture uses. One phone -> substitute
    directly. Several -> pick list with UDID tails + names.
    None -> honest not-found + hint + back to the manual
    prompt. Never touches the job except reading it: the edit
    step stays intact for manual input."""
    if job.get("step") in ("prov_running", "prov_2fa_waiting", "pair_running", "repair_running"):
        send_message(chat_id, tr("prov_guard"))
        return
    _mob = []
    if mode == "usb":
        _udids = _list_usb_udids()
        _visible = []
    else:
        _mob = _browse_mobdev2()
        _valid = [m for m in _mob if m["udid"]]
        if _valid:
            _udids = [m["udid"] for m in _valid]
            _visible = [{"name": m["name"], "ip": m["ip"], "host": ""}
                        for m in _mob if not m["udid"] and m["name"]]
        else:
            _udids = _list_record_udids()
            _visible = _browse_visible_phones()
    _record_set = set(_list_record_udids()) if _mob else set()
    _results = []
    for _udid in _udids[:4]:
        _mobinfo = next((m for m in _mob if m["udid"] == _udid), None)
        if _mobinfo:
            _info = {"name": _mobinfo["name"], "model": _mobinfo["model"],
                     "ios": _mobinfo["ios"], "udid": _udid}
            if _udid in _record_set:
                _probed = _probe_phone_udid(_udid)
                if _probed and _probed.get("serial"):
                    _info["serial"] = _probed["serial"]
            _results.append({"udid": _udid, "info": _info})
        else:
            _results.append({"udid": _udid, "info": _probe_phone_udid(_udid)})
    _known_names = {(r["info"] or {}).get("name", "").lower() for r in _results if (r["info"] or {}).get("name")}
    _visible = [v for v in _visible if v["name"].lower() not in _known_names]
    if job.get("step") != "edit_udid" or str(job.get("edit_id")) != str(edit_id):
        return
    if len(_results) == 1:
        _apply_edit_udid(chat_id, edit_id, _results[0]["udid"], via)
        return
    if not _results:
        _msg = tr("edit_find_empty")
        if _visible:
            _msg += "\n" + tr("find_phone_visible_now") + "\n" + "\n".join(
                "• %s — %s" % (v["name"], v["ip"] or "?") for v in _visible)
        send_message(chat_id, _msg)
        _prof = find_profile(load_profiles(), edit_id)
        if _prof:
            _send_edit_udid_prompt(chat_id, _prof, via)
        return
    _lines = [tr("edit_find_title")]
    _acts = []
    for _r in _results:
        _info = _r["info"] or {}
        _tail = "…" + _r["udid"][-4:]
        if _info:
            _parts = []
            if _info.get("model"):
                _parts.append(_info["model"])
            if _info.get("ios"):
                _parts.append("iOS " + _info["ios"])
            if _info.get("serial"):
                _parts.append(tr("find_phone_serial") + " " + _info["serial"])
            _parts.append("UDID " + _tail)
            _label = _info.get("name") or ("UDID " + _tail)
            _lines.append("📱 %s — %s" % (_label, ", ".join(_parts)))
        else:
            _label = "UDID " + _tail
            _lines.append("📱 %s (%s)" % (_label, tr("find_phone_offline")))
        _acts.append(("📱 %s%s" % (_label, (" (%s)" % _tail) if _info.get("name") else ""), "edit_find_pick:" + _r["udid"]))
    if _visible:
        _lines.append("")
        _lines.append(tr("find_phone_visible_now"))
        for _v in _visible:
            _lines.append("• %s — %s" % (_v["name"], _v["ip"] or "?"))
    _acts.append((btn("menu"), "menu"))
    show_screen(chat_id, "\n".join(_lines), _acts, via, None, wide=True)


INVITES_PATH = os.path.join(BASE_DIR, "invites.json")
INVITE_TTL_SECONDS = 7 * 24 * 3600


def _is_privileged(chat_id):
    if is_owner(chat_id):
        return True
    try:
        return int(chat_id) in load_admins()
    except Exception:
        return False


def _load_invites():
    try:
        with open(INVITES_PATH, encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and isinstance(data.get("invites"), list):
            return data["invites"]
    except Exception:
        pass
    return []


def _save_invites(invites):
    try:
        tmp = INVITES_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"invites": invites}, f, ensure_ascii=False, indent=1)
        os.replace(tmp, INVITES_PATH)
        try:
            os.chmod(INVITES_PATH, 0o600)
        except Exception:
            pass
        return True
    except Exception:
        return False


def _create_invite():
    _token = secrets.token_urlsafe(16)
    _invites = _load_invites()
    _invites.append({"token": _token, "created": int(time.time()),
                     "used": False, "chat_id": 0})
    if not _save_invites(_invites):
        return ""
    return _token


def _consume_invite(token, chat_id):
    """Validate a start-payload token: exists, unused, <7 days.
    Marks it used and binds it to the chat. Returns True/False."""
    _invites = _load_invites()
    _now = int(time.time())
    for _inv in _invites:
        if _inv.get("token") == token:
            if _inv.get("used") or _now - int(_inv.get("created", 0)) > INVITE_TTL_SECONDS:
                return False
            _inv["used"] = True
            _inv["chat_id"] = int(chat_id)
            return _save_invites(_invites)
    return False


def _is_guest_chat(chat_id):
    try:
        _cid = int(chat_id)
    except Exception:
        return False
    return any(_inv.get("used") and int(_inv.get("chat_id") or 0) == _cid
               for _inv in _load_invites())


def pairfile_thread(chat_id, doc, guest=False):
    """Owner-forwarded (or invited-guest) pairing file: download to
    a temp file only, analyze metadata, place where each tool
    expects it, then a trial handshake over the RSD tunnel. Never
    installs, never sends or logs file contents -- only names,
    sizes, key names and the probe verdict leave the PC. When
    guest=True the verdict summary also goes to the owner."""
    _name = doc.get("file_name", "pairing-file")
    _size = doc.get("file_size", 0) or 0
    _tmp = ""
    _nbytes = 0
    _kind_label = "—"
    _udid_disp = "—"
    _placed_disp = "—"
    _verdict = ""
    try:
        if _size > MAX_PAIRFILE_BYTES:
            _verdict = "too big"
            send_message(chat_id, tr("pairfile_too_big") % ((_size + 1023) // 1024,
                                                            MAX_PAIRFILE_BYTES // 1024))
            return
        _fd, _tmp = tempfile.mkstemp(prefix="tiloader-pairfile-")
        os.close(_fd)
        try:
            download_file(doc["file_id"], _tmp)
            with open(_tmp, "rb") as f:
                _data = f.read(MAX_PAIRFILE_BYTES + 1)
        except Exception as e:
            _verdict = "download failed"
            send_message(chat_id, tr("pairfile_download_failed") % str(e)[-200:])
            return
        if len(_data) > MAX_PAIRFILE_BYTES:
            _verdict = "too big"
            send_message(chat_id, tr("pairfile_too_big") % ((len(_data) + 1023) // 1024,
                                                            MAX_PAIRFILE_BYTES // 1024))
            return
        _nbytes = len(_data)
        _info = _analyze_pairing_bytes(_data, _name)
        send_message(chat_id, tr("pairfile_received") % (_name, max(1, len(_data) // 1024)))
        _placed, _backups = _place_pairing_record(_data, _info, _name)
        _placed_disp = ", ".join(_placed)
        try:
            with open(os.path.join(BASE_DIR, "pair-log.txt"), "a", encoding="utf-8") as f:
                f.write("%s pairfile name=%s size=%d kind=%s udid=%s placed=%s guest=%s\n" % (
                    datetime.now(timezone.utc).isoformat(), _name, len(_data),
                    _info["kind"], _info["udid"], ",".join(_placed), guest))
        except Exception:
            pass
        _kind_label = tr("pairfile_kind_" + _info["kind"]) if _info["kind"] in (
            "lockdown", "rp", "plist", "binary") else _info["kind"]
        _udid_disp = _info["udid"] or "—"
        _src_label = (tr("pairfile_udid_from_content") if _info["udid_source"] == "content"
                      else tr("pairfile_udid_from_name") if _info["udid_source"] == "filename"
                      else tr("pairfile_udid_unknown"))
        _keys_label = ", ".join(_info["keys"][:12]) or "—"
        send_message(chat_id, tr("pairfile_format") % (
            _kind_label, _info["udid"] or "—", _src_label, _keys_label))
        send_message(chat_id, tr("pairfile_placed") % "\n".join("• " + p for p in _placed))
        for _old, _bak in _backups:
            send_message(chat_id, tr("pairfile_backed_up") % (_old, _bak))
        if _info["kind"] in ("plist", "binary"):
            _verdict = "format unrecognized"
            send_message(chat_id, tr("pairfile_unrecognized") % os.path.basename(_placed[0]))
            return
        if _info["kind"] == "rp":
            _verdict = "RPPairing, no probe"
            send_message(chat_id, tr("pairfile_no_probe"))
            return
        # Lockdown record with a content UDID: trial handshake.
        _udid = _info["udid"]
        send_message(chat_id, tr("pairfile_probe_start") % _udid)
        proc, addr, port, log, via, pair_suspect = _start_tunnel_any(_udid)
        if proc is None:
            if pair_suspect:
                _verdict = "record rejected"
                send_message(chat_id, tr("pairfile_probe_rejected"))
            else:
                _verdict = "not visible"
                send_message(chat_id, tr("pairfile_probe_notseen") % (log or "no RSD address/port")[-200:])
            return
        try:
            ok, vals, err = _run_probe_handshake(addr, port)
            if not ok:
                _verdict = "probe failed: " + (err or "?")[:120]
                send_message(chat_id, tr("pairfile_probe_failed") % (err or "?"))
                return
            if vals.get("udid") and vals["udid"] != _udid:
                _verdict = "UDID mismatch"
                send_message(chat_id, tr("pairfile_probe_mismatch"))
                return
            _nm = vals.get("name") or "?"
            _ios = vals.get("ios") or ""
            _ver = _parse_ios_version(_ios)
            if _ios and _ver:
                _verdict = "visible+trusted, iOS %s, via %s" % (_ios, via)
                send_message(chat_id, tr("pairfile_probe_ok") % (_nm, _ios, vals.get("model") or "?", via))
                if _ver < (17, 0):
                    send_message(chat_id, tr("pairfile_probe_oldios") % _ios)
            else:
                _verdict = "visible+trusted, iOS unknown, via %s" % via
                send_message(chat_id, tr("pairfile_probe_ok_noios") % (_nm, via))
        finally:
            _stop_rsd_tunnel(proc)
    finally:
        if _tmp and os.path.exists(_tmp):
            try:
                os.remove(_tmp)
            except Exception:
                pass
        if job.get("step") == "pairfile_running":
            job["step"] = None
        if guest and _verdict:
            try:
                send_message(OWNER_ID, tr("pairfile_owner_summary") % (
                    chat_id, _name, max(1, _nbytes // 1024),
                    _kind_label, _udid_disp, _placed_disp, _verdict,
                    tr("pairfile_admin_hint") % chat_id))
            except Exception:
                pass


def pairreplace_thread(chat_id, doc):
    """Owner replacing his OWN pairing record, then retrying the
    install. The file must be his phone's remote_<UDID>.plist
    (RP kind with private_key, or a Lockdown record with
    HostPrivateKey); its UDID must match the bot's expected phone
    UDID. Old records are backed up, never silently overwritten.
    Then the last signed IPA is installed again via
    install_thread (no auto repair -- a fresh record was just
    placed; if it still fails, the install message itself says
    what is wrong). Never sends or logs file contents -- only
    names, sizes and key names leave the host."""
    _name = doc.get("file_name", "pairing-file")
    _size = doc.get("file_size", 0) or 0
    _tmp = ""
    try:
        if _size > MAX_PAIRFILE_BYTES:
            send_message(chat_id, tr("pairfile_too_big") % ((_size + 1023) // 1024,
                                                            MAX_PAIRFILE_BYTES // 1024))
            return
        _fd, _tmp = tempfile.mkstemp(prefix="tiloader-pairreplace-")
        os.close(_fd)
        try:
            download_file(doc["file_id"], _tmp)
            with open(_tmp, "rb") as f:
                _data = f.read(MAX_PAIRFILE_BYTES + 1)
        except Exception as e:
            send_message(chat_id, tr("pairfile_download_failed") % str(e)[-200:])
            return
        if len(_data) > MAX_PAIRFILE_BYTES:
            send_message(chat_id, tr("pairfile_too_big") % ((len(_data) + 1023) // 1024,
                                                            MAX_PAIRFILE_BYTES // 1024))
            return
        _info = _analyze_pairing_bytes(_data, _name)
        send_message(chat_id, tr("pairfile_received") % (_name, max(1, len(_data) // 1024)))
        _expected = _resolve_udid("")
        if not _expected:
            send_message(chat_id, tr("pairreplace_no_udid"))
            return
        if not _info["udid"] or _info["udid"].lower() != _expected.lower():
            send_message(chat_id, tr("pairreplace_wrong_udid") % (
                _info["udid"][-4:] if _info["udid"] else "?", _expected[-4:]))
            return
        if _info["kind"] not in ("rp", "lockdown"):
            send_message(chat_id, tr("pairreplace_bad_format"))
            return
        _need = "private_key" if _info["kind"] == "rp" else "HostPrivateKey"
        if _need not in set(_info["keys"]):
            send_message(chat_id, tr("pairreplace_no_key") % _need)
            return
        _placed, _backups = _place_own_pairing_record(_data, _info)
        try:
            with open(os.path.join(BASE_DIR, "pair-log.txt"), "a", encoding="utf-8") as f:
                f.write("%s pairreplace name=%s size=%d kind=%s udid=%s placed=%s\n" % (
                    datetime.now(timezone.utc).isoformat(), _name, len(_data),
                    _info["kind"], _info["udid"], ",".join(_placed)))
        except Exception:
            pass
        send_message(chat_id, tr("pairfile_placed") % "\n".join("• " + p for p in _placed))
        for _old, _bak in _backups:
            send_message(chat_id, tr("pairfile_backed_up") % (_old, _bak))
        if not LAST_SIGNED.get("path") or not os.path.exists(LAST_SIGNED["path"]):
            _disk = os.path.join(BASE_DIR, "last-signed.ipa")
            if os.path.exists(_disk):
                LAST_SIGNED["path"] = _disk
        if not LAST_SIGNED.get("path") or not os.path.exists(LAST_SIGNED["path"]):
            send_message(chat_id, tr("pairreplace_no_ipa"))
            return
        send_message(chat_id, tr("pairreplace_retrying"))
        install_thread(chat_id, allow_repair=False)
    finally:
        if _tmp and os.path.exists(_tmp):
            try:
                os.remove(_tmp)
            except Exception:
                pass
        if job.get("step") == "pairreplace_running":
            job["step"] = None


STIK_BUNDLES = ("com.stik.stikdebug", "com.stik.sj")


def _find_lockdown_record(udid=""):
    """First Lockdown record for the phone on this host: kind
    'lockdown' with HostPrivateKey, from pairing_candidates()
    plus a scan of pairing/ for *.plist files. Prefers a record
    whose UDID (content first, file name second) matches; falls
    back to the only Lockdown record on the host when nothing
    matches. Returns (path, info) or ('', None). Only key NAMES
    are inspected, never values. The remote/RP record is NOT a
    Lockdown record and is never returned here."""
    _seen = []
    for _p in pairing_candidates(udid):
        if _p and _p not in _seen:
            _seen.append(_p)
    try:
        for _n in sorted(os.listdir(_pairing_dir())):
            if _n.lower().endswith(".plist"):
                _p = os.path.join(_pairing_dir(), _n)
                if _p not in _seen:
                    _seen.append(_p)
    except Exception:
        pass
    _all = []
    for _p in _seen:
        try:
            if not os.path.isfile(_p):
                continue
            with open(_p, "rb") as f:
                _data = f.read(MAX_PAIRFILE_BYTES + 1)
            if len(_data) > MAX_PAIRFILE_BYTES:
                continue
            _info = _analyze_pairing_bytes(_data, _p)
            if _info["kind"] == "lockdown" and "HostPrivateKey" in set(_info["keys"]):
                _all.append((_p, _info))
        except Exception:
            continue
    for _p, _info in _all:
        if _info["udid"] and udid and _info["udid"].lower() == udid.lower():
            return _p, _info
    if len(_all) == 1:
        return _all[0]
    return "", None


def _run_stikpair_write(addr, port, pairing_path, udid, bundle=""):
    """Run stikpair_write.py over the live RSD tunnel. Returns
    (bundle_or_'', error): bundle is the StikDebug bundle the
    file was written into, error is '' on success."""
    if not os.path.exists(STIKPAIR_WRITE_PY):
        return "", "no stikpair_write.py next to the bot"
    try:
        r = subprocess.run([sys.executable, STIKPAIR_WRITE_PY,
                            "--rsd-addr", addr, "--rsd-port", str(port),
                            "--pairing-file", pairing_path, "--udid", udid]
                           + (["--bundle", bundle] if bundle else []),
                           capture_output=True, text=True, timeout=120)
    except Exception as e:
        return "", str(e)
    _out = (r.stdout or "") + "\n" + (r.stderr or "")
    for _line in _out.splitlines():
        if _line.startswith("STIKPAIR_OK "):
            return _line[len("STIKPAIR_OK "):].strip(), ""
    _errs = [l for l in _out.splitlines() if l.startswith("STIKPAIR_ERROR:")]
    if _errs:
        return "", _errs[-1][len("STIKPAIR_ERROR: "):].strip()[-200:]
    return "", (_out.strip()[-200:] or "stikpair write failed")


def stikpair_thread(chat_id):
    """Owner-only: the Lockdown pairing file for StikDebug (JIT),
    idevice_pair-style. (1) Find the phone's Lockdown record on
    this host -- the USB trust file, NOT the remote/RP record.
    (2) Send it to the owner chat, so it can be imported into
    StikDebug by hand. (3) Best-effort: over the live RSD tunnel,
    write the same file straight into StikDebug's Documents via
    house_arrest (com.stik.stikdebug, else com.stik.sj). Every
    step reports honestly; the Telegram file is the deliverable
    even when the phone is unreachable or StikDebug is missing.
    Never sends or logs file contents -- only names, sizes and
    key names leave the host."""
    _bundle = ""
    _err = ""
    try:
        send_message(chat_id, tr("stikpair_working"))
        _udid = _resolve_udid("")
        if not _udid:
            send_message(chat_id, tr("stikpair_no_udid"))
            return
        _path, _info = _find_lockdown_record(_udid)
        if not _path:
            send_message(chat_id, tr("stikpair_no_record"))
            return
        try:
            _size = os.path.getsize(_path)
        except Exception:
            _size = 0
        _disp = os.path.relpath(_path, BASE_DIR) if _path.startswith(BASE_DIR) else os.path.basename(_path)
        send_message(chat_id, tr("stikpair_found") % ("%s, %d KB" % (_disp, max(1, _size // 1024))))
        # Primary delivery: the file itself, to the owner only.
        _send_path = _path
        _tmp = ""
        if os.path.basename(_path) != _udid + ".plist":
            try:
                _fd, _tmp = tempfile.mkstemp(prefix="tiloader-stikpair-", suffix=".plist")
                os.close(_fd)
                _send_path = os.path.join(os.path.dirname(_tmp), _udid + ".plist")
                shutil.copyfile(_path, _send_path)
                _tmp = _send_path
            except Exception:
                _send_path = _path
                _tmp = ""
        try:
            _res = send_document(chat_id, _send_path, tr("pairing_file_caption") % os.path.basename(_send_path))
            _sent = isinstance(_res, dict) and bool(_res.get("ok"))
        except Exception:
            _sent = False
        finally:
            if _tmp and os.path.exists(_tmp):
                try:
                    os.remove(_tmp)
                except Exception:
                    pass
        if not _sent:
            send_message(chat_id, tr("stikpair_send_failed"))
            return
        send_message(chat_id, tr("stikpair_sent"))
        # Best-effort: write straight into StikDebug's Documents.
        _proc, _addr, _port, _log, _via, _suspect = _start_tunnel_any(_udid)
        if _proc is None:
            send_message(chat_id, tr("stikpair_no_phone") % (_log or "no RSD address/port")[-200:])
            return
        try:
            _bundle, _err = _run_stikpair_write(_addr, _port, _path, _udid)
        finally:
            _stop_rsd_tunnel(_proc)
        if _bundle:
            send_message(chat_id, tr("stikpair_written") % _bundle)
        elif "not installed" in (_err or "").lower():
            send_message(chat_id, tr("stikpair_no_app") % ", ".join(STIK_BUNDLES))
        else:
            send_message(chat_id, tr("stikpair_write_failed") % (_err or "?")[-200:])
        try:
            with open(os.path.join(BASE_DIR, "pair-log.txt"), "a", encoding="utf-8") as f:
                f.write("%s stikpair udid=%s record=%s sent=%s bundle=%s err=%s\n" % (
                    datetime.now(timezone.utc).isoformat(), _udid, _disp, _sent, _bundle, (_err or "")[:120]))
        except Exception:
            pass
    finally:
        if job.get("step") == "stikpair_running":
            job["step"] = None


def resolve_sidebot_pair():
    """Our own pairing host: `sidebot-pair`, or `sideloader pair`.

    Both are the Rust binary built from minis-sideloader (src/pair.rs): it
    publishes "Pair with SideBot" through Minis's Bonjour bridge and runs
    the pair-setup itself, so neither siboot nor rootshell is needed.
    SIDEBOT_PAIR_EXE in .env wins."""
    for _c in (ENV.get("SIDEBOT_PAIR_EXE", ""),
               os.path.join(BASE_DIR, "sidebot-pair" + _EXE),
               os.path.join(BASE_DIR, "sidebot-pair"),
               shutil.which("sidebot-pair")):
        if _c and os.path.isfile(_c) and os.access(_c, os.X_OK):
            return _c
    return ""


def resolve_sideloader():
    """Our own Rust `sideloader`: signs and installs an IPA with no siboot.

    SIDELOADER_EXE in .env wins; otherwise the copy next to the bot."""
    for _c in (ENV.get("SIDELOADER_EXE", ""),
               os.path.join(BASE_DIR, "sideloader" + _EXE),
               os.path.join(BASE_DIR, "sideloader"),
               shutil.which("sideloader")):
        if _c and os.path.isfile(_c) and os.access(_c, os.X_OK):
            return _c
    return ""


def _pair_sidebot_cmd():
    """(argv, label) for our own pairing host, or ([], "") when there is none."""
    _exe = resolve_sidebot_pair()
    if _exe:
        return [_exe], os.path.basename(_exe)
    _sl = resolve_sideloader()
    if _sl:
        return [_sl, "pair"], os.path.basename(_sl) + " pair"
    return [], ""


def _pair_via_sidebot_minis(chat_id, api_jid=None, use_cell=None):
    """Pair this iPhone with itself using our own Rust host.

    `sidebot-pair` (or `sideloader pair`) advertises
    _remotepairing-pairable-host._tcp as SideBot via Minis's Bonjour bridge
    (minis-bonjour), accepts the Settings connection with idevice's
    PairableHost, prints the 6-digit code and writes rp_pairing_file.plist
    into pairing/ and .siboot/. No siboot, no rootshell, no transfer code.
    Returns False when the binary is missing or cannot advertise at all, so
    the caller can still fall back to siboot; True once it was attempted."""
    _cmd, _label = _pair_sidebot_cmd()
    if not _cmd:
        return False
    _cell_pair = False
    _apple_open = shutil.which("apple-open") or ("/usr/local/bin/apple-open" if os.path.exists("/usr/local/bin/apple-open") else "")
    _names = _ms_get("cell_names") if isinstance(_ms_get("cell_names"), dict) else {}
    _sc_off = (_names.get("off") or "TurnOffData")
    _sc_on = (_names.get("on") or "TurnOnData")
    _jp = _miniapp_job_get(api_jid) if api_jid else None
    _do_cell = bool(_ms_get("cell")) if use_cell is None else bool(use_cell)
    if _do_cell and (_jp is not None or _apple_open):
        send_message(chat_id, tr("pair_starting_wifi") + "\n📴 Вимикаю мобільні дані — 6-значний код прийде локальним сповіщенням iPhone від Minis.")
        if _jp is not None:
            _jp["toggle"] = "off"
            _jp["toggle_name"] = _sc_off
            _cell_pair = True
            for _ in range(12):
                if not _jp.get("toggle"):
                    break
                time.sleep(0.5)
        if _apple_open:
            try:
                subprocess.run([_apple_open, "shortcuts://run-shortcut?name=" + urllib.parse.quote(_sc_off)],
                               capture_output=True, text=True, timeout=10)
                _cell_pair = True
            except Exception:
                pass
        if _cell_pair:
            time.sleep(1.0)
            _p_dead = time.time() + 6.0
            while time.time() < _p_dead:
                try:
                    with socket.create_connection((MINIS_PHONE_HOST, 49152), timeout=0.4):
                        break
                except Exception:
                    time.sleep(0.2)
    else:
        send_message(chat_id, tr("pair_starting_wifi"))
    _tmp_home = os.path.join(BASE_DIR, ".sidebot-pair-tmp")
    shutil.rmtree(_tmp_home, ignore_errors=True)
    os.makedirs(_tmp_home, exist_ok=True)
    _out_dir = _pairing_dir()
    os.makedirs(_out_dir, exist_ok=True)
    _cmd = list(_cmd) + ["--home", _tmp_home, "--out", _out_dir,
                         "--plain", "--timeout", "600"]
    _env = dict(os.environ)
    _env["SIDEBOT_PLAIN"] = "1"
    _log = []
    _ok = False
    _sent_pins = set()
    _sent_up = False
    _sent_conn = False
    _sent_paired = False
    _advert_failed = False
    _ansi_re = re.compile(r"\x1b\[[0-9;]*[A-Za-z]|\r")
    _log_path = os.path.join(BASE_DIR, "pair-log.txt")
    try:
        with open(_log_path, "a", encoding="utf-8") as _lf:
            _lf.write("%s mode=sidebot_pair start exe=%s\n" % (datetime.now(timezone.utc).isoformat(), " ".join(_cmd)))
    except Exception:
        pass

    def _handle_pair_line(_line):
        nonlocal _sent_up, _sent_conn, _sent_paired, _advert_failed
        if not _line:
            return
        _low = _line.lower()
        try:
            with open(_log_path, "a", encoding="utf-8") as _lf:
                _lf.write("  " + _line + "\n")
        except Exception:
            pass
        if "is up in settings" in _low:
            if not _sent_up:
                _sent_up = True
                _m_up = "📡 «Pair with SideBot» зʼявився в Параметрах → Режим розробника — натисни на нього!"
                send_message(chat_id, _m_up)
                if api_jid:
                    _miniapp_job_set(api_jid, "running", _m_up)
        elif "settings connected" in _low and not _sent_conn:
            _sent_conn = True
            _m_conn = "🔗 iPhone підключився — чекаю 6-значний код..."
            send_message(chat_id, _m_conn)
            if api_jid:
                _miniapp_job_set(api_jid, "running", _m_conn)
        elif "ok paired with" in _low and not _sent_paired:
            _sent_paired = True
            _m_ok = "✅ iPhone спарено! Зберігаю rp_pairing_file.plist..."
            send_message(chat_id, _m_ok)
            if api_jid:
                _miniapp_job_set(api_jid, "running", _m_ok)
        elif ("minis-bonjour" in _low or "паруванн" in _low or "pairing" in _low) and (
                "isn't here" in _low or "couldn't publish" in _low or "refused" in _low):
            _advert_failed = True
        _m3 = re.search(r"\b(\d{3})\s+(\d{3})\b", _line)
        _m6 = re.search(r"\b(\d{6})\b", _line)
        _pin = (_m3.group(1) + _m3.group(2)) if _m3 else (_m6.group(1) if _m6 else "")
        if _pin and _pin not in _sent_pins and "udid" not in _low and "10.7.0.1" not in _low:
            _sent_pins.add(_pin)
            _m_pin = tr("pair_pin") % _pin
            send_message(chat_id, _m_pin)
            if api_jid:
                _miniapp_job_set(api_jid, "running", "🔑 PIN: " + _pin[:3] + " " + _pin[3:])
            _log.append("WIFI_PIN: ****")
        else:
            _log.append(_line)

    try:
        proc = subprocess.Popen(_cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                stderr=subprocess.STDOUT, bufsize=0,
                                env=_env, cwd=BASE_DIR)
        job["proc"] = proc
        _rfd = proc.stdout.fileno()
        _buf = ""
        _deadline = time.time() + 640
        while time.time() < _deadline:
            _r, _, _ = select.select([_rfd], [], [], 0.8)
            if not _r:
                if proc.poll() is not None:
                    break
                continue
            try:
                _chunk = os.read(_rfd, 4096)
            except OSError:
                break
            if not _chunk:
                break
            _buf += _chunk.decode("utf-8", errors="ignore")
            while "\n" in _buf:
                _raw_line, _buf = _buf.split("\n", 1)
                _handle_pair_line(_ansi_re.sub("", _raw_line).strip())
        if _buf.strip():
            _handle_pair_line(_ansi_re.sub("", _buf).strip())
        proc.wait(timeout=30)
        _paired_src = os.path.join(_tmp_home, "rp_pairing_file.plist")
        _ok = os.path.isfile(_paired_src) and os.path.getsize(_paired_src) > 100
        if _ok:
            os.makedirs(SIBOOT_HOME, exist_ok=True)
            shutil.copy2(_paired_src, os.path.join(_out_dir, "rp_pairing_file.plist"))
            shutil.copy2(_paired_src, os.path.join(SIBOOT_HOME, "rp_pairing_file.plist"))
    except Exception as e:
        _log.append("sidebot-pair error: %s" % e)
    finally:
        shutil.rmtree(_tmp_home, ignore_errors=True)
        if _cell_pair:
            if _jp is not None:
                _jp["toggle"] = "on"
                _jp["toggle_name"] = _sc_on
                for _ in range(12):
                    if not _jp.get("toggle"):
                        break
                    time.sleep(0.5)
            if _apple_open:
                try:
                    subprocess.run([_apple_open, "shortcuts://run-shortcut?name=" + urllib.parse.quote(_sc_on)],
                                   capture_output=True, text=True, timeout=10)
                except Exception:
                    pass
            time.sleep(2.5)
    job["proc"] = None
    job["step"] = None
    try:
        with open(_log_path, "a", encoding="utf-8") as _lf:
            _lf.write("%s mode=sidebot_pair done ok=%s up=%s\n---\n" % (
                datetime.now(timezone.utc).isoformat(), _ok, _sent_up))
    except Exception:
        pass
    if _ok:
        _msg_done = (tr("pair_done_wifi") % "rp_pairing_file.plist" +
                     "\n📁 Збережено в:\n• %s\n• %s" % (
                         os.path.join(_out_dir, "rp_pairing_file.plist"),
                         os.path.join(SIBOOT_HOME, "rp_pairing_file.plist")))
        send_message(chat_id, _msg_done)
        _send_pairing_file(chat_id, os.path.join(_out_dir, "rp_pairing_file.plist"))
        return True
    if not _sent_up:
        # Nothing was ever advertised (no minis-bonjour, minis-pair missing,
        # Minis too old): let the caller try siboot instead.
        send_message(chat_id, "⚠️ %s не зміг показати «Pair with SideBot» — пробую siboot." % _label)
        return False
    _tail = "\n".join(_log)[-400:] or "sidebot-pair: pairing failed"
    send_message(chat_id, tr("pair_failed") % _tail)
    return True


def _pair_via_siboot_minis(chat_id, api_jid=None):
    """Self-pair this iPhone inside Open Minis 1.16+ without a PC using
    `siboot connect --plain --terminal --home <tmp>` (minis-bonjour)."""
    _sb_exe = ""
    for _c in (SIBOOT_EXE, os.path.join(BASE_DIR, "siboot"), shutil.which("siboot")):
        if _c and os.path.isfile(_c) and "sideloader" not in os.path.basename(_c).lower():
            _sb_exe = _c
            break
    if not _sb_exe:
        return False
    _cell_pair = False
    _apple_open = shutil.which("apple-open") or ("/usr/local/bin/apple-open" if os.path.exists("/usr/local/bin/apple-open") else "")
    _names = _ms_get("cell_names") if isinstance(_ms_get("cell_names"), dict) else {}
    _sc_off = (_names.get("off") or "TurnOffData")
    _sc_on = (_names.get("on") or "TurnOnData")
    _jp = _miniapp_job_get(api_jid) if api_jid else None
    if _ms_get("cell") and (_jp is not None or _apple_open):
        send_message(chat_id, tr("pair_starting_wifi") + "\n📴 Вимикаю мобільні дані — 6-значний код прийде локальним сповіщенням iPhone від Minis.")
        if _jp is not None:
            _jp["toggle"] = "off"
            _jp["toggle_name"] = _sc_off
            _cell_pair = True
            for _ in range(12):
                if not _jp.get("toggle"):
                    break
                time.sleep(0.5)
        if _apple_open:
            try:
                subprocess.run([_apple_open, "shortcuts://run-shortcut?name=" + urllib.parse.quote(_sc_off)],
                               capture_output=True, text=True, timeout=10)
                _cell_pair = True
            except Exception:
                pass
        if _cell_pair:
            time.sleep(1.0)
            _p_dead = time.time() + 6.0
            while time.time() < _p_dead:
                try:
                    with socket.create_connection((MINIS_PHONE_HOST, 49152), timeout=0.4):
                        break
                except Exception:
                    time.sleep(0.2)
    else:
        send_message(chat_id, tr("pair_starting_wifi"))
    _tmp_home = os.path.join(BASE_DIR, ".siboot-pair-tmp")
    shutil.rmtree(_tmp_home, ignore_errors=True)
    os.makedirs(_tmp_home, exist_ok=True)
    _cmd = [_sb_exe, "connect", "--plain", "--terminal", "--home", _tmp_home]
    _env = dict(os.environ)
    _env["SIBOOT_PLAIN"] = "1"
    _log = []
    _ok = False
    _sent_pins = set()
    _sent_up = False
    _sent_conn = False
    _sent_paired = False
    _ansi_re = re.compile(r"\x1b\[[0-9;]*[A-Za-z]|\r")
    _log_path = os.path.join(BASE_DIR, "pair-log.txt")
    try:
        with open(_log_path, "a", encoding="utf-8") as _lf:
            _lf.write("%s mode=minis_siboot start exe=%s\n" % (datetime.now(timezone.utc).isoformat(), _sb_exe))
    except Exception:
        pass
    _mfd, _sfd = -1, -1
    try:
        proc = subprocess.Popen(_cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                stderr=subprocess.STDOUT, bufsize=0,
                                env=_env, cwd=BASE_DIR)
        job["proc"] = proc
        _rfd = proc.stdout.fileno()
        _buf = ""
        _deadline = time.time() + 620
        _enter_sent = False

        def _handle_pair_line(_line):
            nonlocal _sent_up, _sent_conn, _sent_paired
            if not _line:
                return
            _low = _line.lower()
            try:
                with open(_log_path, "a", encoding="utf-8") as _lf:
                    _lf.write("  " + _line + "\n")
            except Exception:
                pass
            if "start pairing" in _low or "press enter" in _low:
                try:
                    proc.stdin.write(b"\n")
                    proc.stdin.flush()
                except Exception:
                    pass
            if not _sent_up and "is up in settings" in _low:
                _sent_up = True
                send_message(chat_id, "📡 «Pair with siboot» зʼявився в Параметрах → Режим розробника — натисни на нього!")
            if not _sent_conn and "settings connected" in _low:
                _sent_conn = True
                send_message(chat_id, "🔗 iPhone підключився — чекаю 6-значний код...")
            if not _sent_paired and "ok paired with" in _low:
                _sent_paired = True
                send_message(chat_id, "✅ iPhone спарено! Зберігаю rp_pairing_file.plist...")
            _m3 = re.search(r"\b(\d{3})\s+(\d{3})\b", _line)
            _m6 = re.search(r"\b(\d{6})\b", _line)
            _pin = (_m3.group(1) + _m3.group(2)) if _m3 else (_m6.group(1) if _m6 else "")
            if _pin and _pin not in _sent_pins and "udid" not in _low and "10.7.0.1" not in _low:
                _sent_pins.add(_pin)
                send_message(chat_id, tr("pair_pin") % _pin)
                _log.append("WIFI_PIN: ****")
            else:
                _log.append(_line)

        while time.time() < _deadline:
            _r, _, _ = select.select([_rfd], [], [], 0.8)
            if not _r:
                if proc.poll() is not None:
                    break
                if _buf.strip():
                    _clean = _ansi_re.sub("", _buf).strip()
                    _low = _clean.lower()
                    if not _enter_sent and any(k in _low for k in ("start pairing", "press enter", "get ready")):
                        try:
                            proc.stdin.write(b"\n")
                            proc.stdin.flush()
                            _enter_sent = True
                        except Exception:
                            pass
                    if re.search(r"(?:pairing code|code:|\b\d{3}\s+\d{3}\b)", _low):
                        _handle_pair_line(_clean)
                        _buf = ""
                continue
            try:
                _chunk = os.read(_rfd, 4096)
            except OSError:
                break
            if not _chunk:
                break
            _buf += _chunk.decode("utf-8", errors="ignore")
            while "\n" in _buf:
                _raw_line, _buf = _buf.split("\n", 1)
                _handle_pair_line(_ansi_re.sub("", _raw_line).strip())
        if _buf.strip():
            _handle_pair_line(_ansi_re.sub("", _buf).strip())
        proc.wait(timeout=30)
        _paired_src = os.path.join(_tmp_home, "rp_pairing_file.plist")
        _ok = os.path.isfile(_paired_src) and os.path.getsize(_paired_src) > 100
        _verify_warn = (_ok and proc.returncode != 0)
        if _ok:
            os.makedirs(_pairing_dir(), exist_ok=True)
            os.makedirs(SIBOOT_HOME, exist_ok=True)
            _dst_pair = os.path.join(_pairing_dir(), "rp_pairing_file.plist")
            _dst_sb = os.path.join(SIBOOT_HOME, "rp_pairing_file.plist")
            shutil.copy2(_paired_src, _dst_pair)
            shutil.copy2(_paired_src, _dst_sb)
    except Exception as e:
        _log.append("siboot pair error: %s" % e)
    finally:
        if _sfd >= 0:
            try:
                os.close(_sfd)
            except Exception:
                pass
        try:
            os.close(_mfd)
        except Exception:
            pass
        shutil.rmtree(_tmp_home, ignore_errors=True)
        if _cell_pair:
            if _jp is not None:
                _jp["toggle"] = "on"
                _jp["toggle_name"] = _sc_on
                for _ in range(12):
                    if not _jp.get("toggle"):
                        break
                    time.sleep(0.5)
            if _apple_open:
                try:
                    subprocess.run([_apple_open, "shortcuts://run-shortcut?name=" + urllib.parse.quote(_sc_on)],
                                   capture_output=True, text=True, timeout=10)
                except Exception:
                    pass
            time.sleep(2.5)
    job["proc"] = None
    job["step"] = None
    try:
        with open(_log_path, "a", encoding="utf-8") as _lf:
            _lf.write("%s mode=minis_siboot done ok=%s\n---\n" % (
                datetime.now(timezone.utc).isoformat(), _ok))
    except Exception:
        pass
    if not _ok:
        _tail = "\n".join(_log)[-400:] or "siboot pairing failed (need Open Minis 1.16+ & LocalDevVPN)"
        send_message(chat_id, tr("pair_failed") % _tail)
        return True
    _msg_done = (tr("pair_done_wifi") % "rp_pairing_file.plist" +
                 "\n📁 Збережено в:\n• %s\n• %s" % (
                     os.path.join(_pairing_dir(), "rp_pairing_file.plist"),
                     os.path.join(SIBOOT_HOME, "rp_pairing_file.plist")))
    if locals().get("_verify_warn"):
        _msg_done += "\n\n⚠️ Файл створено, але перевірка 10.7.0.1:49152 на 5G відмовила — встановлюй через SideBot із Cellular Refresh."
    send_message(chat_id, _msg_done)
    _send_pairing_file(chat_id, os.path.join(_pairing_dir(), "rp_pairing_file.plist"))
    return True


def pair_thread(chat_id, mode):
    """Run the pair helper and, for USB, the pymobiledevice3 remote
    record. The helper prints one marker line per step; the bot
    streams stdout (byte reads, like provision_thread) so the
    Wi-Fi PIN reaches Telegram while the helper is still waiting
    for the phone -- a subprocess.run() would deliver it only
    after the helper exits, when it is too late. After a
    successful run the saved pairing files are sent to the owner
    chat (with a warning caption) and listed under "My pairings";
    the PIN is redacted in pair-log.txt. Cancel kills the helper
    through job["proc"] / reset_job, like provisioning."""
    if (MINIS_MODE or os.uname().machine in ("aarch64", "arm64")) and mode == "wifi":
        # Our own Rust host first (sidebot-pair / `sideloader pair`, paired as
        # "SideBot" through minis-bonjour): siboot is only the fallback now.
        if _pair_via_sidebot_minis(chat_id):
            return
        if _pair_via_siboot_minis(chat_id):
            return
    if not os.path.exists(PAIR_EXE):
        send_message(chat_id, tr("pair_exe_missing"))
        job["step"] = None
        return
    send_message(chat_id, tr("pair_starting_usb") if mode == "usb" else tr("pair_starting_wifi"))
    _udid = job.get("udid", "") or ""
    _cmd = [PAIR_EXE, "--mode", mode, "--out-dir", os.path.join(BASE_DIR, "pairing")]
    if PAIR_HOST_LABEL:
        _cmd += ["--host-label", PAIR_HOST_LABEL]
    if mode == "usb":
        if _udid:
            _cmd += ["--udid", _udid]
        _cmd += ["--write-app", PAIR_WRITE_APP or "SideStore"]
    else:
        _cmd += ["--timeout-secs", "300"]
    _lockdown = ""
    _remote = ""
    _wrote = ""
    _log = []
    _ok = False
    try:
        proc = subprocess.Popen(_cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                stderr=subprocess.STDOUT, bufsize=0, cwd=BASE_DIR)
        job["proc"] = proc
        buf = ""
        while True:
            try:
                chunk = os.read(proc.stdout.fileno(), 8192)
            except Exception:
                break
            if not chunk:
                break
            try:
                _txt = chunk.decode("utf-8", errors="ignore")
            except Exception:
                _txt = ""
            buf += _txt
            while "\n" in buf:
                line, buf = buf.split("\n", 1)
                _line = line.strip()
                if _line.startswith("WIFI_PIN:"):
                    _pin = _line.split(":", 1)[1].strip()
                    if _pin:
                        send_message(chat_id, tr("pair_pin") % _pin)
                    _log.append("WIFI_PIN: ****")
                elif _line.startswith("PAIR_LOCKDOWN_SAVED:"):
                    _lockdown = os.path.basename(_line.split(":", 1)[1].strip().rsplit(" ", 1)[0].strip())
                    _log.append(_line)
                elif _line.startswith("PAIR_REMOTE_SAVED:"):
                    _remote = os.path.basename(_line.split(":", 1)[1].strip().rsplit(" ", 1)[0].strip())
                    _log.append(_line)
                elif _line.startswith("PAIR_WROTE_APP:"):
                    _wrote = tr("pair_sidestore_wrote")
                    _log.append(_line)
                elif _line.startswith("PAIR_DONE"):
                    _ok = True
                    _log.append(_line)
                elif _line:
                    _log.append(_line)
        proc.wait(timeout=60)
        _ok = _ok and proc.returncode == 0
    except Exception as e:
        _log.append("pair thread error: %s" % e)
    job["proc"] = None
    job["step"] = None
    try:
        with open(os.path.join(BASE_DIR, "pair-log.txt"), "a", encoding="utf-8") as _lf:
            _lf.write("%s mode=%s ok=%s\n%s\n---\n" % (datetime.now(timezone.utc).isoformat(), mode, _ok, "\n".join(_log)[-1500:]))
    except Exception:
        pass
    if not _ok:
        _tail = "\n".join(_log)[-400:] or "pair helper failed"
        send_message(chat_id, tr("pair_failed") % _tail)
        return
    if mode == "wifi":
        send_message(chat_id, tr("pair_done_wifi") % (_remote or "pairingFile.plist"))
        if _remote:
            _send_pairing_file(chat_id, os.path.join(_pairing_dir(), _remote))
        return
    # USB only: the pymobiledevice3 remote record is a DIFFERENT
    # format from the helper's RPPairing file, and only the
    # pymobiledevice3 record makes its Wi-Fi discovery work.
    # Created promptlessly over the already-trusted USB lockdown
    # channel (pymobiledevice3 docs: lockdown remotepairing --pair).
    _rc, _out = _run_pmd(["lockdown", "remotepairing", "--pair"], timeout=120)
    _remote_note = tr("pair_remote_ok") if _rc == 0 else tr("pair_remote_fail") % _out.strip()[-200:]
    _extra = "\n".join([x for x in (_wrote, _remote_note) if x])
    send_message(chat_id, tr("pair_done_usb") % (_lockdown or "?", _remote or "?", _extra))
    for _name in (_lockdown, _remote):
        if _name:
            _send_pairing_file(chat_id, os.path.join(_pairing_dir(), _name))


def check_thread(chat_id):
    _bundle = LAST_SIGNED.get("bundle", "")
    if not _bundle:
        _recs = load_installed()
        if _recs:
            _bundle = _recs[-1].get("bundle", "")
    if not _bundle:
        send_message(chat_id, tr("check_phone_no_bundle"))
        return
    _udid = job.get("udid", "") or ""
    if not _udid:
        _recs = load_installed()
        if _recs:
            _udid = _recs[-1].get("udid", "")
    found, out = check_phone_apps(_udid, _bundle)
    if found:
        send_message(chat_id, tr("check_phone_found") % _bundle)
    else:
        send_message(chat_id, tr("check_phone_missing") % (_bundle, out))


_REPAIR_CODE_RE = re.compile(r"Enter this code on your device:\s*(\d{6})")
_REPAIR_TIMEOUT = 180


def repair_thread(chat_id, retry_install=True):
    """Re-pair the phone over Wi-Fi when its pairing record went
    stale (the phone accepts TCP on 49152, then drops the
    connection during record validation -- fixed live on
    2026-10-28 by `remote pair-host`). Runs `pymobiledevice3
    remote pair-host`, streams its output, forwards the 6-digit
    code to Telegram, and on success retries the install once.
    The phone tap + code entry cannot be automated -- Apple
    requires approval in Settings > Developer > Paired Macs --
    but everything else happens from Telegram alone. The code is
    redacted in repair-log.txt. Guarded like pair_thread:
    job['step']='repair_running', job['proc'] for Cancel."""
    if job.get("step") in ("prov_running", "prov_2fa_waiting", "pair_running", "repair_running"):
        send_message(chat_id, tr("repair_busy"))
        return
    job["step"] = "repair_running"
    _dbg("repair start")
    send_message(chat_id, tr("repair_starting"))
    _code_sent = {"done": False}
    _state = {"paired": False}
    _lines = []
    proc = None
    try:
        _exe = shutil.which("pymobiledevice3")
        full = ([_exe] if _exe else [sys.executable, "-m", "pymobiledevice3"]) + ["remote", "pair-host"]
        proc = subprocess.Popen(full, stdout=subprocess.PIPE,
                                stderr=subprocess.STDOUT,
                                stdin=subprocess.DEVNULL,
                                text=True, bufsize=1)
        job["proc"] = proc

        def _reader():
            try:
                for _line in proc.stdout:
                    _lines.append(_line.rstrip("\n"))
                    if not _code_sent["done"]:
                        _m = _REPAIR_CODE_RE.search(_line)
                        if _m:
                            _code_sent["done"] = True
                            _dbg("repair: code prompt seen (value not logged)")
                            send_message(chat_id, tr("repair_code") % _m.group(1))
                    if "Paired with device:" in _line or "Pairing record written" in _line:
                        _state["paired"] = True
            except Exception:
                pass

        _t = threading.Thread(target=_reader, daemon=True)
        _t.start()
        _deadline = time.time() + _REPAIR_TIMEOUT
        while time.time() < _deadline:
            if _state["paired"]:
                break
            if proc.poll() is not None:
                break
            time.sleep(0.5)
        _t.join(timeout=2)
        _was_running = proc.poll() is None
        if _was_running:
            _stop_rsd_tunnel(proc)
        _dbg("repair result paired=%s" % _state["paired"])
        _tail = "\n".join(_lines)[-600:]
        try:
            with open(os.path.join(BASE_DIR, "repair-log.txt"), "a", encoding="utf-8") as _lf:
                _lf.write("%s\n%s\n---\n" % (datetime.now(timezone.utc).isoformat(),
                                             _REPAIR_CODE_RE.sub("Enter this code on your device: ******", _tail)))
        except Exception:
            pass
        if _state["paired"]:
            send_message(chat_id, tr("repair_done"))
            if retry_install and LAST_SIGNED.get("path"):
                install_thread(chat_id, allow_repair=False)
            return
        if _was_running or proc.returncode in (0, None):
            # Still waiting when the deadline hit (or exited
            # cleanly without pairing): the phone never started.
            send_message(chat_id, tr("repair_timeout"))
            return
        send_message(chat_id, tr("repair_failed") % _tail[-200:])
    except Exception as e:
        send_message(chat_id, tr("repair_failed") % str(e))
    finally:
        if job.get("proc") is proc:
            job["proc"] = None
        job["step"] = None



# MINIS INSTALL 2026-11-13 -------------------------------------------
# Only install path that works inside Open Minis: the native Rust
# install-helper (idevice 0.1.68, same crate as SideStore's
# "idevice" backend) talks plain TCP to the phone's own RSD
# service at 10.7.0.1:49152 through LocalDevVPN. No TUN, no root,
# no pymobiledevice3, no Trust prompt: it validates the SAVED
# pairing record (pairing/<UDID>.remote.plist, or the rootshell
# export rp_pairing_file.plist placed in pairing/). Success is
# ONLY "INSTALL_OK" on stdout with exit code 0. On-phone verify
# via apps query is impossible here (needs the TUN tunnel), so a
# helper-reported success is reported as such and the owner
# confirms the icon on the home screen.

def _minis_install_exe():
    if INSTALL_EXE and os.path.exists(INSTALL_EXE):
        return INSTALL_EXE
    _local = os.path.join(BASE_DIR, "install-helper", "target", "release", "telegram-iloader-install")
    return _local if os.path.exists(_local) else ""


def _minis_pairing_file(udid=""):
    _cands = []
    if udid:
        _cands.append(os.path.join(_pairing_dir(), udid + ".remote.plist"))
        _cands.append(os.path.join(_pairing_dir(), udid + ".plist"))
    _cands.append(os.path.join(_pairing_dir(), "rp_pairing_file.plist"))
    _cands.append(os.path.join(SIBOOT_HOME, "rp_pairing_file.plist"))
    for _p in _cands:
        if os.path.exists(_p):
            return _p
    try:
        for _n in sorted(os.listdir(_pairing_dir())):
            if _n.endswith(".remote.plist") or _n.endswith(".plist"):
                return os.path.join(_pairing_dir(), _n)
    except Exception:
        pass
    return ""


_INSTALL_LIVE_LOCK = threading.Lock()
_INSTALL_LIVE_LINES = []


def _install_log_line(msg):
    _ts = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
    _ln = "[%s] %s" % (_ts, msg)
    _dbg(msg)
    try:
        with open(os.path.join(BASE_DIR, "install-log.txt"), "a", encoding="utf-8") as _lf:
            _lf.write(_ln + "\n")
    except Exception:
        pass
    try:
        _short = "[%s] %s" % (_ts[11:19], msg)
        with _INSTALL_LIVE_LOCK:
            _INSTALL_LIVE_LINES.append(_short)
            if len(_INSTALL_LIVE_LINES) > 60:
                del _INSTALL_LIVE_LINES[:-60]
            _snap = list(_INSTALL_LIVE_LINES)
        _jid = job.get("api_jid")
        if not _jid:
            with _MINIAPP_JOBS_LOCK:
                for _k, _v in reversed(list(_MINIAPP_JOBS.items())):
                    if _v.get("status") == "running":
                        _jid = _k
                        break
        if _jid:
            _pct = None
            _m = re.search(r"(\d{1,3})\s*%", msg)
            if _m:
                _v = max(0, min(100, int(_m.group(1))))
                if "[helper" in msg:
                    _pct = max(55, min(99, 55 + int(_v * 0.44)))
                else:
                    _pct = _v
            elif "[DOWNLOAD] start" in msg:
                _pct = 10
            elif "[DOWNLOAD] ok" in msg:
                _pct = 25
            elif "START PROVISION" in msg:
                _pct = 35
            elif "END PROVISION rc=0" in msg:
                _pct = 50
            elif "[INSTALL_THREAD]" in msg or "START INSTALL_MINIS_RUST" in msg:
                _pct = 55
            elif "INSTALL_OK" in msg or "END INSTALL_MINIS_RUST ok=True" in msg:
                _pct = 100
            with _MINIAPP_JOBS_LOCK:
                if _jid in _MINIAPP_JOBS:
                    _MINIAPP_JOBS[_jid]["logs"] = _snap
                    if _pct is not None:
                        _prev = _MINIAPP_JOBS[_jid].get("pct") or 0
                        if _pct >= _prev:
                            _MINIAPP_JOBS[_jid]["pct"] = _pct
    except Exception:
        pass


def install_minis_rust(ipa_path, udid="", bundle=""):
    """(ok, details). ok only on INSTALL_OK + rc 0."""
    _t0 = time.time()
    if not ipa_path or not os.path.exists(ipa_path):
        _install_log_line("ERR: signed file not found: %s" % ipa_path)
        return False, "signed file not found in Minis"
    udid = _resolve_udid(udid)
    _exe = _minis_install_exe()
    if not _exe:
        _install_log_line("ERR: install-helper binary missing")
        return False, ("install-helper not built yet: run ./build-minis-rust.sh "
                       "on the PC (aarch64-musl) or ./build.sh inside Minis, "
                       "then copy install-helper/target/release/telegram-iloader-install "
                       "into the Minis workspace and restart the bot")
    _rf = _minis_pairing_file(udid)
    if not _rf:
        _install_log_line("ERR: pairing file not found (udid=...%s)" % (udid[-4:] if udid else ""))
        return False, ("pairing file not found: put rp_pairing_file.plist "
                       "(rootshell export) or <UDID>.remote.plist in pairing/ "
                       "via the Files app, or forward it to the bot (/pairfile)")
    _fsize = os.path.getsize(ipa_path)
    _rfsize = os.path.getsize(_rf) if os.path.exists(_rf) else 0
    _cmd = [_exe, "--host", MINIS_PHONE_HOST, "--pairing-file", _rf,
            "--ipa", ipa_path, "--timeout-secs", "300"]
    if udid:
        _cmd += ["--udid", udid]
    _install_log_line("=== START INSTALL_MINIS_RUST ===")
    _install_log_line("ipa=%s (%.2f MB) bundle=%s udid=%s" % (
        os.path.basename(ipa_path), _fsize / (1024 * 1024), bundle or "-", udid or "-"))
    _install_log_line("pairing=%s (%d B) host=%s:49152" % (
        os.path.basename(_rf), _rfsize, MINIS_PHONE_HOST))
    _install_log_line("cmd=%s" % _dbg_mask_cmd(_cmd))
    _lines = []
    _rc = -1
    try:
        _p = subprocess.Popen(_cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                              text=True, bufsize=1, errors="replace")
        for _raw in _p.stdout:
            _s = _raw.rstrip("\r\n")
            if _s:
                _lines.append(_s)
                _install_log_line("[helper +%.1fs] %s" % (time.time() - _t0, _s))
        _rc = _p.wait(timeout=600)
    except Exception as e:
        _install_log_line("EXC install-helper (+%.1fs): %s" % (time.time() - _t0, e))
        return False, "install-helper: %s" % e
    _out = "\n".join(_lines)[-12000:]
    _ok_flag = (_rc == 0 and "INSTALL_OK" in _out)
    _install_log_line("=== END INSTALL_MINIS_RUST ok=%s rc=%s elapsed=%.1fs ===" % (
        _ok_flag, _rc, time.time() - _t0))
    if _ok_flag:
        return True, ("INSTALL_OK via 10.7.0.1 (Rust install-helper). "
                      "Check the icon on the home screen and launch the app - "
                      "on-phone verify is not possible from Minis.\n" + _out.strip()[-800:])
    return False, _out.strip()[-1500:] or ("install-helper failed (rc=%s)" % _rc)


# ---- Uninstall from the phone (2026-11-16, minis-uninstall) ---
# My Apps › Delete must really remove the app, not only its row.
# The only device channel in Minis is the Rust install-helper
# (idevice 0.1.68 over 10.7.0.1:49152). Its source is built
# separately, so whether THIS build has an uninstall subcommand
# cannot be assumed — it is probed once per binary version. When
# the build has none, the bot says so honestly instead of
# claiming the app is gone; the record and files are still
# removed so the card disappears.
_UNINSTALL_PROBE = {"exe": "", "mtime": 0, "size": 0, "ok": False}


def _minis_uninstall_supports():
    """(exe, ok, err). ok means this helper answers an uninstall
    help, so a real uninstall can be attempted. Cached per
    (path, mtime, size) like the appdata probe."""
    _exe = _minis_install_exe()
    if not _exe:
        return "", False, tr("miniapp_uninstall_helper_missing")
    try:
        _st = os.stat(_exe)
    except Exception:
        return "", False, tr("miniapp_uninstall_helper_missing")
    _probe = _UNINSTALL_PROBE
    if _probe.get("exe") == _exe and _probe.get("mtime") == _st.st_mtime \
            and _probe.get("size") == _st.st_size:
        return _exe, bool(_probe.get("ok")), ("" if _probe.get("ok")
                                             else tr("miniapp_uninstall_unsupported"))
    _ok = False
    try:
        _r = subprocess.run([_exe, "uninstall", "--help"],
                            capture_output=True, text=True, timeout=20)
        _out = ((_r.stdout or "") + "\n" + (_r.stderr or "")).lower()
        _ok = "uninstall" in _out and "--bundle" in _out
        if not _ok:
            _r2 = subprocess.run([_exe, "--help"], capture_output=True,
                                 text=True, timeout=20)
            _ok = "uninstall" in (((_r2.stdout or "") + "\n"
                                   + (_r2.stderr or "")).lower())
    except Exception:
        _ok = False
    _probe.update({"exe": _exe, "mtime": _st.st_mtime,
                   "size": _st.st_size, "ok": _ok})
    return _exe, _ok, "" if _ok else tr("miniapp_uninstall_unsupported")


def _minis_uninstall(bundle, udid=""):
    """(ok, details, attempted). attempted False = this helper
    cannot uninstall at all (details says so). attempted True and
    ok False = the helper ran and refused/failed."""
    _exe, _ok, _err = _minis_uninstall_supports()
    if not _ok:
        return False, _err or tr("miniapp_uninstall_helper_missing"), False
    _rf = _minis_pairing_file(udid or "")
    if not _rf:
        return False, "pairing file not found", True
    _cmd = [_exe, "uninstall", "--host", MINIS_PHONE_HOST,
            "--pairing-file", _rf, "--bundle", bundle,
            "--timeout-secs", "120"]
    if udid:
        _cmd += ["--udid", udid]
    _dbg("minis uninstall cmd=%s" % _dbg_mask_cmd(_cmd))
    try:
        _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=240)
        _out = ((_r.stdout or "") + "\n" + (_r.stderr or ""))[-600:]
        _rc = _r.returncode
    except Exception as _e:
        return False, "install-helper: %s" % _e, True
    try:
        with open(os.path.join(BASE_DIR, "install-log.txt"), "a", encoding="utf-8") as _lf:
            _lf.write("%s minis-uninstall rc=%s bundle=%s\n%s\n---\n" % (
                datetime.now(timezone.utc).isoformat(), _rc, bundle, _out[-1200:]))
    except Exception:
        pass
    _up = _out.upper()
    if _rc == 0 and ("UNINSTALL_OK" in _up or "UNINSTALLED" in _up):
        return True, _out.strip()[-300:], True
    return False, _out.strip()[-400:] or "install-helper returned rc=%s" % _rc, True


# ---- App data backup & restore (Phase 8, 2026-11-14-minis-appdata8) ----
# Port of the Windows bot subsystem (BOT_BUILD 2026-11-13-win-celldance,
# ~8 _appdata_* functions, pymobiledevice3 house_arrest CLI).
# Minis adaptations:
# - Transport is NOT pymobiledevice3 (needs TUN + root, unavailable in
#   Minis): the Rust install-helper gained `appdata-pull` /
#   `appdata-push` subcommands (idevice 0.1.68 HouseArrestClient:
#   VendContainer / VendDocuments over AFC, same RSD tunnel to
#   10.7.0.1:49152 as the install path). The helper is probed for
#   those subcommands; an old helper reports honestly instead of
#   faking a backup (appdata_helper_no_appdata).
# - No Mini App job system in Minis: threads report straight to chat.
# - No on-phone "is the app installed" pre-check (needs the TUN
#   tunnel): the vend itself fails with InstallationLookupFailed
#   when the app is absent or refuses the container, and the
#   backup reports that instead of claiming success.
# - Backups live in backups/appdata/<bundle>-<stamp>.zip (chmod 600)
#   INSIDE the Minis bot folder (i.e. on the phone itself); the
#   index appdata_backups.json keeps the newest 5 per bundle.
#   A ZIP can be sent to chat only within the Telegram send limit
#   (50 MB, 2000 MB with a local Bot API server) -- bigger backups
#   stay in the folder and the bot says so.
# - Restore NEVER runs without a confirm tap: the confirm screen
#   carries a data-loss warning, and the pending restore is kept
#   in job["appdata_pending"] and validated on the Yes tap, so a
#   stale or double tap cannot overwrite data.
# - Uploaded restore ZIPs are extracted with a zip-slip guard and
#   are capped by Telegram's 20 MB download limit (download_file).
# - Backups contain the user's private app data: never include
#   them in any archive the bot builds, and warn before sending.
APPDATA_DIR = os.path.join(BASE_DIR, "backups", "appdata")
APPDATA_INDEX = os.path.join(BASE_DIR, "appdata_backups.json")
APPDATA_KEEP = 5
APPDATA_UPLOAD_MAX_BYTES = 20 * 1024 * 1024


def _appdata_index_load():
    try:
        with open(APPDATA_INDEX, encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, list) else []
    except Exception:
        return []


def _appdata_index_save(records):
    try:
        tmp = APPDATA_INDEX + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(records, f, ensure_ascii=False, indent=1)
        os.replace(tmp, APPDATA_INDEX)
        try:
            os.chmod(APPDATA_INDEX, 0o600)
        except Exception:
            pass
        return True
    except Exception:
        return False


def _appdata_for(bundle):
    """Index entries for one bundle, newest first."""
    _all = [r for r in _appdata_index_load() if r.get("bundle") == bundle]
    _all.sort(key=lambda r: r.get("at", ""), reverse=True)
    return _all


def _appdata_prune(bundle):
    """Keep the newest APPDATA_KEEP zips per bundle; delete older
    files and their index entries."""
    _kept = _appdata_for(bundle)[:APPDATA_KEEP]
    _drop = _appdata_for(bundle)[APPDATA_KEEP:]
    for _r in _drop:
        try:
            os.unlink(os.path.join(APPDATA_DIR, _r.get("file", "")))
        except Exception:
            pass
    _rest = [r for r in _appdata_index_load()
             if r.get("bundle") != bundle or r in _kept]
    _appdata_index_save(_rest)


_APPDATA_HELPER_PROBE = {"exe": "", "mtime": 0, "size": 0, "ok": False}


def _appdata_helper_supports():
    """(exe, ok, err): exe = install-helper path or ''; ok = the
    binary answers `appdata-pull --help` (Phase 8 build). The
    probe is cached per (path, mtime, size), so a rebuilt helper
    is picked up after a bot restart without re-probing."""
    _exe = _minis_install_exe()
    if not _exe:
        return "", False, tr("appdata_helper_missing")
    try:
        _st = os.stat(_exe)
    except Exception:
        return "", False, tr("appdata_helper_missing")
    _probe = _APPDATA_HELPER_PROBE
    if _probe.get("exe") == _exe and _probe.get("mtime") == _st.st_mtime \
            and _probe.get("size") == _st.st_size:
        return _exe, bool(_probe.get("ok")), \
            "" if _probe.get("ok") else tr("appdata_helper_no_appdata")
    _ok = False
    try:
        r = subprocess.run([_exe, "appdata-pull", "--help"],
                           capture_output=True, text=True, timeout=30)
        _ok = r.returncode == 0 and "appdata-pull" in (r.stdout or "")
    except Exception:
        _ok = False
    _probe.update({"exe": _exe, "mtime": _st.st_mtime,
                   "size": _st.st_size, "ok": _ok})
    return _exe, _ok, "" if _ok else tr("appdata_helper_no_appdata")


def _appdata_pull(udid, bundle, dest, documents_only):
    """One House Arrest pull of the container root into dest, via
    the Rust install-helper. Returns (rc, output tail)."""
    _exe, _ok, _err = _appdata_helper_supports()
    if not _ok:
        return -1, _err
    _rf = _minis_pairing_file(udid)
    if not _rf:
        return -1, tr("appdata_no_pairing")
    _cmd = [_exe, "appdata-pull", "--host", MINIS_PHONE_HOST,
            "--pairing-file", _rf, "--bundle", bundle,
            "--out-dir", dest, "--timeout-secs", "900"]
    if documents_only:
        _cmd.append("--documents-only")
    if udid:
        _cmd += ["--udid", udid]
    _dbg("appdata pull cmd=%s" % _dbg_mask_cmd(_cmd))
    try:
        r = subprocess.run(_cmd, capture_output=True, text=True, timeout=960)
        return r.returncode, ((r.stdout or "") + "\n" + (r.stderr or ""))[-900:]
    except Exception as e:
        return -1, str(e)


def _appdata_push(udid, bundle, path, documents_only):
    """One House Arrest push: a directory is uploaded as
    /<basename> (recursive), a file as /<basename>. The helper
    tells the two apart itself. Returns (rc, output tail)."""
    _exe, _ok, _err = _appdata_helper_supports()
    if not _ok:
        return -1, _err
    _rf = _minis_pairing_file(udid)
    if not _rf:
        return -1, tr("appdata_no_pairing")
    _cmd = [_exe, "appdata-push", "--host", MINIS_PHONE_HOST,
            "--pairing-file", _rf, "--bundle", bundle,
            "--timeout-secs", "900"]
    if os.path.isdir(path):
        _cmd += ["--dir", path]
    else:
        _cmd += ["--file", path]
    if documents_only:
        _cmd.append("--documents-only")
    if udid:
        _cmd += ["--udid", udid]
    _dbg("appdata push cmd=%s" % _dbg_mask_cmd(_cmd))
    try:
        r = subprocess.run(_cmd, capture_output=True, text=True, timeout=960)
        return r.returncode, ((r.stdout or "") + "\n" + (r.stderr or ""))[-900:]
    except Exception as e:
        return -1, str(e)


def _appdata_backup_thread(chat_id, bundle):
    try:
        _rec = next((r for r in load_installed() if r.get("bundle") == bundle), None)
        if _rec is None:
            send_message(chat_id, tr("appdata_no_record"))
            return
        _title = _rec.get("title") or bundle
        _udid = _rec.get("udid") or _resolve_udid()
        _exe, _ok, _err = _appdata_helper_supports()
        if not _ok:
            send_message(chat_id, _err)
            return
        if not _minis_pairing_file(_udid):
            send_message(chat_id, tr("appdata_no_pairing"))
            return
        send_message(chat_id, tr("appdata_backup_started") % _title)
        _tmp = tempfile.mkdtemp(prefix="appdata-")
        _scope = "container"
        try:
            _rc, _out = _appdata_pull(_udid, bundle, _tmp, False)
            if _rc != 0 and "InstallationLookupFailed" in (_out or ""):
                _scope = "documents"
                _rc, _out = _appdata_pull(_udid, bundle, _tmp, True)
            if _rc != 0:
                send_message(chat_id, tr("appdata_backup_fail") % (_title, (_out or "")[-300:]))
                return
            _files = 0
            _size = 0
            for _dp, _dn, _fn in os.walk(_tmp):
                for _f in _fn:
                    _fp = os.path.join(_dp, _f)
                    try:
                        _size += os.path.getsize(_fp)
                        _files += 1
                    except Exception:
                        pass
            if _files == 0:
                # A pull that yields nothing is a failure, not an
                # empty backup: even a fresh app has Library files.
                send_message(chat_id, tr("appdata_backup_fail") % (_title, tr("appdata_empty")))
                return
            _stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
            _safe = re.sub(r"[^A-Za-z0-9._-]", "", bundle.replace(".", "_"))
            _name = "%s-%s.zip" % (_safe or "app", _stamp)
            os.makedirs(APPDATA_DIR, exist_ok=True)
            _zpath = os.path.join(APPDATA_DIR, _name)
            with zipfile.ZipFile(_zpath, "w", zipfile.ZIP_DEFLATED) as _z:
                for _dp, _dn, _fn in os.walk(_tmp):
                    for _f in _fn:
                        _fp = os.path.join(_dp, _f)
                        _z.write(_fp, os.path.relpath(_fp, _tmp))
            try:
                os.chmod(_zpath, 0o600)
            except Exception:
                pass
            _recs = _appdata_index_load()
            _recs.append({"bundle": bundle, "title": _title, "file": _name,
                          "scope": _scope, "size": _size, "files": _files,
                          "at": datetime.now(timezone.utc).isoformat()})
            _appdata_index_save(_recs)
            _appdata_prune(bundle)
            _scope_text = tr("appdata_scope_container") if _scope == "container" else tr("appdata_scope_documents")
            send_message(chat_id, tr("appdata_backup_ok") % (_title, _scope_text, _size / 1048576.0, _files, _name))
            if _scope == "documents":
                send_message(chat_id, tr("appdata_docs_only"))
        finally:
            shutil.rmtree(_tmp, ignore_errors=True)
    finally:
        if job.get("step") == "appdata_running":
            job["step"] = None


def _appdata_safe_extract(zpath, dest):
    """Extract a ZIP with a zip-slip guard: no absolute paths, no
    '..' components. Raises ValueError on a bad entry."""
    with zipfile.ZipFile(zpath) as _z:
        for _info in _z.infolist():
            _name = _info.filename
            if os.path.isabs(_name) or ".." in _name.split("/"):
                raise ValueError("bad zip entry: %s" % _name[:80])
        _z.extractall(dest)


def _appdata_restore_thread(chat_id, bundle, idx=None, upload=None):
    """Restore one backup: idx = index into _appdata_for(bundle)
    (stored backup), or upload = {"dir": extracted_dir, "file":
    display_name} (forwarded ZIP). Only ever started from the
    confirm Yes tap -- never directly from a menu action."""
    _tmp = None
    _own_tmp = False
    try:
        _rec = next((r for r in load_installed() if r.get("bundle") == bundle), None)
        if _rec is None:
            send_message(chat_id, tr("appdata_no_record"))
            return
        _title = _rec.get("title") or bundle
        _udid = _rec.get("udid") or _resolve_udid()
        _exe, _ok, _err = _appdata_helper_supports()
        if not _ok:
            send_message(chat_id, _err)
            return
        if not _minis_pairing_file(_udid):
            send_message(chat_id, tr("appdata_no_pairing"))
            return
        if upload is not None:
            _tmp = upload.get("dir") or ""
            _name = upload.get("file") or "upload.zip"
            _scope = "container"
            if not _tmp or not os.path.isdir(_tmp):
                send_message(chat_id, tr("appdata_no_backups") % _title)
                return
        else:
            _entries = _appdata_for(bundle)
            if idx is None or idx < 0 or idx >= len(_entries):
                send_message(chat_id, tr("appdata_no_backups") % bundle)
                return
            _ent = _entries[idx]
            _name = _ent.get("file", "")
            _zpath = os.path.join(APPDATA_DIR, _name)
            if not os.path.exists(_zpath):
                send_message(chat_id, tr("appdata_no_backups") % _title)
                return
            _scope = _ent.get("scope") or "container"
            _tmp = tempfile.mkdtemp(prefix="appdata-restore-")
            _own_tmp = True
            try:
                _appdata_safe_extract(_zpath, _tmp)
            except Exception as e:
                send_message(chat_id, tr("appdata_restore_fail") % (_title, str(e)[:200]))
                return
        send_message(chat_id, tr("appdata_restore_started") % (_title, _name))
        _tops = sorted([e for e in os.listdir(_tmp)
                        if os.path.exists(os.path.join(_tmp, e))])
        _done = 0
        _errs = []
        _fell_back = False
        for _e in _tops:
            _rc, _out = _appdata_push(_udid, bundle, os.path.join(_tmp, _e),
                                      _scope == "documents")
            if _rc == 0:
                _done += 1
                continue
            if _scope == "container" and "InstallationLookupFailed" in (_out or ""):
                # The phone refuses the full container now (e.g. the
                # app was reinstalled as an App Store build): retry
                # this entry Documents-only and say so.
                _rc2, _out2 = _appdata_push(_udid, bundle, os.path.join(_tmp, _e), True)
                if _rc2 == 0:
                    _done += 1
                    _fell_back = True
                    continue
                _errs.append("%s: %s" % (_e, (_out2 or "")[-200:]))
            else:
                _errs.append("%s: %s" % (_e, (_out or "")[-200:]))
        if _errs:
            send_message(chat_id, tr("appdata_restore_fail") % (_title, "; ".join(_errs)[:400]))
            return
        send_message(chat_id, tr("appdata_restore_ok") % (_title, _done))
        if _fell_back:
            send_message(chat_id, tr("appdata_docs_only"))
    except Exception as e:
        _title = ""
        try:
            _rec = next((r for r in load_installed() if r.get("bundle") == bundle), None)
            _title = (_rec or {}).get("title") or bundle
        except Exception:
            _title = bundle
        send_message(chat_id, tr("appdata_restore_fail") % (_title, str(e)[:200]))
    finally:
        if _own_tmp and _tmp:
            shutil.rmtree(_tmp, ignore_errors=True)
        if upload is not None and _tmp:
            # The uploaded tree was extracted for this restore only.
            shutil.rmtree(_tmp, ignore_errors=True)
        if job.get("step") == "appdata_running":
            job["step"] = None


def _appdata_apps():
    """Installed apps the bot knows, as [(bundle, title)]; also
    refreshes job["appdata_apps"], the bundle list the short
    callback data ("appdata_app:<idx>") resolves against."""
    _recs = [r for r in load_installed() if r.get("bundle")]
    job["appdata_apps"] = [r.get("bundle") for r in _recs]
    return [(r.get("bundle"), r.get("title") or r.get("bundle")) for r in _recs]


def _appdata_bundle_at(app_idx):
    try:
        _apps = job.get("appdata_apps") or []
        _i = int(app_idx)
        return _apps[_i] if 0 <= _i < len(_apps) else ""
    except Exception:
        return ""


def _appdata_menu(chat_id, via, message_id=None):
    _apps = _appdata_apps()
    if not _apps:
        send_message(chat_id, tr("appdata_no_apps"))
        return
    _limit = 2000 if _local_bot_api() else 50
    _lines = [tr("appdata_menu_title"),
              tr("appdata_menu_hint") % (_limit, _limit)]
    _acts = []
    for _i, (_b, _t) in enumerate(_apps):
        _n = len(_appdata_for(_b))
        _acts.append(("💾 %s (%d)" % (_t, _n), "appdata_app:%d" % _i))
    _acts.append((btn("menu"), "menu"))
    show_screen(chat_id, "\n".join(_lines), _acts, via, message_id, wide=True)


def _appdata_screen(chat_id, app_idx, via, message_id=None):
    _bundle = _appdata_bundle_at(app_idx)
    if not _bundle:
        _appdata_menu(chat_id, via, message_id)
        return
    _rec = next((r for r in load_installed() if r.get("bundle") == _bundle), None)
    if _rec is None:
        send_message(chat_id, tr("appdata_no_record"))
        return
    _entries = _appdata_for(_bundle)
    _acts = [("💾 Backup", "appdata_backup:%d" % app_idx),
             (btn("appdata_upload"), "appdata_upload:%d" % app_idx)]
    for _i, _e in enumerate(_entries):
        _acts.append(("📦 %s — %s, %.1f МБ" % (_e.get("file", ""), _e.get("scope", ""),
                                                (_e.get("size") or 0) / 1048576.0),
                      "appdata_pick:%d:%d" % (app_idx, _i)))
    _acts.append((btn("menu"), "menu"))
    show_screen(chat_id, tr("appdata_title") % (_rec.get("title") or _bundle, _bundle, len(_entries)),
                _acts, via, message_id, wide=True)


def _appdata_backup_screen(chat_id, app_idx, idx, via, message_id=None):
    """One stored backup: its details, Restore (goes to the
    confirm screen, never straight to the push) and ZIP-to-chat."""
    _bundle = _appdata_bundle_at(app_idx)
    if not _bundle:
        _appdata_menu(chat_id, via, message_id)
        return
    _entries = _appdata_for(_bundle)
    if idx < 0 or idx >= len(_entries):
        _appdata_screen(chat_id, app_idx, via, message_id)
        return
    _ent = _entries[idx]
    _rec = next((r for r in load_installed() if r.get("bundle") == _bundle), None)
    _title = (_rec or {}).get("title") or _bundle
    _scope_text = tr("appdata_scope_container") if (_ent.get("scope") or "container") == "container" \
        else tr("appdata_scope_documents")
    _lines = ["📦 %s" % (_ent.get("file") or "?"),
              "%s: %s" % (_title, _bundle),
              "%s, %.1f МБ, %d %s" % (_scope_text, (_ent.get("size") or 0) / 1048576.0,
                                      _ent.get("files") or 0,
                                      "файлів" if CUR_LANG in ("uk", "ru") else "files"),
              (_ent.get("at", "") or "")[:16].replace("T", " ")]
    _acts = [("↩️ Restore", "appdata_restore:%d:%d" % (app_idx, idx)),
             (btn("appdata_send"), "appdata_send:%d:%d" % (app_idx, idx)),
             ("⬅️ %s" % _title, "appdata_app:%d" % app_idx),
             (btn("menu"), "menu")]
    show_screen(chat_id, "\n".join(_lines), _acts, via, message_id, wide=True)


def _appdata_confirm_screen(chat_id, app_idx, idx, via, message_id=None, upload=False):
    """The data-loss warning. Sets job["appdata_pending"]; only a
    Yes tap whose pending still matches starts the restore."""
    _bundle = _appdata_bundle_at(app_idx)
    if not _bundle:
        _appdata_menu(chat_id, via, message_id)
        return
    _rec = next((r for r in load_installed() if r.get("bundle") == _bundle), None)
    _title = (_rec or {}).get("title") or _bundle
    if upload:
        _pend = job.get("appdata_pending") or {}
        if _pend.get("bundle") != _bundle or _pend.get("kind") != "upload":
            _appdata_screen(chat_id, app_idx, via, message_id)
            return
        _name = _pend.get("file") or "upload.zip"
        _yes = "appdata_yes_upload:%d" % app_idx
    else:
        _entries = _appdata_for(_bundle)
        if idx < 0 or idx >= len(_entries):
            _appdata_screen(chat_id, app_idx, via, message_id)
            return
        _name = _entries[idx].get("file", "")
        job["appdata_pending"] = {"bundle": _bundle, "idx": idx}
        _yes = "appdata_yes:%d:%d" % (app_idx, idx)
    _acts = [(btn("appdata_restore_yes"), _yes),
             (btn("appdata_restore_no"), "appdata_no:%d" % app_idx)]
    show_screen(chat_id, tr("appdata_restore_confirm") % (_title, _name),
                _acts, via, message_id, wide=True)


def _appdata_send_zip(chat_id, app_idx, idx):
    _bundle = _appdata_bundle_at(app_idx)
    if not _bundle:
        _appdata_menu(chat_id, "reply")
        return
    _entries = _appdata_for(_bundle)
    if idx < 0 or idx >= len(_entries):
        _appdata_screen(chat_id, app_idx, "reply")
        return
    _ent = _entries[idx]
    _rec = next((r for r in load_installed() if r.get("bundle") == _bundle), None)
    _title = (_rec or {}).get("title") or _bundle
    _zpath = os.path.join(APPDATA_DIR, _ent.get("file", ""))
    if not os.path.exists(_zpath):
        send_message(chat_id, tr("appdata_no_backups") % _title)
        return
    _limit = 2000 * 1024 * 1024 if _local_bot_api() else 50 * 1024 * 1024
    _size = os.path.getsize(_zpath)
    if _size > _limit:
        send_message(chat_id, tr("appdata_send_too_big") % (
            _ent.get("file", ""), _size / 1048576.0,
            _limit / 1048576, _limit / 1048576, _ent.get("file", "")))
        return
    send_message(chat_id, tr("appdata_send_warn") % (_ent.get("file", ""), _size / 1048576.0))
    res = send_document(chat_id, _zpath, caption=_ent.get("file", ""))
    if not (isinstance(res, dict) and res.get("ok")):
        _err = ""
        if isinstance(res, dict):
            _err = str(res.get("description") or res)[:120]
        send_message(chat_id, tr("appdata_send_failed") % (_err or "send failed"))


def _appdata_restore_upload_thread(chat_id, bundle, doc):
    """Download a forwarded restore ZIP, validate it, extract it
    to a temp dir and show the confirm screen. Nothing is pushed
    here -- the Yes tap does that."""
    _rec = next((r for r in load_installed() if r.get("bundle") == bundle), None)
    if _rec is None:
        job["step"] = None
        send_message(chat_id, tr("appdata_no_record"))
        return
    _title = _rec.get("title") or bundle
    _name = doc.get("file_name", "backup.zip") or "backup.zip"
    _tmp = tempfile.mkdtemp(prefix="appdata-upload-")
    _zpath = os.path.join(_tmp, "upload.zip")
    _extract = ""
    try:
        download_file(doc["file_id"], _zpath)
        if not zipfile.is_zipfile(_zpath):
            send_message(chat_id, tr("appdata_restore_upload_bad"))
            return
        _extract = tempfile.mkdtemp(prefix="appdata-upload-x-")
        _appdata_safe_extract(_zpath, _extract)
    except Exception as e:
        if _extract:
            shutil.rmtree(_extract, ignore_errors=True)
        send_message(chat_id, tr("appdata_restore_fail") % (_title, str(e)[-200:]))
        return
    finally:
        shutil.rmtree(_tmp, ignore_errors=True)
    job["appdata_pending"] = {"bundle": bundle, "kind": "upload",
                              "dir": _extract, "file": _name}
    job["step"] = None
    job["appdata_pending_upload"] = {}
    send_message(chat_id, tr("appdata_restore_upload_received") % _name)
    _apps = job.get("appdata_apps") or []
    _idx = _apps.index(bundle) if bundle in _apps else -1
    if _idx < 0:
        _appdata_apps()
        _apps = job.get("appdata_apps") or []
        _idx = _apps.index(bundle) if bundle in _apps else -1
    if _idx < 0:
        job["step"] = None
        send_message(chat_id, tr("appdata_no_record"))
        shutil.rmtree(_extract, ignore_errors=True)
        job["appdata_pending"] = {}
        return
    _appdata_confirm_screen(chat_id, _idx, -1, job.get("via", "reply"), None, upload=True)


def install_thread(chat_id, allow_repair=True):
    send_message(chat_id, tr("lockdown_starting"))
    _path = LAST_SIGNED.get("path", "")
    _udid = job.get("udid", "") or ""
    _bundle = LAST_SIGNED.get("bundle", "")
    if not _bundle and _path and os.path.exists(_path):
        _bundle = read_ipa_info(_path)[0] or ""
    _dbg("install start bundle=%s path=%s udid_tail=%s" % (_bundle, os.path.basename(_path or ""), _udid[-4:]))
    if MINIS_MODE:
        _aj = job.get("api_jid")
        _cell_toggled = False
        _t0 = time.time()
        _tlog = []
        _install_log_line("[INSTALL_THREAD] path=%s bundle=%s aj=%s cell=%s" % (os.path.basename(_path or ""), _bundle, _aj, bool(_ms_get("cell"))))
        def _tmark(msg):
            _s = "+%.1fs %s" % (time.time() - _t0, msg)
            _tlog.append(_s)
            _install_log_line("[TIMING] " + _s)
            if _aj:
                _miniapp_job_set(_aj, "running", _s)
        _port_ok = False
        send_message(chat_id, "\U0001f4f2 \u0412\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u044e\u044e \u0447\u0435\u0440\u0435\u0437 install-helper (Rust) \u043d\u0430 10.7.0.1... \u0422\u0440\u0438\u043c\u0430\u0439 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u0440\u043e\u0437\u0431\u043b\u043e\u043a\u043e\u0432\u0430\u043d\u0438\u043c, \u0435\u043a\u0440\u0430\u043d \u0443\u0432\u0456\u043c\u043a\u043d\u0435\u043d\u0438\u043c.")
        if _ms_get("cell"):
            _names = _ms_get("cell_names") if isinstance(_ms_get("cell_names"), dict) else {}
            _sc_off = (_names.get("off") or "TurnOffData")
            _apple_open = shutil.which("apple-open") or ("/usr/local/bin/apple-open" if os.path.exists("/usr/local/bin/apple-open") else "")
            if _apple_open:
                try:
                    _sc_url = "shortcuts://run-shortcut?name=" + urllib.parse.quote(_sc_off)
                    _dbg("minis cell-off via apple-open: %s" % _sc_url)
                    _tmark("TurnOffData -> apple-open")
                    subprocess.run([_apple_open, _sc_url], capture_output=True, text=True, timeout=10)
                    _cell_toggled = True
                    time.sleep(1.0)
                    _deadline = time.time() + 6.0
                    while time.time() < _deadline:
                        try:
                            with socket.create_connection((MINIS_PHONE_HOST, 49152), timeout=0.4):
                                _port_ok = True
                                break
                        except Exception:
                            time.sleep(0.2)
                    _tmark("port 49152 %s" % ("OPEN!" if _port_ok else "refused (6s timeout)"))
                except Exception as _ae:
                    _dbg("apple-open cell-off err=%s" % _ae)
            elif _aj:
                _jp = _miniapp_job_get(_aj)
                if _jp is not None:
                    _tmark("TurnOffData -> SideBot")
                    _jp["toggle"] = "off"
                    _jp["toggle_name"] = _sc_off
                    _cell_toggled = True
                    for _ in range(12):
                        if not _jp.get("toggle"):
                            break
                        time.sleep(0.5)
                    _tmark("toggle_ack ok, waiting 1.0s")
                    time.sleep(1.0)
                    _deadline = time.time() + 6.0
                    while time.time() < _deadline:
                        try:
                            with socket.create_connection((MINIS_PHONE_HOST, 49152), timeout=0.4):
                                _port_ok = True
                                break
                        except Exception:
                            time.sleep(0.2)
                    _tmark("port 49152 %s" % ("OPEN!" if _port_ok else "refused (6s timeout)"))
        _ok, _det = False, "not started"
        try:
            if _cell_toggled and not _port_ok:
                _tmark("abort: port 10.7.0.1:49152 unreachable -> TurnOnData")
                _det = "Порт 10.7.0.1:49152 недоступний (перевір LocalDevVPN)"
            else:
                _tmark("start install-helper")
                _ok, _det = install_minis_rust(_path, _udid, _bundle)
                _tmark("install-helper done ok=%s" % _ok)
        finally:
            if _cell_toggled and not bool(_ms_get("skip_turn_on")):
                _names = _ms_get("cell_names") if isinstance(_ms_get("cell_names"), dict) else {}
                _sc_on = (_names.get("on") or "TurnOnData")
                _apple_open = shutil.which("apple-open") or ("/usr/local/bin/apple-open" if os.path.exists("/usr/local/bin/apple-open") else "")
                if _apple_open:
                    try:
                        subprocess.run([_apple_open, "shortcuts://run-shortcut?name=" + urllib.parse.quote(_sc_on)], capture_output=True, text=True, timeout=10)
                    except Exception:
                        pass
                elif _aj:
                    _jp = _miniapp_job_get(_aj)
                    if _jp is not None:
                        _jp["toggle"] = "on"
                        _jp["toggle_name"] = _sc_on
                time.sleep(1.5)
        if _aj:
            with _MINIAPP_JOBS_LOCK:
                if _aj in _MINIAPP_JOBS:
                    _MINIAPP_JOBS[_aj]["install_ok"] = bool(_ok)
                    _MINIAPP_JOBS[_aj]["install_err"] = "" if _ok else str(_det or "")
                    if _ok:
                        _MINIAPP_JOBS[_aj]["pct"] = 100
        if _ok:
            send_message(chat_id, "\u2705 " + _det)
        else:
            send_message(chat_id, "\u274c Minis-\u0432\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u043d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f: " + _det)
        if _tlog:
            send_message(chat_id, "⏱ Timing:\n" + "\n".join(_tlog))
        return
    ok, details, pair_suspect, unverified = install_via_lockdown(_path, _udid, _bundle)
    _dbg("install result ok=%s unverified=%s pair_suspect=%s" % (ok, unverified, pair_suspect))
    try:
        with open(os.path.join(BASE_DIR, "install-log.txt"), "a", encoding="utf-8") as _lf:
            _lf.write("%s ok=%s udid=...%s path=%s\n%s\n---\n" % (datetime.now(timezone.utc).isoformat(), "unverified" if unverified else ok, _udid[-4:], os.path.basename(_path or ""), (details or "")[-1500:]))
    except Exception:
        pass
    if ok:
        _tail = (details or "").strip()
        if _tail:
            send_message(chat_id, tr("lockdown_ok") + "\n" + _tail[-400:])
        else:
            send_message(chat_id, tr("lockdown_ok") + "\n(no output from pymobiledevice3)")
    elif unverified:
        send_message(chat_id, tr("lockdown_unverified"))
    else:
        _pair_path, _pair_kind = find_pairing_file(_udid)
        send_message(chat_id, tr("lockdown_fail") % details)
        # Stale pairing record: fix it from here instead of
        # retrying tunnels that the phone will keep rejecting.
        # The repair runs once (its retry calls install_thread
        # with allow_repair=False, so this cannot loop).
        if pair_suspect and allow_repair and LAST_SIGNED.get("path"):
            _dbg("install: pair_suspect, starting repair")
            threading.Thread(target=repair_thread, args=(chat_id, True), daemon=True).start()
            return
        # The admin hint is generic: do not show it when the
        # tunnel log itself says what is wrong (e.g. the device
        # chooser asking for --udid) -- that text is the diagnosis.
        if "rsd-tunnel:" in (details or "") and "Pass --udid" not in (details or ""):
            send_message(chat_id, tr("rsd_tunnel_hint"))
        if not _pair_path or _pair_kind == "sidestore":
            send_message(chat_id, tr("pairing_setup"))




# SPLIT INSTALL 2026-10-28 --------------------------------------------
# Two visible steps of one `apps install --developer`: (1) stage the
# signed IPA over AFC to /PublicStaging/pymobiledevice3.ipa, (2) send
# the Install command for the staged file, no re-upload. The helper
# (stage_install.py) uses the same pymobiledevice3 calls
# install_from_local uses, only split; the bot starts/stops the RSD
# tunnel around each step exactly like install_via_rsd_tunnel. The
# staged file stays on the phone until installd consumes it or the
# next stage overwrites it (one fixed filename); staged.json records
# which bundle was staged, so step 2 can verify it.
STAGED_FILE = os.path.join(BASE_DIR, "staged.json")
STAGED_REMOTE_PATH = "/PublicStaging/pymobiledevice3.ipa"


def load_staged():
    try:
        with open(STAGED_FILE, "r", encoding="utf-8") as _f:
            _d = json.load(_f)
        return _d if isinstance(_d, dict) else {}
    except Exception:
        return {}


def save_staged(rec):
    try:
        with open(STAGED_FILE, "w", encoding="utf-8") as _f:
            json.dump(rec, _f, ensure_ascii=False)
    except Exception:
        pass


def _run_stage_helper(mode, ipa_path, udid, bundle, timeout=300):
    """Run stage_install.py over a fresh RSD tunnel. Returns
    (rc, output): 0 = step done, 2 = Install sent but bundle not
    verified, anything else = helper/tunnel failure."""
    if not os.path.exists(STAGE_INSTALL_PY):
        return -1, "stage-helper-missing"
    udid = _resolve_udid(udid)
    proc, addr, port, log, via, _suspect = _start_tunnel_any(udid)
    if proc is None:
        return -1, "rsd-tunnel: " + (log or "no RSD address/port")[-240:]
    try:
        _cmd = [sys.executable, STAGE_INSTALL_PY, "--mode", mode,
                "--rsd-addr", addr, "--rsd-port", port]
        if ipa_path:
            _cmd += ["--ipa", ipa_path]
        if bundle:
            _cmd += ["--bundle", bundle]
        _dbg("stage request cmd=%s" % _dbg_mask_cmd(_cmd))
        try:
            r = subprocess.run(_cmd, capture_output=True, text=True, timeout=timeout)
            _full = (r.stdout or "") + "\n" + (r.stderr or "")
            _dbg("stage response rc=%s out=%s" % (r.returncode, _full.replace("\n", " | ")))
            return r.returncode, _full[-900:]
        except Exception as e:
            return -1, str(e)
    finally:
        _stop_rsd_tunnel(proc)


def stage_via_rsd(ipa_path, udid="", bundle=""):
    """Step 1: upload the signed IPA to PublicStaging. Returns
    (ok, details). Records the staged file in staged.json."""
    if not ipa_path or not os.path.exists(ipa_path):
        return False, "signed file not found on PC"
    rc, out = _run_stage_helper("stage", ipa_path, udid, bundle)
    if rc != 0:
        return False, out.strip()[-400:] or "stage helper failed"
    _size = 0
    for _line in out.splitlines():
        if _line.startswith("STAGE_OK"):
            try:
                _size = int(_line.split()[1])
            except Exception:
                _size = 0
    save_staged({"bundle": bundle, "path": ipa_path,
                 "remote": STAGED_REMOTE_PATH, "size": _size,
                 "at": datetime.now(timezone.utc).isoformat()})
    return True, out.strip()[-400:]


def install_staged_via_rsd(udid="", bundle=""):
    """Step 2: Install command for the staged file, then verify.
    Returns (ok, details, verified)."""
    rc, out = _run_stage_helper("install", "", udid, bundle)
    if rc == 0:
        return True, out.strip()[-400:], True
    if rc == 2:
        return False, out.strip()[-400:], False
    return False, out.strip()[-400:] or "stage helper failed", False


def stage_thread(chat_id):
    if not os.path.exists(STAGE_INSTALL_PY):
        send_message(chat_id, tr("stage_helper_missing"))
        return
    send_message(chat_id, tr("stage_starting"))
    _path = LAST_SIGNED.get("path", "")
    _udid = job.get("udid", "") or ""
    _bundle = LAST_SIGNED.get("bundle", "")
    if not _bundle and _path and os.path.exists(_path):
        _bundle = read_ipa_info(_path)[0] or ""
    ok, details = stage_via_rsd(_path, _udid, _bundle)
    try:
        with open(os.path.join(BASE_DIR, "stage-log.txt"), "a", encoding="utf-8") as _lf:
            _lf.write("%s stage ok=%s udid=...%s path=%s\n%s\n---\n" % (datetime.now(timezone.utc).isoformat(), ok, _udid[-4:], os.path.basename(_path or ""), (details or "")[-1200:]))
    except Exception:
        pass
    if ok:
        _st = load_staged()
        send_message(chat_id, tr("stage_ok") % (_st.get("remote", STAGED_REMOTE_PATH), _st.get("size", 0)))
    elif details.strip() == "stage-helper-missing":
        send_message(chat_id, tr("stage_helper_missing"))
    else:
        send_message(chat_id, tr("stage_fail") % details)
        if "rsd-tunnel:" in (details or "") and "Pass --udid" not in (details or ""):
            send_message(chat_id, tr("rsd_tunnel_hint"))


def install_staged_thread(chat_id):
    if not os.path.exists(STAGE_INSTALL_PY):
        send_message(chat_id, tr("stage_helper_missing"))
        return
    _st = load_staged()
    if not _st.get("bundle"):
        send_message(chat_id, tr("install_staged_nothing"))
        return
    send_message(chat_id, tr("install_staged_starting"))
    _udid = job.get("udid", "") or ""
    ok, details, verified = install_staged_via_rsd(_udid, _st["bundle"])
    try:
        with open(os.path.join(BASE_DIR, "stage-log.txt"), "a", encoding="utf-8") as _lf:
            _lf.write("%s install-staged ok=%s verified=%s bundle=%s\n%s\n---\n" % (datetime.now(timezone.utc).isoformat(), ok, verified, _st["bundle"], (details or "")[-1200:]))
    except Exception:
        pass
    if ok:
        send_message(chat_id, tr("install_staged_ok"))
    elif details.strip() == "stage-helper-missing":
        send_message(chat_id, tr("stage_helper_missing"))
    elif "INSTALL_UNVERIFIED" in (details or ""):
        send_message(chat_id, tr("install_staged_unverified") % (_st["bundle"], details[-300:]))
    else:
        send_message(chat_id, tr("install_staged_fail") % details)
        if "rsd-tunnel:" in (details or "") and "Pass --udid" not in (details or ""):
            send_message(chat_id, tr("rsd_tunnel_hint"))


# TAILSCALE OTA 2026-10-27 -------------------------------------------
# Local HTTP server on 127.0.0.1 only (the only proxy target
# Tailscale Serve accepts) + `tailscale serve --bg <port>`, so the
# phone can install from another Wi-Fi / 5G via the tailnet HTTPS
# URL. MIME is load-bearing: iOS will not start the install if the
# manifest arrives as application/octet-stream; it must be text/xml.
# Writes are atomic (.part -> os.replace) and each publish gets a
# timestamped filename, so a stale cached manifest/IPA cannot be
# served and a phone cannot download a half-written file. The
# newest 3 publishes are kept, so older Serve links survive a
# re-sign; the server starts at bot startup, so they also
# survive a bot restart. Requests are logged to
# ota-access-log.txt on Linux for OTA failure diagnosis.
_OTA_SERVER = {"httpd": None, "started": False}
_TAILSCALE_SERVE_OK = False


class _OtaHandler(http.server.SimpleHTTPRequestHandler):
    extensions_map = dict(http.server.SimpleHTTPRequestHandler.extensions_map)
    extensions_map.update({".plist": "text/xml", ".ipa": "application/octet-stream"})

    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=OTA_DIR, **kwargs)

    def _serve_file(self, send_body):
        """Serve one file with HTTP Range support. The stock
        SimpleHTTPRequestHandler on some Python versions
        ignores Range and always returns 200; installd fetches
        the IPA with Range requests, so partial/resumed
        downloads must answer 206 with a correct Content-Range.
        This implementation is version-independent."""
        _path = self.translate_path(self.path)
        if os.path.isdir(_path):
            # BUG FIX 2026-11-14: a directory used to get the stock
            # SimpleHTTPRequestHandler listing. The same server is exposed
            # through the public tunnel, so anyone with the URL could list
            # every published IPA and manifest. There is nothing to list.
            self.send_error(404, "File not found")
            return
        try:
            _f = open(_path, "rb")
        except OSError:
            self.send_error(404, "File not found")
            return
        _size = os.fstat(_f.fileno()).st_size
        _ctype = self.guess_type(_path)
        _range = self.headers.get("Range", "")
        _start, _end, _status = 0, _size - 1, 200
        _m = re.fullmatch(r"bytes=(\d*)-(\d*)", (_range or "").strip())
        if _range:
            if not _m:
                self.send_response(416)
                self.send_header("Content-Range", "bytes */%d" % _size)
                self.send_header("Accept-Ranges", "bytes")
                self.end_headers()
                _f.close()
                return
            _a, _b = _m.group(1), _m.group(2)
            if _a:
                _start = int(_a)
                _end = int(_b) if _b else _size - 1
            elif _b:
                # Suffix range: bytes=-N means the last N bytes.
                _start = max(0, _size - int(_b))
                _end = _size - 1
            else:
                _start, _end = 0, _size - 1
            if _start >= _size or _end < _start:
                self.send_response(416)
                self.send_header("Content-Range", "bytes */%d" % _size)
                self.send_header("Accept-Ranges", "bytes")
                self.end_headers()
                _f.close()
                return
            _end = min(_end, _size - 1)
            _status = 206
        try:
            self.send_response(_status)
            self.send_header("Content-Type", _ctype)
            self.send_header("Content-Length", str(_end - _start + 1))
            self.send_header("Accept-Ranges", "bytes")
            if _status == 206:
                self.send_header("Content-Range",
                                 "bytes %d-%d/%d" % (_start, _end, _size))
            self.send_header("Last-Modified",
                             self.date_time_string(os.path.getmtime(_path)))
            if _path.endswith(".plist"):
                self.send_header("Cache-Control", "no-cache, no-store")
            self.end_headers()
            if send_body:
                _f.seek(_start)
                shutil.copyfileobj(_f, self.wfile, _end - _start + 1)
        finally:
            _f.close()

    def _keepalive_llm_get(self):
        _path = urllib.parse.urlsplit(self.path).path
        if _path not in ("/v1/models", "/models"):
            return False
        _body = json.dumps({
            "object": "list",
            "data": [{
                "id": "sidebot-keepalive",
                "object": "model",
                "created": 1700000000,
                "owned_by": "sidebot",
            }],
        }).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(_body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(_body)
        return True

    def _keepalive_llm_post(self):
        self.close_connection = True
        try:
            _clen = int(self.headers.get("Content-Length") or 0)
        except Exception:
            _clen = 0
        _raw = self.rfile.read(min(_clen, 1048576)) if _clen > 0 else b"{}"
        try:
            _req = json.loads(_raw.decode("utf-8", "replace")) if _raw else {}
        except Exception:
            _req = {}
        _model = str((_req or {}).get("model") or "sidebot-keepalive")
        _stream = bool((_req or {}).get("stream", False))
        if not _stream:
            _body = json.dumps({
                "id": "chatcmpl-keepalive",
                "object": "chat.completion",
                "created": int(time.time()),
                "model": _model,
                "choices": [{
                    "index": 0,
                    "message": {"role": "assistant", "content": "SideBot keep-alive active."},
                    "finish_reason": "stop",
                }],
                "usage": {"prompt_tokens": 1, "completion_tokens": 4, "total_tokens": 5},
            }).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(_body)))
            self.end_headers()
            self.wfile.write(_body)
            return
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream; charset=utf-8")
        self.send_header("Cache-Control", "no-cache")
        self.send_header("Connection", "close")
        self.end_headers()
        _cid = "chatcmpl-ka-%d" % int(time.time())
        def _send_chunk(delta, finish=None):
            _payload = json.dumps({
                "id": _cid,
                "object": "chat.completion.chunk",
                "created": int(time.time()),
                "model": _model,
                "choices": [{"index": 0, "delta": delta, "finish_reason": finish}],
            }, ensure_ascii=False)
            self.wfile.write(("data: %s\n\n" % _payload).encode("utf-8"))
            self.wfile.flush()
        try:
            _send_chunk({"role": "assistant", "content": "🟢 SideBot keep-alive активний. Можеш згортати Minis — бот не засне."})
            for _ in range(720):
                time.sleep(10)
                _send_chunk({"content": " "})
            _send_chunk({}, finish="stop")
            self.wfile.write(b"data: [DONE]\n\n")
            self.wfile.flush()
        except (BrokenPipeError, ConnectionResetError, OSError):
            pass

    def _keepalive_assets_get(self):
        _path = urllib.parse.urlsplit(self.path).path
        _map = {
            "/sidebot-keepalive.shortcut": (
                "Sidebot+keepalive.shortcut",
                "application/octet-stream",
            ),
            "/sidebot-keepalive.mobileconfig": (
                "sidebot-keepalive-webclip.mobileconfig",
                "application/x-apple-aspen-config",
            ),
            "/appstore-icon.png": (
                "appstore-icon.png",
                "image/png",
            ),
        }
        if _path == "/manifest.json":
            _man = json.dumps({
                "name": "SideBot",
                "short_name": "SideBot",
                "start_url": "/sidebot.html",
                "scope": "/",
                "display": "standalone",
                "background_color": "#000000",
                "theme_color": "#000000",
                "icons": [{"src": "/sidebot-icon.png", "sizes": "180x180", "type": "image/png"}],
            }).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/manifest+json; charset=utf-8")
            self.send_header("Content-Length", str(len(_man)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            try:
                self.wfile.write(_man)
            except Exception:
                pass
            return True
        if _path == "/miniapp-botlog":
            _out = []
            for _ln_p, _lbl_p, _n in (
                (os.path.join(BASE_DIR, "install-log.txt"), "=== install-log.txt (останні 180) ===", 180),
                ("/tmp/bot.log", "=== /tmp/bot.log (останні 120) ===", 120),
                (os.path.join(BASE_DIR, "pair-log.txt"), "=== pair-log.txt (останні 60) ===", 60),
            ):
                if os.path.isfile(_ln_p):
                    try:
                        with open(_ln_p, "r", encoding="utf-8", errors="ignore") as _lf:
                            _lines = _lf.readlines()[-_n:]
                        _out.append(_lbl_p + "\n" + "".join(_lines))
                    except Exception as _le:
                        _out.append(_lbl_p + "\nerror: " + str(_le))
            _txt = "\n".join(_out) or "(logs empty)"
            _tb = _txt.encode("utf-8", errors="replace")
            self.close_connection = True
            self.send_response(200)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", str(len(_tb)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            try:
                self.wfile.write(_tb)
            except Exception:
                pass
            return True
        if _path == "/miniapp-cert-export":
            _qs = urllib.parse.parse_qs(_u.query)
            _cid = (_qs.get("cid") or [""])[0].strip()
            _kind = (_qs.get("kind") or ["p12"])[0].strip().lower()
            _target = ""
            if _cid and _cid != "builtin":
                _rec = _feather_cert_find(_feather_certs_load(), _cid)
                if _rec:
                    _target = _feather_cert_abs(_rec, "provision" if _kind == "provision" else "p12") or ""
            else:
                if _kind == "provision":
                    if PROVISION_PATH and os.path.isfile(PROVISION_PATH):
                        _target = PROVISION_PATH
                    else:
                        _cands = []
                        for _d in (BASE_DIR, os.path.join(BASE_DIR, "profiles")):
                            if os.path.isdir(_d):
                                for _fn in os.listdir(_d):
                                    if _fn.lower().endswith(".mobileprovision"):
                                        _fp = os.path.join(_d, _fn)
                                        if os.path.isfile(_fp):
                                            _cands.append(_fp)
                        if _cands:
                            _cands.sort(key=lambda p: os.path.getmtime(p), reverse=True)
                            _target = _cands[0]
                else:
                    if P12_PATH and os.path.isfile(P12_PATH):
                        _target = P12_PATH
                    else:
                        _cands = []
                        for _d in (BASE_DIR, os.path.join(BASE_DIR, "profiles")):
                            if os.path.isdir(_d):
                                for _fn in os.listdir(_d):
                                    if _fn.lower().endswith(".p12"):
                                        _fp = os.path.join(_d, _fn)
                                        if os.path.isfile(_fp):
                                            _cands.append(_fp)
                        if _cands:
                            _cands.sort(key=lambda p: os.path.getmtime(p), reverse=True)
                            _target = _cands[0]
            if not _target or not os.path.isfile(_target):
                self.send_error(404, "File not found")
                return True
            with open(_target, "rb") as _cf:
                _cb = _cf.read()
            _fn_out = os.path.basename(_target) or ("cert.mobileprovision" if _kind == "provision" else "cert.p12")
            self.send_response(200)
            self.send_header("Content-Type", "application/octet-stream" if _kind == "provision" else "application/x-pkcs12")
            self.send_header("Content-Disposition", 'attachment; filename="%s"' % _fn_out)
            self.send_header("Content-Length", str(len(_cb)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            try:
                self.wfile.write(_cb)
            except Exception:
                pass
            return True
        if _path == "/miniapp-pairing-export":
            _ps = _list_pairings()
            if not _ps:
                self.send_error(404, "No pairing file")
                return True
            _fp = os.path.join(_pairing_dir(), _ps[0]["name"])
            if not os.path.isfile(_fp):
                self.send_error(404, "Not found")
                return True
            with open(_fp, "rb") as _pf:
                _pdata = _pf.read()
            self.close_connection = True
            self.send_response(200)
            self.send_header("Content-Type", "application/octet-stream")
            self.send_header("Content-Disposition", 'attachment; filename="%s"' % _ps[0]["name"])
            self.send_header("Content-Length", str(len(_pdata)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            try:
                self.wfile.write(_pdata)
            except Exception:
                pass
            return True
        if _path == "/udid.mobileconfig":
            import plistlib, uuid as _uuid
            _lp = ENV.get("OTA_PORT", "8080").strip() or "8080"
            _prof = {
                "PayloadContent": {
                    "URL": "http://127.0.0.1:%s/miniapp-udid-cb" % _lp,
                    "DeviceAttributes": ["UDID", "PRODUCT", "VERSION", "SERIAL"],
                },
                "PayloadOrganization": "SideBot",
                "PayloadDisplayName": "SideBot Device UDID",
                "PayloadVersion": 1,
                "PayloadUUID": str(_uuid.uuid4()).upper(),
                "PayloadIdentifier": "com.sidebot.udid.service",
                "PayloadDescription": "Отримати UDID цього iPhone для підпису додатків",
                "PayloadType": "Profile Service",
            }
            _mc = plistlib.dumps(_prof)
            self.send_response(200)
            self.send_header("Content-Type", "application/x-apple-aspen-config")
            self.send_header("Content-Disposition", 'attachment; filename="SideBot-UDID.mobileconfig"')
            self.send_header("Content-Length", str(len(_mc)))
            self.end_headers()
            try:
                self.wfile.write(_mc)
            except Exception:
                pass
            return True
        if _path.startswith("/ota/"):
            _fn = os.path.basename(_path[5:].split("?", 1)[0])
            _fp = os.path.join(OTA_DIR, _fn)
            if not _fn or not os.path.isfile(_fp):
                self.send_error(404)
                return True
            _ct = "application/octet-stream" if _fn.endswith(".ipa") else ("application/xml" if _fn.endswith(".plist") else "application/octet-stream")
            try:
                _sz = os.path.getsize(_fp)
                self.send_response(200)
                self.send_header("Content-Type", _ct)
                self.send_header("Content-Length", str(_sz))
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                with open(_fp, "rb") as _of:
                    while True:
                        _chunk = _of.read(65536)
                        if not _chunk:
                            break
                        self.wfile.write(_chunk)
            except Exception:
                pass
            return True
        if _path in ("/sidebot.mobileconfig", "/appstore.mobileconfig"):
            import plistlib, uuid as _uuid
            _is_as = (_path == "/appstore.mobileconfig")
            _lp = ENV.get("OTA_PORT", "8080").strip() or "8080"
            _lbl = "App Store" if _is_as else "SideBot"
            _url = ("http://127.0.0.1:%s/appstore.html" if _is_as else "http://127.0.0.1:%s/sidebot.html") % _lp
            _icon_fn = "appstore-icon.png" if _is_as else "sidebot-icon.png"
            _icon_p = os.path.join(BASE_DIR, _icon_fn)
            _wc = {
                "FullScreen": True,
                "IgnoreManifestScope": True,
                "IsRemovable": True,
                "Label": _lbl,
                "PayloadDescription": "Web Clip for " + _lbl,
                "PayloadDisplayName": _lbl + " Web Clip",
                "PayloadIdentifier": "com.sidebot.webclip." + ("appstore" if _is_as else "main"),
                "PayloadType": "com.apple.webClip.managed",
                "PayloadUUID": str(_uuid.uuid4()).upper(),
                "PayloadVersion": 1,
                "Precomposed": True,
                "URL": _url,
            }
            if os.path.isfile(_icon_p):
                try:
                    with open(_icon_p, "rb") as _icf:
                        _wc["Icon"] = _icf.read()
                except Exception:
                    pass
            _prof = {
                "PayloadContent": [_wc],
                "PayloadDisplayName": _lbl + " (Local)",
                "PayloadIdentifier": "com.sidebot.profile." + ("appstore" if _is_as else "main"),
                "PayloadRemovalDisallowed": False,
                "PayloadType": "Configuration",
                "PayloadUUID": str(_uuid.uuid4()).upper(),
                "PayloadVersion": 1,
            }
            _mc = plistlib.dumps(_prof)
            self.send_response(200)
            self.send_header("Content-Type", "application/x-apple-aspen-config")
            self.send_header("Content-Disposition", 'attachment; filename="%s.mobileconfig"' % _lbl.replace(" ", ""))
            self.send_header("Content-Length", str(len(_mc)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            try:
                self.wfile.write(_mc)
            except Exception:
                pass
            return True
        _spec = _map.get(_path)
        if not _spec:
            return False
        _fn, _ctype = _spec
        _fp = os.path.join(BASE_DIR, _fn)
        if not os.path.isfile(_fp):
            self.send_error(404, "Not found")
            return True
        try:
            with open(_fp, "rb") as _f:
                _data = _f.read()
            self.send_response(200)
            self.send_header("Content-Type", _ctype)
            self.send_header("Content-Length", str(len(_data)))
            if _fn.endswith((".shortcut", ".mobileconfig")):
                self.send_header("Content-Disposition", 'attachment; filename="%s"' % _fn)
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(_data)
        except (BrokenPipeError, ConnectionResetError, OSError):
            pass
        return True

    def _appstore_ipa_get(self):
        _u = urllib.parse.urlsplit(self.path)
        if _u.path != "/appstore-api/ipa":
            return False
        _qs = urllib.parse.parse_qs(_u.query or "")
        _tok = (_qs.get("t") or [""])[0].strip()
        _ip = (self.client_address[0] if self.client_address else "")
        if _ip not in ("127.0.0.1", "::1") and not _miniapp_launch_token_check(_tok):
            self.send_error(403, "Forbidden")
            return True
        _fn = (_qs.get("file") or [""])[0].strip()
        _fp = _appstore_safe_ipa(_fn)
        if not _fp:
            self.send_error(404, "Not found")
            return True
        try:
            _sz = os.path.getsize(_fp)
            _bn = os.path.basename(_fp)
            self.send_response(200)
            self.send_header("Content-Type", "application/octet-stream")
            self.send_header("Content-Length", str(_sz))
            self.send_header("Content-Disposition", 'attachment; filename="%s"' % _bn.replace('"', ""))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            with open(_fp, "rb") as _f:
                shutil.copyfileobj(_f, self.wfile, 65536)
        except (BrokenPipeError, ConnectionResetError, OSError):
            pass
        return True

    def do_GET(self):
        if self._keepalive_llm_get():
            return
        if self._keepalive_assets_get():
            return
        if self._appstore_ipa_get():
            return
        if self._sap_proxy_http("GET"):
            return
        if self._serve_miniapp(True):
            return
        self._serve_file(True)

    def do_HEAD(self):
        if self._serve_miniapp(False):
            return
        self._serve_file(False)

    def do_POST(self):
        _path = urllib.parse.urlsplit(self.path).path
        if _path in ("/v1/chat/completions", "/chat/completions"):
            self._keepalive_llm_post()
            return
        if _path == "/miniapp-upload":
            self.close_connection = True
            try:
                _miniapp_upload(self)
            except Exception:
                try:
                    self._miniapp_api_reply(
                        500, {"ok": False, "error": "internal"})
                except Exception:
                    pass
            return
        if _path == "/miniapp-dylib":
            self.close_connection = True
            try:
                _miniapp_dylib_upload(self)
            except Exception:
                try:
                    self._miniapp_api_reply(
                        500, {"ok": False, "error": "internal"})
                except Exception:
                    pass
            return
        if _path == "/miniapp-pairing":
            self.close_connection = True
            try:
                _miniapp_pairing_upload(self)
            except Exception:
                try:
                    self._miniapp_api_reply(
                        500, {"ok": False, "error": "internal"})
                except Exception:
                    pass
            return
        if _path == "/miniapp-update":
            self.close_connection = True
            try:
                _miniapp_update_upload(self)
            except Exception:
                try:
                    self._miniapp_api_reply(
                        500, {"ok": False, "error": "internal"})
                except Exception:
                    pass
            return
        if _path.startswith("/appstore-api/sap-proxy"):
            self._sap_proxy_http("POST")
            return
        if _path.startswith("/appstore-api"):
            self._appstore_api_http(_path)
            return
        if _path.startswith("/miniapp-api"):
            self._miniapp_api(_path)
            return
        self.send_error(404, "Not found")

    def _appstore_api_http(self, path):
        """POST /appstore-api/* — JSON in, JSON out.

        Same trust model as /miniapp-api: the bot-issued launch
        token from the page URL (?t=) first, Telegram initData as
        the fallback, everything else 403 with no information. The
        page and the API share an origin, so there is no CORS and
        no cookie to leak; credentials (Apple ID password, 2FA
        code) travel in the POST body only and are never logged.
        """
        try:
            _n = int(self.headers.get("Content-Length") or 0)
        except Exception:
            _n = 0
        # The store proof state (files written by Apple's store libraries)
        # travels through sap-result and can be far larger than an
        # ordinary API body; everything else stays at 64 KB.
        _max = 16 * 1024 * 1024 if path.startswith("/appstore-api/sap-") else 65536
        if _n <= 0 or _n > _max:
            self._miniapp_api_reply(400, {"ok": False, "error": "bad request"})
            return
        try:
            _body = json.loads(self.rfile.read(_n).decode("utf-8"))
        except Exception:
            self._miniapp_api_reply(400, {"ok": False, "error": "bad request"})
            return
        if not isinstance(_body, dict):
            self._miniapp_api_reply(400, {"ok": False, "error": "bad request"})
            return
        _uid, _why = _miniapp_api_auth(_body, self)
        if _uid is None:
            _miniapp_api_note(path, 403, _why)
            _dbg("appstore_api 403 path=%s why=%s" % (path, _why))
            self._miniapp_api_reply(403, {"ok": False, "error": "forbidden", "text": "403: " + str(_why)})
            return
        _t0 = time.time()
        _act_k = path.rsplit("/", 1)[-1]
        if "_APPSTORE_INFLIGHT" not in globals():
            globals()["_APPSTORE_INFLIGHT"] = {}
        _APPSTORE_INFLIGHT[_act_k] = _APPSTORE_INFLIGHT.get(_act_k, 0) + 1
        if _act_k not in ("auth", "downloads", "log", "sap-result"):
            _dbg("api_start %s inflight=%s" % (_act_k, dict(_APPSTORE_INFLIGHT)))
        try:
            _resp = _appstore_api(path, _body, _uid)
        except Exception as e:
            _miniapp_api_note(path, 500, "exception")
            _dbg("appstore_api 500 path=%s err=%s" % (path, str(e)[:160]))
            import traceback
            traceback.print_exc()
            _resp = {"ok": False, "text": "internal error: " + str(e)[:120]}
        finally:
            _APPSTORE_INFLIGHT[_act_k] = max(0, _APPSTORE_INFLIGHT.get(_act_k, 1) - 1)
            if _APPSTORE_INFLIGHT[_act_k] == 0:
                _APPSTORE_INFLIGHT.pop(_act_k, None)
        _ms = int((time.time() - _t0) * 1000)
        if not isinstance(_resp, dict):
            _resp = {"ok": False, "text": "internal error"}
        if not _resp.get("ok", True) or _ms > 2000:
            _dbg("appstore_api path=%s ms=%d ok=%s txt=%s" % (path, _ms, _resp.get("ok"), str(_resp.get("text") or _resp.get("error") or "")[:80]))
        self._miniapp_api_reply(200, _resp)

    def _sap_proxy_http(self, method):
        """Transparent pass-through for Apple's SAP/provisioning calls.

        sap-signer.js runs in the page and cannot read s.mzstatic.com,
        fpinit.itunes.apple.com or auth.itunes.apple.com/auth/v1/otp
        cross-origin; it calls this endpoint instead and gets Apple's
        own status and bytes back. Host, path and method are fixed by
        SAP_PROXY_TARGETS and the launch token rides in the path, so
        this is neither an open relay nor a way to reach anything but
        those four Apple URLs.
        """
        try:
            _parts = urllib.parse.urlsplit(self.path)
            _segs = [x for x in _parts.path.split("/") if x]
        except Exception:
            return False
        if len(_segs) < 3 or _segs[0] != "appstore-api" or _segs[1] != "sap-proxy":
            return False
        _uid, _why = _miniapp_api_auth(
            {"token": urllib.parse.unquote(_segs[2])}, self)
        if _uid is None:
            self.send_error(403, "forbidden")
            return True
        try:
            _q = urllib.parse.parse_qs(_parts.query)
            _target = (_q.get("url") or [""])[0]
        except Exception:
            _target = ""
        _up = urllib.parse.urlsplit(_target)
        _allowed = False
        for _host, _apath, _amethod in SAP_PROXY_TARGETS:
            if (method == _amethod and _up.scheme == "https"
                    and (_up.hostname or "").lower() == _host
                    and _up.path == _apath):
                _allowed = True
                break
        if not _allowed:
            self.send_error(403, "target not allowed")
            return True
        _body = b""
        if method == "POST":
            try:
                _n = int(self.headers.get("Content-Length") or 0)
            except Exception:
                _n = 0
            if _n <= 0 or _n > SAP_PROXY_MAX_BYTES:
                self.send_error(400, "bad body")
                return True
            _body = self.rfile.read(_n)
        _finish = _up.path.endswith("/finish")
        _ctype = self.headers.get("Content-Type") or ""
        _hdrs = {"User-Agent": SAP_UA, "Accept": "*/*"}
        if method == "POST":
            if not _ctype.startswith("application/"):
                _ctype = "application/x-apple-plist" if _finish else "application/x-plist"
            _hdrs["Content-Type"] = _ctype
        _status, _out, _otype = 502, b"", "application/octet-stream"
        try:
            _req = urllib.request.Request(
                _target, data=(_body if method == "POST" else None),
                method=method, headers=_hdrs)
            with urllib.request.urlopen(_req, timeout=90) as _resp:
                _status = _resp.status
                _out = _resp.read(SAP_PROXY_MAX_BYTES + 1)
                _otype = _resp.headers.get("Content-Type") or _otype
        except urllib.error.HTTPError as _he:
            _status = _he.code
            _otype = _he.headers.get("Content-Type") or _otype
            try:
                _out = _he.read(SAP_PROXY_MAX_BYTES + 1)
            except Exception:
                _out = b""
        except Exception as _e:
            _status = 502
            _out = str(_e)[:200].encode("utf-8", "replace")
        if len(_out) > SAP_PROXY_MAX_BYTES:
            _status, _out = 502, b"response too large"
        elif _finish and _out:
            # The page's store-proof code parses an XML plist; Apple
            # sometimes answers the finish call with a binary one.
            try:
                _pl = plistlib.loads(_out)
                _out = plistlib.dumps(_pl, fmt=plistlib.FMT_XML)
                _otype = "application/x-apple-plist"
            except Exception:
                pass
        try:
            self.send_response(_status)
            self.send_header("Content-Type", _otype)
            self.send_header("Content-Length", str(len(_out)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(_out)
        except Exception:
            pass
        return True

    def _serve_sap_runtime(self, path, body):
        """GET /sap-runtime/<file> — the vendored iPadn runtime and the
        small bridge page, served from sap-runtime/ beside the bot.

        Same origin as the page, so the WASM and the .so files load
        without CORS. Nothing secret is here: these are public iPadn
        vendor files, and the bridge holds no token (the page passes it
        in at init, and the proxy carries it in its path).
        """
        try:
            _name = urllib.parse.unquote(path[len("/sap-runtime/"):])
        except Exception:
            return True
        if not _name or "/" in _name or "\\" in _name or ".." in _name:
            self.send_error(404, "not found")
            return True
        if _name == "sap-bridge.html":
            _data = SAP_BRIDGE_HTML.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(_data)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            if body:
                try:
                    self.wfile.write(_data)
                except Exception:
                    pass
            return True
        if _name not in SAP_RUNTIME_TYPES:
            self.send_error(404, "not found")
            return True
        # No gzip: serve the file as-is. The browser runs on the same
        # phone (localhost), so compressing only burns CPU in the bot
        # process (GIL) and stalls the whole bot on first AppStore open.
        _p = _sap_runtime_path(_name)
        try:
            _size = os.path.getsize(_p)
            _f = open(_p, "rb")
        except Exception:
            self.send_error(404, "%s not downloaded yet" % _name)
            return True
        try:
            _cache = ("public, max-age=604800" if _name != "index.html"
                      else "no-store")
            self.send_response(200)
            self.send_header("Content-Type", SAP_RUNTIME_TYPES[_name])
            self.send_header("Content-Length", str(_size))
            self.send_header("Cache-Control", _cache)
            self.end_headers()
            if body:
                shutil.copyfileobj(_f, self.wfile)
        except Exception:
            pass
        finally:
            try:
                _f.close()
            except Exception:
                pass
        return True

    def _miniapp_api_reply(self, code, obj):
        try:
            _raw = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        except Exception:
            _raw = b'{"ok": false}'
            code = 500
        try:
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(_raw)))
            self.end_headers()
            self.wfile.write(_raw)
        except Exception:
            pass

    def _miniapp_api(self, path):
        """SideBot in-app API (2026-11-11, win-inapp): POST JSON
        {token, ...} — same origin as miniapp.html, so no CORS
        and no Telegram dependency. Auth is the bot-issued launch
        token from the Mini App URL (token-first), with Telegram
        initData HMAC validation as fallback; anything else is
        403 with no information. Credentials travel in the POST
        body only, so they never appear in the URL and never land
        in the access log (log_message records the request line
        only — and redacts the launch token from it anyway)."""
        try:
            _n = int(self.headers.get("Content-Length") or 0)
        except Exception:
            _n = 0
        if _n <= 0 or _n > 65536:
            _miniapp_api_note(path, 400, "bad-request")
            self._miniapp_api_reply(400, {"ok": False, "error": "bad request"})
            return
        try:
            _body = json.loads(self.rfile.read(_n).decode("utf-8"))
        except Exception:
            _miniapp_api_note(path, 400, "bad-request")
            self._miniapp_api_reply(400, {"ok": False, "error": "bad request"})
            return
        if not isinstance(_body, dict):
            _miniapp_api_note(path, 400, "bad-request")
            self._miniapp_api_reply(400, {"ok": False, "error": "bad request"})
            return
        _uid, _why = _miniapp_api_auth(_body, self)
        if _uid is None:
            _miniapp_api_note(path, 403, _why)
            self._miniapp_api_reply(403, {"ok": False, "error": "forbidden"})
            return
        # Path aliases (2026-11-14, minis-sidestore1): the SideStore
        # endpoints are addressable by name — /miniapp-api/refresh-all,
        # /miniapp-api/jit, /miniapp-api/certs, /miniapp-api/appids,
        # /miniapp-api/install — while a body `action` stays the
        # canonical command. The path fills the action in only when
        # the body omits it, so /miniapp-api + action keeps working
        # unchanged (the page's own calls).
        if path.startswith("/miniapp-api/") and not _body.get("action"):
            _seg = path.rsplit("/", 1)[-1]
            _alias = {"refresh-all": "refresh_all",
                      "appids": "app_ids",
                      "signopts": "sign_opts_get",
                      "sign-opts": "sign_opts_get",
                      "cell": "set_cell",
                      "auto": "set_auto",
                      "certs": "certs"}
            _act = _alias.get(_seg) or _seg.replace("-", "_")
            if _act:
                _body["action"] = _act
        try:
            if path == "/miniapp-api/state":
                _miniapp_api_note(path, 200, _why)
                self._miniapp_api_reply(200, {"ok": True,
                                              "state": _miniapp_state()})
            elif path == "/miniapp-api/status":
                _job = _miniapp_job_get(str(_body.get("job") or ""))
                if _job is None:
                    _miniapp_api_note(path, 404, "unknown-job")
                    self._miniapp_api_reply(404, {"ok": False,
                                                  "error": "unknown job"})
                else:
                    # Every poll marks the job polled: that is
                    # what tells the bot the app is still open,
                    # so prompts and final results stay in-app
                    # instead of falling back to chat.
                    _miniapp_job_touch(str(_body.get("job") or ""))
                    _resp = {"ok": True, "status": _job["status"],
                             "text": _job.get("text", ""),
                             "kind": _job.get("kind", "")}
                    if _job.get("pct") is not None:
                        _resp["pct"] = _job["pct"]
                    _jlogs = _job.get("logs")
                    if not _jlogs:
                        with _INSTALL_LIVE_LOCK:
                            _jlogs = list(_INSTALL_LIVE_LINES)
                    if _jlogs:
                        _resp["logs"] = _jlogs
                    if _job.get("options"):
                        _resp["options"] = _job["options"]
                    # Cellular Refresh toggle handshake
                    # (2026-11-12, win-cellside): rides on every
                    # poll, including the terminal one — the page
                    # opens the shortcut before it stops polling.
                    if _job.get("toggle"):
                        _resp["toggle"] = _job["toggle"]
                        _resp["toggle_name"] = _job.get("toggle_name", "")
                    if _job.get("open_url"):
                        _resp["open_url"] = _job["open_url"]
                    _miniapp_api_note(path, 200, _why)
                    self._miniapp_api_reply(200, _resp)
            elif path == "/miniapp-api/2fa":
                # 2FA code from the app into the waiting flow.
                # The code travels in the POST body only (never
                # in the URL, never in a log) and is handed to
                # the flow exactly like a chat message.
                _ok, _text = _miniapp_api_feed_code(
                    str(_body.get("job") or ""), _body.get("code") or "")
                _miniapp_api_note(path, 200 if _ok else 400,
                                  "ok" if _ok else "rejected")
                self._miniapp_api_reply(200 if _ok else 400,
                                        {"ok": _ok, "text": _text})
            elif path == "/miniapp-api/2fa-choice":
                _ok, _text = _miniapp_api_feed_choice(
                    str(_body.get("job") or ""), _body.get("choice") or "",
                    _body.get("code") or "")
                _miniapp_api_note(path, 200 if _ok else 400,
                                  "ok" if _ok else "rejected")
                self._miniapp_api_reply(200 if _ok else 400,
                                        {"ok": _ok, "text": _text})
            elif path == "/miniapp-udid-cb":
                import plistlib
                _clen = int(self.headers.get("Content-Length", "0") or 0)
                _raw_cb = self.rfile.read(min(_clen, 262144)) if _clen > 0 else b""
                _u_found = ""
                try:
                    _s_idx = _raw_cb.find(b"<?xml")
                    _e_idx = _raw_cb.find(b"</plist>")
                    if _s_idx >= 0 and _e_idx > _s_idx:
                        _pl = plistlib.loads(_raw_cb[_s_idx:_e_idx + len(b"</plist>")])
                        _u_found = str(_pl.get("UDID") or "").strip()
                except Exception:
                    pass
                if _u_found:
                    try:
                        with open(os.path.join(BASE_DIR, "device_udid.txt"), "w", encoding="utf-8") as _df:
                            _df.write(_u_found)
                        _profs = load_profiles()
                        for _p in _profs:
                            _p["udid"] = _u_found
                        save_profiles(_profs)
                        job["udid"] = _u_found
                    except Exception:
                        pass
                _lp = ENV.get("OTA_PORT", "8080").strip() or "8080"
                self.send_response(301)
                self.send_header("Location", "http://127.0.0.1:%s/miniapp.html?udid=%s" % (_lp, urllib.parse.quote(_u_found)))
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
            elif path == "/miniapp-api/revoke":
                _ok, _text = _miniapp_api_feed_revoke(
                    str(_body.get("job") or ""),
                    str(_body.get("choice") or "0"))
                _miniapp_api_note(path, 200 if _ok else 400,
                                  "ok" if _ok else "rejected")
                self._miniapp_api_reply(200 if _ok else 400,
                                        {"ok": _ok, "text": _text})
            else:
                _miniapp_api_note(path, 200, _why)
                self._miniapp_api_reply(200,
                                        _miniapp_api_dispatch(_body, _uid))
        except Exception as e:
            _miniapp_api_note(path, 500, "exception")
            print("miniapp api failed: %s" % e, flush=True)
            self._miniapp_api_reply(500, {"ok": False, "error": "internal"})

    def _serve_miniapp(self, body):
        """The Telegram Mini App page (BASE_DIR/miniapp.html).

        Served from the bot folder, NOT from the OTA dir, and
        only on the exact /miniapp.html path (query string
        allowed — the state rides in ?s=). Reachable only via
        the tunnel (127.0.0.1 bind), localhost-only. The page
        holds no secrets; every action goes back through the
        bot with an owner check. Returns True when handled.
        """
        try:
            _path = urllib.parse.urlsplit(self.path).path
        except Exception:
            return False
        if _path.startswith("/sap-runtime/"):
            return self._serve_sap_runtime(_path, body)
        if _path == "/jit":
            # JIT hand-off page (minis-sidestore1): the Mini App
            # opens this https URL in Safari because a raw
            # stikdebug:// link dies in Telegram's WebView. The
            # launch token is required, so the tunnel URL alone
            # cannot be used to bounce a stranger into StikDebug.
            try:
                _q = urllib.parse.parse_qs(
                    urllib.parse.urlsplit(self.path).query)
            except Exception:
                _q = {}
            _tok = (_q.get("t") or [""])[0]
            _b = (_q.get("b") or [""])[0]
            _uid, _why = _miniapp_api_auth({"token": _tok}, self)
            if _uid is None or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9.-]{1,150}", _b or ""):
                self.send_error(403, "forbidden")
                return True
            _raw = _miniapp_jit_page(_b).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(_raw)))
            self.end_headers()
            if body:
                self.wfile.write(_raw)
            return True
        if _path in ("/cell-off", "/cell-on"):
            _which = "off" if _path == "/cell-off" else "on"
            _names = _ms_get("cell_names") or {}
            _sc = (_names.get(_which) if isinstance(_names, dict) else "") or ("TurnOffData" if _which == "off" else "TurnOnData")
            _sc_url = "shortcuts://run-shortcut?name=" + urllib.parse.quote(_sc)
            _raw = (
                "<!doctype html><html><head><meta charset='utf-8'>"
                "<meta name='viewport' content='width=device-width,initial-scale=1'>"
                "<title>%s</title></head>"
                "<body style='background:#121212;color:#fff;font-family:-apple-system,sans-serif;text-align:center;padding:48px 20px'>"
                "<h3>%s</h3>"
                "<p><a href='%s' style='display:inline-block;padding:14px 24px;background:#2E8B7A;color:#fff;border-radius:12px;text-decoration:none;font-weight:700'>Open %s</a></p>"
                "<script>setTimeout(function(){location.href=%r;},150);</script>"
                "</body></html>"
            ) % (html.escape(_sc), html.escape(_sc), html.escape(_sc_url), html.escape(_sc), _sc_url)
            _b = _raw.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(_b)))
            self.end_headers()
            if body:
                self.wfile.write(_b)
            return True
        if _path == "/sidebot-icon.png":
            import base64 as _b64
            _png = _b64.b64decode("")
            self.send_response(200)
            self.send_header("Content-Type", "image/png")
            self.send_header("Content-Length", str(len(_png)))
            self.send_header("Cache-Control", "public, max-age=86400")
            self.end_headers()
            if body:
                self.wfile.write(_png)
            return True
        if _path in ("/livecontainer-icon.png", "/sidestore-icon.png", "/altstore-icon.png", "/flekdeck-icon.png"):
            _ip = os.path.join(BASE_DIR, os.path.basename(_path))
            if not os.path.isfile(_ip):
                self.send_error(404)
                return True
            with open(_ip, "rb") as _f:
                _png = _f.read()
            self.send_response(200)
            self.send_header("Content-Type", "image/png")
            self.send_header("Content-Length", str(len(_png)))
            self.send_header("Cache-Control", "public, max-age=86400")
            self.end_headers()
            if body:
                self.wfile.write(_png)
            return True
        if _path.startswith("/appicon/"):
            # Real My Apps icons (2026-11-16, minis-appicons). The
            # page asks for /appicon/<bundle>.png?t=<launch token>:
            # the token is checked exactly like /jit, so the tunnel
            # URL alone cannot be used to pull someone's app list.
            # Order: cached icon -> extract from the kept IPA ->
            # redirect to the catalog's iconURL -> 404 (the page
            # then keeps its placeholder).
            try:
                _q = urllib.parse.parse_qs(
                    urllib.parse.urlsplit(self.path).query)
            except Exception:
                _q = {}
            _tok = (_q.get("t") or [""])[0]
            _uid, _why = _miniapp_api_auth({"token": _tok}, self)
            _name = urllib.parse.unquote(_path[len("/appicon/"):])
            if _uid is None:
                self.send_error(403, "forbidden")
                return True
            if not _name.lower().endswith(".png"):
                self.send_error(404, "not found")
                return True
            _bundle = _name[:-4]
            if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,199}", _bundle or ""):
                self.send_error(404, "not found")
                return True
            _png_path = _appicon_png_path(_bundle)
            if not _png_path:
                _remote = _appicon_remote_url(_bundle)
                if _remote:
                    self.send_response(302)
                    self.send_header("Location", _remote)
                    self.send_header("Cache-Control", "public, max-age=3600")
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return True
                self.send_error(404, "no icon")
                return True
            try:
                with open(_png_path, "rb") as _f:
                    _png = _f.read()
            except Exception:
                self.send_error(404, "no icon")
                return True
            self.send_response(200)
            self.send_header("Content-Type", "image/png")
            self.send_header("Content-Length", str(len(_png)))
            self.send_header("Cache-Control", "public, max-age=86400")
            self.end_headers()
            if body:
                self.wfile.write(_png)
            return True
        if _path not in ("/miniapp.html", "/sidebot.html", "/appstore.html"):
            return False
        # appstore.html is the App Store UI of the same bot: served
        # from the bot folder, same token-in-URL launch, same
        # localhost-only server behind the tunnel.
        _file = os.path.join(BASE_DIR, os.path.basename(_path))
        if not os.path.exists(_file) and _path == "/sidebot.html":
            _file = os.path.join(BASE_DIR, "miniapp.html")
        try:
            with open(_file, "rb") as f:
                _data = f.read()
        except Exception:
            self.send_error(404, "%s not found" % os.path.basename(_path))
            return True
        _host = (self.headers.get("Host") or "").lower()
        _is_direct_local = (
            self.client_address[0] in ("127.0.0.1", "::1")
            and (_host.startswith("127.0.0.1:") or _host.startswith("localhost:"))
            and not self.headers.get("X-Forwarded-For")
            and not self.headers.get("Cf-Connecting-Ip")
            and not self.headers.get("X-Real-Ip")
        )
        if _is_direct_local:
            _tok = _miniapp_launch_token_issue()
            _inj = ('<script>window.__LOCAL_TOKEN__="%s";</script></head>' % _tok).encode("utf-8")
            _data = _data.replace(b"</head>", _inj, 1)
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Cache-Control", "no-store, no-cache, must-revalidate")
        self.send_header("Content-Length", str(len(_data)))
        self.end_headers()
        if body:
            self.wfile.write(_data)
        return True

    def log_message(self, *args):
        # Diagnostics for failed OTA installs: what installd
        # actually requested (path, Range, status) is otherwise
        # invisible. Paths only, no tokens or file contents.
        # The log is capped so it cannot grow without bound.
        try:
            _log = os.path.join(BASE_DIR, "ota-access-log.txt")
            if os.path.exists(_log) and os.path.getsize(_log) > 524288:
                os.remove(_log)
            _line = "%s %s range=%s ua=%s\n" % (
                datetime.now(timezone.utc).isoformat(),
                (args[0] % args[1:]) if args else "",
                self.headers.get("Range", "-"),
                (self.headers.get("User-Agent", "-") or "-")[:80])
            # Never log a Mini App launch token: the page URL
            # carries ?t=<exp>.<hmac>, and the request line is
            # logged verbatim. Redact it (bearer, valid 24h).
            _line = re.sub(r"([?&]t=)[0-9a-f]+\.[0-9a-f]+",
                           r"\1<redacted>", _line)
            # The SAP proxy carries the same launch token in its path.
            _line = re.sub(r"(/appstore-api/sap-proxy/)[^ ?]+",
                           r"\1<redacted>", _line)
            with open(_log, "a", encoding="utf-8") as _f:
                _f.write(_line)
        except Exception:
            pass


def _ota_local_ok():
    """True when the local OTA server answers on 127.0.0.1."""
    try:
        _req = urllib.request.Request(
            "http://127.0.0.1:%d/" % OTA_PORT, method="HEAD")
        with urllib.request.urlopen(_req, timeout=3) as _resp:
            return _resp.status < 500
    except urllib.error.HTTPError as _e:
        return _e.code < 500
    except Exception:
        return False


def _tailscale_exe():
    found = shutil.which("tailscale")
    if found:
        return found
    for _cand in ("/usr/bin/tailscale", "/usr/local/bin/tailscale",
                  "/snap/bin/tailscale",
                  "/opt/tailscale/tailscale"):
        if os.path.exists(_cand):
            return _cand
    return ""


def _ensure_ota_server():
    # A started flag alone is not proof: the server thread may
    # have died, or this process restarted while ota/ files from
    # an earlier publish still exist. Probe locally; restart
    # the server when it does not answer, so old Serve links
    # keep working after a bot restart.
    if _OTA_SERVER["started"] and _OTA_SERVER["httpd"] is not None:
        if _ota_local_ok():
            return True, ""
        _OTA_SERVER["started"] = False
        _OTA_SERVER["httpd"] = None
    try:
        os.makedirs(OTA_DIR, exist_ok=True)
        class _ReusableHTTPServer(http.server.ThreadingHTTPServer):
            allow_reuse_address = True
            daemon_threads = True
            block_on_close = False
            request_queue_size = 32
        httpd = _ReusableHTTPServer(("127.0.0.1", OTA_PORT), _OtaHandler)
        threading.Thread(target=httpd.serve_forever, daemon=True).start()
        _OTA_SERVER["httpd"] = httpd
        _OTA_SERVER["started"] = True
        return True, ""
    except Exception as e:
        if _ota_local_ok():
            _OTA_SERVER["started"] = True
            return True, ""
        return False, str(e)


def _ensure_tailscale_serve():
    """Idempotent `tailscale serve --bg <port>` + status check.
    Returns (True, '') or (False, safe_reason). Never runs funnel."""
    global _TAILSCALE_SERVE_OK
    exe = _tailscale_exe()
    if not exe:
        return False, tr("tailscale_no_cli")
    if _TAILSCALE_SERVE_OK:
        return True, ""
    try:
        proc = subprocess.run([exe, "serve", "--bg", "--yes", str(OTA_PORT)],
                              capture_output=True, text=True, timeout=30)
    except Exception as e:
        return False, str(e)
    if proc.returncode != 0:
        _out = ((proc.stdout or "") + (proc.stderr or "")).strip()
        return False, _out[-300:] if _out else "tailscale serve failed"
    try:
        st = subprocess.run([exe, "serve", "status"], capture_output=True,
                            text=True, timeout=15)
        _out = (st.stdout or "") + (st.stderr or "")
    except Exception as e:
        return False, str(e)
    _host = urllib.parse.urlparse(effective_tailscale_url()).netloc
    if _host and _host in _out and ("127.0.0.1:%d" % OTA_PORT) in _out:
        _TAILSCALE_SERVE_OK = True
        return True, ""
    return False, tr("tailscale_not_serving")


# ---------------- MINI APP (SideBot) VIA TUNNEL — Phase 9, 2026-11-14 ----------------
# The Windows bot serves SideBot from its OTA server behind
# Tailscale Serve. In Minis Tailscale Serve is BLOCKED: LocalDevVPN
# holds the single iOS VPN slot, so Tailscale is off while the bot
# runs. The Mini App therefore rides on a TUNNEL instead: the bot
# serves miniapp.html + the in-app API on the local OTA server
# (127.0.0.1:8743) and a tunnel client exposes it as a public
# HTTPS URL, which is what Telegram requires for a Web App.
#
# Tunnel clients (both are plain userspace outbound-HTTPS
# processes — no TUN, no root, no VPN slot):
#   * cloudflared (preferred): `cloudflared tunnel --url ...`
#     needs NO account (free quick tunnel, random
#     *.trycloudflare.com URL, changes every restart); with
#     CLOUDFLARED_TUNNEL_TOKEN + MINIAPP_TUNNEL_HOSTNAME in .env
#     it runs a NAMED tunnel with a fixed hostname instead.
#   * ngrok (fallback): needs NGROK_AUTHTOKEN in .env (free
#     account); the public URL comes from its local API.
# The bot starts the tunnel ON DEMAND (tap 📱 SideBot in the
# menu) and stops it on shutdown. The Mini App works only while
# Minis is alive — same as the bot itself (music playing in the
# Minis built-in browser keeps it answering while locked).
# Auth is the Windows launch-token scheme verbatim: a bot-issued
# 24h HMAC token in the Mini App URL (?t=), initData fallback.
# The secret lives in miniapp_secret.json (chmod 600), never in
# chat or logs; the access log redacts ?t= tokens.
# What is DELIBERATELY not ported from Windows:
#   * Cellular Refresh shortcut dance (delays/names/TurnOffData):
#     the bot's push travels PC -> phone over WireGuard there; in
#     Minis the transfer is on-device loopback 10.7.0.1, so data
#     toggles are meaningless. Since 2026-11-14 (minis-sidestore1)
#     the switch itself EXISTS again as a persisted Minis setting
#     ("Cellular Refresh & Install"): refresh/install never
#     require Wi-Fi, and OFF only blocks a job the bot can tell is
#     on mobile data. The delay/name rows are gone for good.
#   * Install backends other than rust: Minis installs only via
#     the Rust install-helper to 10.7.0.1. set_backend accepts
#     "rust" and honestly refuses the rest.
#   * In-app profile adding (provision_start): the Apple login +
#     2FA runs in chat in Minis; the API answers with a chat
#     pointer instead of taking a password in-app.
#   * JIT: there is no JIT engine to drive from here; the ⚡ JIT
#     button hands the bundle ID to StikDebug through the bot's
#     /jit page (the same hand-off SideStore uses), which is why
#     the job bar only claims the hand-off, never "JIT on".
#   * /appicon/: no icon extractor in Minis; the page falls back
#     to the sparkle icon.
#   * Refresh-attempts journal: Minis keeps no such store; the
#     refresh workers resolve jobs from the installed record's
#     expiry + the last-signed file instead.

_MINIAPP_LAUNCH_TTL = 86400  # launch tokens live 24h
_MINIAPP_JOBS = {}
_MINIAPP_JOBS_LOCK = threading.Lock()
_MINIAPP_DATA_SEEN = {"n": 0, "last": "", "at": ""}
_MINIAPP_API_LAST = {"n": 0, "at": "", "path": "", "code": 0, "reason": ""}
# Steps during which a Mini App job is "busy" (same set the chat
# guards use, plus the siboot flow which also runs in Minis).
_MINIAPP_BUSY_STEPS = ("prov_running", "prov_2fa_waiting", "prov_2fa_choice",
                       "pair_running", "repair_running",
                       "siboot_running", "siboot_2fa_waiting")
_MINIAPP_UC_KEYS = {"keys": None}


def _miniapp_uc_keys():
    """UC bool-toggle keys, computed lazily: UC_DEFAULTS is
    defined further down the file, so a module-level tuple
    would raise NameError at import."""
    if _MINIAPP_UC_KEYS["keys"] is None:
        _MINIAPP_UC_KEYS["keys"] = tuple(
            k for k, v in UC_DEFAULTS.items() if isinstance(v, bool))
    return _MINIAPP_UC_KEYS["keys"]
# Minis installs only via the Rust install-helper.
MINIAPP_INSTALL_METHODS = ("rust",)


# --- Tunnel ---------------------------------------------------------------

_MINIS_TUNNEL = {"proc": None, "kind": "", "url": "", "log": "",
                 "started_at": ""}


def _tunnel_exe(kind):
    """Path of the tunnel binary (executable file), or "". Env
    override first (CLOUDFLARED_EXE / NGROK_EXE), then the file
    next to bot.py, then PATH. Never raises."""
    try:
        _name = "cloudflared" if kind == "cloudflared" else "ngrok"
        _env_key = "CLOUDFLARED_EXE" if kind == "cloudflared" else "NGROK_EXE"
        _cands = []
        _env = (ENV.get(_env_key, "") or "").strip()
        if _env:
            _cands.append(_env)
        _cands.append(os.path.join(BASE_DIR, _name))
        _found = shutil.which(_name)
        if _found:
            _cands.append(_found)
        for _c in _cands:
            if _c and os.path.isfile(_c) and os.access(_c, os.X_OK):
                return _c
    except Exception:
        pass
    return ""


def _tunnel_available():
    """True when at least one tunnel binary (ssh for localhost.run,
    cloudflared, or ngrok) can run."""
    return bool(shutil.which("ssh") or _tunnel_exe("cloudflared") or _tunnel_exe("ngrok"))


def _tunnel_url_cached():
    """Public tunnel URL when the tunnel process is alive, else
    "". Never starts anything — rendering the menu must stay fast."""
    try:
        _p = _MINIS_TUNNEL.get("proc")
        if _p is not None and _p.poll() is None and _MINIS_TUNNEL.get("url"):
            return _MINIS_TUNNEL["url"]
    except Exception:
        pass
    return ""


def _tunnel_stop():
    """Stop the tunnel (shutdown path). Never raises."""
    _p = _MINIS_TUNNEL.get("proc")
    _MINIS_TUNNEL["proc"] = None
    _MINIS_TUNNEL["url"] = ""
    _MINIS_TUNNEL["kind"] = ""
    if _p is None:
        return
    try:
        _p.terminate()
        try:
            _p.wait(timeout=5)
        except Exception:
            try:
                _p.kill()
            except Exception:
                pass
    except Exception:
        pass


def _tunnel_kill_proc(_p):
    """Stop one tunnel process for good (terminate, then kill).
    Used on every failure branch of the tunnel starters (BUG FIX
    2026-11-14): they used to just drop the handle, so a cloudflared /
    ngrok that never printed a URL kept running — holding a PUBLIC
    https tunnel to the bot's local API — and _tunnel_stop() later
    could not find it any more. Never raises."""
    if _p is None:
        return
    try:
        _p.terminate()
        try:
            _p.wait(timeout=5)
        except Exception:
            try:
                _p.kill()
                _p.wait(timeout=3)
            except Exception:
                pass
    except Exception:
        try:
            _p.kill()
        except Exception:
            pass


def _tunnel_start_cloudflared():
    """Start cloudflared. Named tunnel when CLOUDFLARED_TUNNEL_TOKEN
    + MINIAPP_TUNNEL_HOSTNAME are both in .env, else a free quick
    tunnel (no account). Returns (True, "") or (False, reason).
    The token travels via the TUNNEL_TOKEN env var, never argv
    (argv is visible in ps) and never the log."""
    _exe = _tunnel_exe("cloudflared")
    if not _exe:
        return False, "no cloudflared binary"
    _token = (ENV.get("CLOUDFLARED_TUNNEL_TOKEN", "") or "").strip()
    _host = (ENV.get("MINIAPP_TUNNEL_HOSTNAME", "") or "").strip()
    _log_path = os.path.join(BASE_DIR, "tunnel-cloudflared.log")
    try:
        _logf = open(_log_path, "w", encoding="utf-8")
    except Exception as e:
        return False, "cannot open tunnel log: %s" % str(e)[:80]
    try:
        if _token and _host:
            _env = dict(os.environ)
            _env["TUNNEL_TOKEN"] = _token
            _proc = subprocess.Popen(
                [_exe, "tunnel", "--no-autoupdate", "--protocol", "http2", "run"],
                stdout=_logf, stderr=subprocess.STDOUT, env=_env)
            _MINIS_TUNNEL.update({
                "proc": _proc, "kind": "cloudflared-named",
                "log": _log_path,
                "started_at": datetime.now(timezone.utc).isoformat()})
            # Named tunnel: the URL is the configured hostname.
            # Give the process a moment to prove it stays up.
            for _ in range(10):
                if _proc.poll() is not None:
                    _tunnel_kill_proc(_proc)
                    _MINIS_TUNNEL["proc"] = None
                    return False, "cloudflared exited at once (bad token?)"
                time.sleep(1)
            _MINIS_TUNNEL["url"] = "https://" + _host
            return True, ""
        _proc = subprocess.Popen(
            [_exe, "tunnel", "--no-autoupdate", "--protocol", "http2", "--url",
             "http://127.0.0.1:%d" % OTA_PORT],
            stdout=_logf, stderr=subprocess.STDOUT)
        _MINIS_TUNNEL.update({
            "proc": _proc, "kind": "cloudflared-quick",
            "log": _log_path,
            "started_at": datetime.now(timezone.utc).isoformat()})
        _deadline = time.time() + 18
        while time.time() < _deadline:
            if _proc.poll() is not None:
                _tunnel_kill_proc(_proc)
                _MINIS_TUNNEL["proc"] = None
                return False, "cloudflared exited early"
            try:
                with open(_log_path, encoding="utf-8", errors="ignore") as _f:
                    _txt = _f.read()
            except Exception:
                _txt = ""
            _m = re.search(r"https://[A-Za-z0-9-]+\.trycloudflare\.com", _txt)
            if _m:
                _MINIS_TUNNEL["url"] = _m.group(0)
                return True, ""
            time.sleep(1)
        _tunnel_kill_proc(_proc)
        _MINIS_TUNNEL["proc"] = None
        return False, "no tunnel URL in the cloudflared log"
    except Exception as e:
        _tunnel_kill_proc(locals().get("_proc"))
        _MINIS_TUNNEL["proc"] = None
        return False, str(e)[:120]
    finally:
        try:
            _logf.close()
        except Exception:
            pass


def _tunnel_start_ngrok():
    """Start ngrok (fallback). Needs NGROK_AUTHTOKEN in .env
    (free account). The public URL comes from ngrok's local API
    http://127.0.0.1:4040/api/tunnels. Returns (True, "") or
    (False, reason)."""
    _exe = _tunnel_exe("ngrok")
    if not _exe:
        return False, "no ngrok binary"
    _token = (ENV.get("NGROK_AUTHTOKEN", "") or "").strip()
    if not _token:
        return False, "no NGROK_AUTHTOKEN in .env"
    _log_path = os.path.join(BASE_DIR, "tunnel-ngrok.log")
    try:
        _logf = open(_log_path, "w", encoding="utf-8")
    except Exception as e:
        return False, "cannot open tunnel log: %s" % str(e)[:80]
    try:
        _env = dict(os.environ)
        _env["NGROK_AUTHTOKEN"] = _token
        _proc = subprocess.Popen(
            [_exe, "http", "http://127.0.0.1:%d" % OTA_PORT,
             "--log=stdout"],
            stdout=_logf, stderr=subprocess.STDOUT, env=_env)
        _MINIS_TUNNEL.update({
            "proc": _proc, "kind": "ngrok",
            "log": _log_path,
            "started_at": datetime.now(timezone.utc).isoformat()})
        _deadline = time.time() + 30
        while time.time() < _deadline:
            if _proc.poll() is not None:
                _tunnel_kill_proc(_proc)
                _MINIS_TUNNEL["proc"] = None
                return False, "ngrok exited early (bad authtoken?)"
            try:
                _req = urllib.request.Request(
                    "http://127.0.0.1:4040/api/tunnels", method="GET")
                with urllib.request.urlopen(_req, timeout=3) as _resp:
                    _d = json.loads(_resp.read().decode("utf-8"))
                for _t in _d.get("tunnels") or []:
                    _u = (_t or {}).get("public_url") or ""
                    if _u.startswith("https://"):
                        _MINIS_TUNNEL["url"] = _u
                        return True, ""
            except Exception:
                pass
            time.sleep(1)
        _tunnel_kill_proc(_proc)
        _MINIS_TUNNEL["proc"] = None
        return False, "no tunnel URL from the ngrok local API"
    except Exception as e:
        _tunnel_kill_proc(locals().get("_proc"))
        _MINIS_TUNNEL["proc"] = None
        return False, str(e)[:120]
    finally:
        try:
            _logf.close()
        except Exception:
            pass


def _tunnel_start_localhostrun():
    """Fallback free HTTPS tunnel via ssh to nokey@localhost.run (no account/token)."""
    _ssh = shutil.which("ssh")
    if not _ssh:
        return False, "no ssh binary"
    _log_path = os.path.join(BASE_DIR, "tunnel-localhostrun.log")
    try:
        _logf = open(_log_path, "w", encoding="utf-8")
    except Exception as e:
        return False, "cannot open tunnel log: %s" % str(e)[:80]
    try:
        _proc = subprocess.Popen(
            [_ssh, "-T", "-o", "StrictHostKeyChecking=no",
             "-o", "UserKnownHostsFile=/dev/null",
             "-o", "ServerAliveInterval=15",
             "-o", "ServerAliveCountMax=2",
             "-o", "ExitOnForwardFailure=yes",
             "-R", "80:127.0.0.1:%d" % OTA_PORT,
             "nokey@localhost.run"],
            stdin=subprocess.DEVNULL, stdout=_logf, stderr=subprocess.STDOUT)
        _MINIS_TUNNEL.update({
            "proc": _proc, "kind": "localhostrun",
            "log": _log_path,
            "started_at": datetime.now(timezone.utc).isoformat()})
        _deadline = time.time() + 20
        while time.time() < _deadline:
            if _proc.poll() is not None:
                _tunnel_kill_proc(_proc)
                _MINIS_TUNNEL["proc"] = None
                return False, "localhost.run ssh exited early"
            try:
                with open(_log_path, encoding="utf-8", errors="ignore") as _f:
                    _txt = _f.read()
            except Exception:
                _txt = ""
            _m = re.search(r"https://[A-Za-z0-9.-]+\.lhr\.life", _txt)
            if _m:
                _MINIS_TUNNEL["url"] = _m.group(0)
                return True, ""
            time.sleep(1)
        _tunnel_kill_proc(_proc)
        _MINIS_TUNNEL["proc"] = None
        return False, "no tunnel URL from localhost.run"
    except Exception as e:
        _tunnel_kill_proc(locals().get("_proc"))
        _MINIS_TUNNEL["proc"] = None
        return False, str(e)[:120]
    finally:
        try:
            _logf.close()
        except Exception:
            pass


def _tunnel_start():
    """(ok, error): prefer ssh localhost.run (fast, no rate limits),
    with cloudflared and ngrok as fallbacks. Never raises."""
    try:
        if _tunnel_url_cached():
            return True, ""
        _tunnel_stop()
        _ok, _lhr_err = _tunnel_start_localhostrun()
        if _ok:
            return True, ""
        _ok, _cf_err = _tunnel_start_cloudflared()
        if _ok:
            return True, ""
        if _tunnel_exe("ngrok"):
            _ok, _ng_err = _tunnel_start_ngrok()
            if _ok:
                return True, ""
            return False, "localhost.run: %s; cloudflared: %s; ngrok: %s" % (_lhr_err, _cf_err, _ng_err)
        return False, "localhost.run: %s; cloudflared: %s" % (_lhr_err, _cf_err)
    except Exception as e:
        return False, str(e)[:120]


def _tunnel_watchdog_loop():
    """Keep the Minis HTTPS tunnel alive; restart if ssh died or returns 'no tunnel'."""
    while True:
        time.sleep(25)
        try:
            if not MINIS_MODE or not _tunnel_available():
                continue
            _u = _tunnel_url_cached()
            if not _u:
                _tunnel_start()
                continue
            if _MINIS_TUNNEL.get("kind") == "localhostrun":
                try:
                    _req = urllib.request.Request(_u + "/miniapp.html", method="HEAD")
                    with urllib.request.urlopen(_req, timeout=5) as _resp:
                        if _resp.status >= 500:
                            raise RuntimeError("tunnel 5xx")
                except urllib.error.HTTPError as _he:
                    if _he.code in (404, 502, 503, 504):
                        _tunnel_stop()
                        _tunnel_start()
                except Exception:
                    _tunnel_stop()
                    _tunnel_start()
        except Exception:
            pass


def _tunnel_status_text():
    """One /status line for the Mini App tunnel. Host only, no
    token, no full URL with the launch token (the URL in the
    menu carries ?t=, and /status is owner-only anyway)."""
    _url = _tunnel_url_cached()
    if _url:
        _host = urllib.parse.urlparse(_url).netloc
        return "%s (%s)" % (_host, _MINIS_TUNNEL.get("kind") or "tunnel")
    if _MINIS_TUNNEL.get("proc") is not None:
        return "starting…"
    if not _tunnel_available():
        return "off (no cloudflared/ngrok binary)"
    return "off (tap %s to start)" % tr("miniapp")


def _miniapp_tunnel_start_thread(chat_id):
    """Start the tunnel off the polling loop, then re-show the
    main menu — the re-rendered menu carries the web_app button
    with the fresh tunnel URL. Runs in a thread."""
    _ok, _err = _tunnel_start()
    if not _ok:
        try:
            send_message(chat_id, tr("miniapp_tunnel_failed") % _err)
        except Exception:
            pass
        return
    try:
        show_main_menu(chat_id, "reply", None)
        _u = _miniapp_url()
        _local_url = "http://127.0.0.1:%d/miniapp.html" % OTA_PORT
        if _u:
            show_main_menu(chat_id, "reply", None)
            _res = api("sendMessage", chat_id=chat_id,
                       text="📱 SideBot готовий:\n• У Telegram — кнопка нижче\n• Локально в Safari (миттєво + для «На початковий екран»): %s" % _local_url,
                       reply_markup=json.dumps({"inline_keyboard": [[
                           {"text": "📱 Відкрити SideBot", "web_app": {"url": _u}}
                       ]]}, ensure_ascii=False))
            _dbg("miniapp inline res=%s" % str(_res)[:200])
        else:
            send_message(chat_id, "⚠️ _miniapp_url() повернув порожньо (тунель=%r)" % _tunnel_url_cached())
    except Exception as _e:
        _dbg("miniapp_thread err: %s" % _e)
        try:
            send_message(chat_id, "⚠️ miniapp error: %s" % str(_e)[:200])
        except Exception:
            pass


# --- Mini App state / URL (Minis) -------------------------------------------

# SideStore parity settings (2026-11-14, minis-sidestore1): the one
# 0600 JSON file the Mini App persists its own switches in —
# Cellular Refresh & Install, Auto-Refresh, ask-sign-options and the
# last sign-options values. Kept apart from user_customizations.json
# (SideStore GENERAL/APP VERIFICATION, shared with the chat UI) so a
# reset of one never silently changes the other. No secrets here:
# no passwords, no cert contents, no Apple IDs.
MINIAPP_SETTINGS_FILE = os.path.join(BASE_DIR, "miniapp_settings.json")
MINIAPP_APP_ID_LIMIT = 10          # free-account App IDs per 7 days
MINIAPP_APP_ID_WINDOW_DAYS = 7
MINIAPP_APP_INSTALL_LIMIT = 3      # free-account apps at once
MINIAPP_AUTO_DAYS_MAX = 6          # a 7-day profile must be renewed before it dies
MINIAPP_SIGNOPT_TEXT_KEYS = ("display_name", "custom_bundle_id", "version",
                             "min_ios")
MINIAPP_SIGNOPT_BOOL_KEYS = ("rm_extensions", "enable_files", "rm_watch",
                             "rm_uisd", "inject_extensions", "weak_dylib")

MINIAPP_SETTINGS_DEFAULTS = {
    "backend": "rust",
    "cell": True,
    "auto_refresh": True,
    "auto_refresh_days": 5,
    "auto_check_hours": 1,
    "ask_signopts": False,
    "sign_opts": {},
    "last_check": "",
    "last_auto": {},
    "jit_last": "",
    # SideBot UI language (2026-11-16): empty means "follow the bot's
    # chat language", so the two never disagree on first launch.
    "language": "",
}


def _ms_load():
    """Saved Mini App settings. Missing file, corrupt JSON or a
    value of the wrong type falls back to the default silently —
    the page can never be locked out by its own settings. Never
    raises."""
    out = json.loads(json.dumps(MINIAPP_SETTINGS_DEFAULTS))
    try:
        with open(MINIAPP_SETTINGS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return out
    if not isinstance(data, dict):
        return out
    _b = data.get("backend")
    if isinstance(_b, str) and _b in ("rust", "siboot"):
        out["backend"] = _b
    for _k in ("cell", "auto_refresh", "ask_signopts"):
        if isinstance(data.get(_k), bool):
            out[_k] = data[_k]
    for _k, _lo, _hi in (("auto_refresh_days", 1, MINIAPP_AUTO_DAYS_MAX),
                         ("auto_check_hours", 1, 24)):
        try:
            _v = int(data.get(_k))
        except Exception:
            continue
        if _lo <= _v <= _hi:
            out[_k] = _v
    if isinstance(data.get("sign_opts"), dict):
        out["sign_opts"] = _miniapp_signopts_clean(data["sign_opts"])
    if isinstance(data.get("last_check"), str):
        out["last_check"] = data["last_check"][:40]
    if isinstance(data.get("last_auto"), dict):
        out["last_auto"] = {str(k)[:120]: str(v)[:40]
                            for k, v in list(data["last_auto"].items())[:50]}
    if isinstance(data.get("jit_last"), str):
        out["jit_last"] = data["jit_last"][:40]
    if isinstance(data.get("language"), str) and data["language"] in LANGS:
        out["language"] = data["language"]
    return out


def _ms_save(data):
    """Persist Mini App settings. Atomic tmp+replace, 0600, same
    pattern as _uc_save. Returns True/False, never raises."""
    try:
        _tmp = MINIAPP_SETTINGS_FILE + ".tmp"
        with open(_tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        os.replace(_tmp, MINIAPP_SETTINGS_FILE)
        try:
            os.chmod(MINIAPP_SETTINGS_FILE, 0o600)
        except Exception:
            pass
        return True
    except Exception:
        return False


def _ms_get(key):
    return _ms_load().get(key, MINIAPP_SETTINGS_DEFAULTS.get(key))


def _ms_set(key, value):
    """Set one key and save. Returns True on success."""
    d = _ms_load()
    d[key] = value
    return _ms_save(d)


def _miniapp_signopts_clean(raw):
    """Only the sign-option keys the Mini App may set, with type
    and length limits. Unknown keys are dropped, so a page bug can
    never reach zsign with an unexpected flag."""
    out = {}
    if not isinstance(raw, dict):
        return out
    for _k in MINIAPP_SIGNOPT_TEXT_KEYS:
        _v = raw.get(_k)
        if isinstance(_v, str):
            _v = _v.strip()[:120]
            if _v:
                out[_k] = _v
    for _k in MINIAPP_SIGNOPT_BOOL_KEYS:
        if isinstance(raw.get(_k), bool):
            out[_k] = raw[_k]
    if out.get("custom_bundle_id") and not re.fullmatch(
            r"[A-Za-z0-9][A-Za-z0-9.-]{1,150}", out["custom_bundle_id"]):
        out.pop("custom_bundle_id", None)
    if out.get("version") and not re.fullmatch(r"[0-9][0-9.]{0,19}", out["version"]):
        out.pop("version", None)
    if out.get("min_ios") and not re.fullmatch(r"[0-9]{1,2}(\.[0-9]{1,2}){0,2}",
                                                out["min_ios"]):
        out.pop("min_ios", None)
    if isinstance(raw.get("dylibs"), list):
        _droot = os.path.realpath(MINIAPP_DYLIBS_DIR)
        _clean_d = []
        for _dp in raw["dylibs"]:
            if not isinstance(_dp, str) or not _dp.strip():
                continue
            try:
                _rp = os.path.realpath(_dp.strip())
                if (_rp.startswith(_droot + os.sep) or os.path.isfile(_rp)) and _rp.lower().endswith(".dylib") and os.path.isfile(_rp):
                    if _rp not in _clean_d:
                        _clean_d.append(_rp)
            except Exception:
                pass
        out["dylibs"] = _clean_d[:20]
    return out


def _miniapp_dylibs_info(so=None):
    so = so if so is not None else (_ms_load().get("sign_opts") or {})
    out = []
    for _p in (so.get("dylibs") or []):
        if isinstance(_p, str) and os.path.isfile(_p):
            out.append({"path": _p, "name": os.path.basename(_p)})
    return out


def _miniapp_signopts_merge(cmd_opts):
    """Put the Mini App's sign options into the global job WITHOUT
    dropping values another flow already set (rm_extensions from
    the extensions prompt, an icon path, dylibs). Returns the
    clean option dict."""
    _so = _miniapp_signopts_clean(cmd_opts)
    if not _so:
        return {}
    if "dylibs" not in _so:
        _saved_dy = (_ms_load().get("sign_opts") or {}).get("dylibs")
        if isinstance(_saved_dy, list):
            _valid_dy = [p for p in _saved_dy if isinstance(p, str) and os.path.isfile(p)]
            if _valid_dy:
                _so["dylibs"] = _valid_dy
    _opts = dict(job.get("sign_opts") or {})
    _opts.update(_so)
    job["sign_opts"] = _opts
    job["sign_opts_from_mini"] = True
    # Kept apart as well: _prefill_sign_opts derives some flags from
    # the IPA itself (Enable Files follows the bundle) and would
    # overwrite the user's explicit choice; the import flow re-applies
    # exactly these keys after the prefill.
    _per_app_keys = ("custom_bundle_id", "display_name", "version", "min_ios")
    job["sign_opts_mini"] = dict(_so)
    d = _ms_load()
    # Per-app fields (Bundle ID, display name, version, min iOS) are NOT
    # kept as defaults: otherwise the next app would be renamed/re-ID'd
    # to the previous app (e.g. LiveContainer) without the user noticing.
    d["sign_opts"] = {k: v for k, v in _so.items() if k not in _per_app_keys}
    _ms_save(d)
    return _so


def _miniapp_signopts_text(so=None):
    """One-line summary of the sign options that will be applied."""
    so = so if so is not None else (_ms_load().get("sign_opts") or {})
    _parts = []
    if so.get("display_name"):
        _parts.append("%s" % so["display_name"])
    if so.get("custom_bundle_id"):
        _parts.append("ID %s" % so["custom_bundle_id"])
    if so.get("version"):
        _parts.append("v%s" % so["version"])
    if so.get("min_ios"):
        _parts.append("iOS %s+" % so["min_ios"])
    if so.get("rm_extensions"):
        _parts.append(tr("miniapp_so_rm_ext"))
    if so.get("enable_files"):
        _parts.append(tr("miniapp_so_files"))
    if so.get("rm_watch"):
        _parts.append(tr("miniapp_so_rm_watch"))
    if so.get("rm_uisd"):
        _parts.append(tr("miniapp_so_rm_uisd"))
    if so.get("inject_extensions"):
        _parts.append(tr("miniapp_so_inject_ext"))
    if so.get("weak_dylib"):
        _parts.append(tr("miniapp_so_weak"))
    if so.get("dylibs"):
        _parts.append("%d dylib" % len([p for p in so["dylibs"] if os.path.isfile(p)]))
    if not _parts:
        return tr("miniapp_so_none")
    return ", ".join(_parts)


