def profile_new_bundle_id(profile_path):
    """Bundle ID iloader actually installs, from the provisioning profile.

    iloader/isideload sign_app rewrites the app's CFBundleIdentifier to
    "{original_bundle}.{team_id}" (update_bundle_id in isideload's
    sideloader.rs / application.rs) BEFORE signing, so the installed
    app's bundle ID exactly equals the profile's App ID. Our bot did
    NOT do this: it created App ID "{bundle}.{team}", then zsigned
    the IPA with its original bundle ID, so iOS saw
    profile App ID != app bundle ID and refused with
    "cannot verify authenticity", while our own verify passed only
    because it allowed a startswith match. Returns the team-suffixed
    bundle ID, or None if the profile cannot be parsed (caller then
    signs without -b, old behaviour).
    """
    try:
        blob = open(profile_path, "rb").read()
        start = blob.find(b"<?xml")
        end = blob.find(b"</plist>")
        if start < 0 or end < 0:
            return None
        prov = plistlib.loads(blob[start:end + len(b"</plist>")])
        ent = prov.get("Entitlements") or {}
        app_id = ent.get("application-identifier") or ""
        if "." not in app_id:
            return None
        return app_id.split(".", 1)[1]
    except Exception:
        return None


# ---- Feather-style signing options (2026-11-08, win-feather / linux-feather) ----
# Feather (claration/feather) is an on-device iOS signer; it cannot run
# on a PC/Linux host. Its options are just zsign flags, and this bot
# already uses zsign, so the options are exposed here as zsign flags.
# zsign v1.1.3 (the shipped version) supports all of them
# (-b -n -r -I -M -S -E -W -U -l -D -w -P); older zsign builds may not,
# so the supported flags are probed from `zsign --help` at runtime and
# any requested option whose flag is missing refuses the sign up front.
# Injection only adds LC_LOAD_DYLIB: whether a tweak works depends on
# the tweak itself (Ellekit/Substrate); the bot cannot guarantee it.
# A custom bundle ID needs a matching profile (see provision_thread).

_SIGNOPTS_FLAG_FOR = {
    "display_name": "n", "version": "r", "icon_path": "I",
    "min_ios": "M", "enable_files": "S", "rm_extensions": "E",
    "rm_watch": "W", "rm_uisd": "U", "dylibs": "l",
    "weak_dylib": "w", "inject_extensions": "P",
    "entitlements_path": "e",
}

_ZSIGN_FLAGS_CACHE = None


def _sign_opts_default():
    return {"custom_bundle_id": "", "display_name": "", "version": "",
            "min_ios": "", "icon_path": "", "dylibs": [],
            "frameworks": [], "bundles": [],
            "weak_dylib": False, "inject_extensions": False,
            "enable_files": False, "rm_extensions": False,
            "rm_watch": False, "rm_uisd": False, "return_mode": False,
            "appearance": "", "itunes_files": False, "promotion": False,
            "game_mode": False, "ipad_fullscreen": False,
            "rm_url_scheme": False, "force_localize": False,
            "liquid_glass": "",
            # Feather rebuild 2: entitlements, modify-only, PPQ,
            # inject path/folder, disinject, remove files
            "merge_entitlements": False,
            "entitlements_path": "",
            "entitlements_name": "",
            "modify_only": False,
            "ppq": False,
            "ppq_string": "",
            "inject_path": "@executable_path",
            "inject_folder": "/Frameworks/",
            "disinject": [],
            "rm_files": []}


def _sign_opts_dir():
    d = job.get("sign_opts_dir") or ""
    if not d:
        d = tempfile.mkdtemp(prefix="tiloader-signopts-")
        job["sign_opts_dir"] = d
    return d


def _signopts_cleanup():
    d = job.get("sign_opts_dir") or ""
    job["sign_opts_dir"] = ""
    if d:
        shutil.rmtree(d, ignore_errors=True)


def _zsign_flags():
    """Single-letter flags this zsign binary supports, from --help.
    Cached per process. On probe failure returns the long-standing
    baseline only (b/n/r/l/w) so newer options fail closed."""
    global _ZSIGN_FLAGS_CACHE
    if _ZSIGN_FLAGS_CACHE is not None:
        return _ZSIGN_FLAGS_CACHE
    _ZSIGN_FLAGS_CACHE = set("bnrlw")
    try:
        zsign = resolve_zsign()
        if zsign:
            proc = subprocess.run([zsign, "--help"], capture_output=True, text=True, timeout=30)
            out = (proc.stdout or "") + (proc.stderr or "")
            for m in re.finditer(r"(?<![A-Za-z0-9])-([A-Za-z0-9])(?=[,\s])", out):
                _ZSIGN_FLAGS_CACHE.add(m.group(1))
    except Exception:
        pass
    return _ZSIGN_FLAGS_CACHE


def _sign_opts_unsupported(opts):
    """Flag letters the current zsign lacks for the requested options."""
    opts = opts or {}
    have = _zsign_flags()
    missing = []
    for key, flag in _SIGNOPTS_FLAG_FOR.items():
        val = opts.get(key)
        if val and flag not in have:
            missing.append("-%s" % flag)
    return missing


def _sign_opts_cmd_args(opts):
    """zsign argv fragments for the requested options, in zsign's
    documented order. Custom bundle ID is NOT here: it is applied
    by rewriting job["app_bundle"] before provisioning (so the
    wrapper creates a profile for exactly that ID), or refused in
    the cached-sign flow. Returns (args, missing_flags)."""
    opts = opts or {}
    args = []
    if opts.get("display_name"):
        args += ["-n", opts["display_name"]]
    if opts.get("version"):
        args += ["-r", opts["version"]]
    if opts.get("icon_path"):
        args += ["-I", opts["icon_path"]]
    if opts.get("entitlements_path"):
        args += ["-e", opts["entitlements_path"]]
    if opts.get("min_ios"):
        args += ["-M", opts["min_ios"]]
    if opts.get("enable_files"):
        args += ["-S"]
    if opts.get("rm_extensions"):
        args += ["-E"]
    if opts.get("rm_watch"):
        args += ["-W"]
    if opts.get("rm_uisd"):
        args += ["-U"]
    for d in (opts.get("dylibs") or []):
        args += ["-l", d]
    if opts.get("weak_dylib"):
        args += ["-w"]
    if opts.get("inject_extensions"):
        args += ["-P"]
    return args, _sign_opts_unsupported(opts)


def sign_ipa(input_path, output_path, new_bundle_id=None, opts=None, pair=None):
    """Sign with zsign. Password is passed only to the subprocess,
    never printed, never logged. Returns (ok, error_text_safe).
    new_bundle_id, when given and different from the IPA's own ID,
    is passed as zsign -b, exactly like iloader's bundle rewrite.
    opts is the Feather-style options dict (see _sign_opts_default):
    only the flags actually set are passed, and any option whose
    flag this zsign does not support refuses the sign up front.
    pair, when given, is (p12_path, provision_path, p12_password)
    to sign with instead of the bot's own .env pair — used by
    the Feather certificates part (active imported certificate);
    None means the .env pair (today's behaviour everywhere).
    Before zsign runs, the Feather prep step edits the plist /
    Mach-O (and injects tweaks whose path/folder is not the
    default), injected dylibs get their hardcoded
    /Library/Frameworks/CydiaSubstrate.framework load paths
    rewritten to @rpath, and — like Feather — CydiaSubstrate.framework
    from ellekit.deb is added to the app when a tweak is injected
    and the app lacks it (plus any frameworks/bundles from .deb
    files). Only the dylibs the prep step could not inject itself
    are passed to zsign -l. In modify-only mode the prep + repack
    run but zsign is skipped and the modified-but-unsigned IPA is
    written to output_path. Non-fatal notes from this step land in
    _LAST_SIGN_NOTES for the caller to send via _send_sign_notes()."""
    global _LAST_SIGN_NOTES
    _LAST_SIGN_NOTES = []
    opts = opts or {}
    _pair_p12, _pair_prov, _pair_pw = pair if pair else (P12_PATH, PROVISION_PATH, P12_PASSWORD)
    if opts.get("modify_only"):
        _prepared, _tmpdirs, _fb, _err = _feather_build_modified(input_path, opts)
        if _prepared is None:
            return False, _err
        try:
            shutil.copyfile(_prepared, output_path)
        finally:
            for _d in _tmpdirs:
                shutil.rmtree(_d, ignore_errors=True)
        _LAST_SIGN_NOTES.append("Modified without signing (modify-only mode): this IPA is unsigned and cannot be installed.")
        return True, ""
    zsign = resolve_zsign()
    if not zsign:
        return False, tr("l10n_zsign_missing") % ZSIGN_PATH
    if not _pair_p12 or not os.path.exists(_pair_p12):
        return False, tr("l10n_p12_missing_short")
    if not _pair_prov or not os.path.exists(_pair_prov):
        return False, tr("l10n_profile_missing_short")
    # Minis diagnosis 2026-11-13: the old code reported only
    # "zsign failed" when zsign died silently (no stdout/stderr),
    # which hid the real cause. Check the inputs first, then
    # report the return code and sizes so the next failure is
    # diagnosable from the Telegram message alone.
    if not os.path.exists(input_path):
        return False, tr("l10n_zsign_err") + "input IPA not found: %s" % os.path.basename(input_path)
    _in_size = os.path.getsize(input_path)
    if _in_size <= 0:
        return False, tr("l10n_zsign_err") + "input IPA is empty (0 bytes)"
    if not _pair_pw:
        return False, tr("l10n_zsign_err") + "p12 password is empty, zsign cannot unlock the p12"
    _opt_args, _missing = _sign_opts_cmd_args(opts)
    if _missing:
        return False, tr("signopts_unsupported") % ", ".join(_missing)
    _tmpdirs = []
    _opts = dict(opts)
    try:
        # merge entitlements (profile + binary) when requested and no
        # custom file was sent; the merged file is passed via -e.
        if _opts.get("merge_entitlements") and not _opts.get("entitlements_path"):
            _prof_ent = _read_profile_entitlements(_pair_prov)
            _bin_ent = _ipa_binary_entitlements(input_path)
            if _prof_ent and _bin_ent:
                _team = _read_profile_team_id(_pair_prov)
                _bundle = new_bundle_id or _read_profile_bundle(_pair_prov) or ""
                _merged = _merge_entitlements(_prof_ent, _bin_ent, _bundle, _team)
                _etmp = tempfile.mkdtemp(prefix="tiloader-ent-")
                _tmpdirs.append(_etmp)
                _epath = os.path.join(_etmp, "merged.entitlements")
                with open(_epath, "wb") as _f:
                    plistlib.dump(_merged, _f)
                _opts["entitlements_path"] = _epath
                _opts["entitlements_name"] = "merged.entitlements"
        _prepared, _btmp, _zsign_dylibs, _err = _feather_build_modified(input_path, _opts)
        _tmpdirs += _btmp
        if _prepared is None:
            return False, _err
    except Exception as e:
        for _d in _tmpdirs:
            shutil.rmtree(_d, ignore_errors=True)
        return False, "feather_prep_failed: %s" % str(e)[:200]
    # only the fallback dylibs go to zsign -l (the rest were
    # injected by the prep step itself); re-check flags now that
    # the merged entitlements file (if any) is known
    _opts2 = dict(_opts)
    _opts2["dylibs"] = list(_zsign_dylibs)
    _opt_args, _missing = _sign_opts_cmd_args(_opts2)
    if _missing:
        for _d in _tmpdirs:
            shutil.rmtree(_d, ignore_errors=True)
        return False, tr("signopts_unsupported") % ", ".join(_missing)
    cmd = [zsign, "-f", "-k", _pair_p12, "-m", _pair_prov]
    # zsign has no way to read the p12 password except the command line,
    # so it is visible in `ps` to the same user for the length of the
    # sign (accepted risk, documented; on Minis that user is the phone
    # owner). The password is never logged or sent to the chat.
    cmd += ["-p", _pair_pw]
    if new_bundle_id:
        cmd += ["-b", new_bundle_id]
    cmd += _opt_args
    cmd += ["-o", output_path, _prepared]
    _dbg("sign_ipa: input %d bytes, output %s" % (_in_size, output_path))
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=1800)
    except subprocess.TimeoutExpired:
        for _d in _tmpdirs:
            shutil.rmtree(_d, ignore_errors=True)
        return False, tr("l10n_zsign_timeout")
    except OSError as e:
        # BUG FIX 2026-11-14: ENOEXEC/EACCES/E2BIG from the kernel (binary
        # not executable, built for another libc, too big for the phone)
        # used to escape sign_ipa entirely and surface as a generic
        # prov_error. Say what actually happened.
        for _d in _tmpdirs:
            shutil.rmtree(_d, ignore_errors=True)
        return False, tr("l10n_zsign_err") + "zsign не запускається: %s" % e
    for _d in _tmpdirs:
        shutil.rmtree(_d, ignore_errors=True)
    if proc.returncode == 0 and os.path.exists(output_path) and os.path.getsize(output_path) > 0:
        return True, ""
    _dbg("sign_ipa: rc=%s out=%s err=%s" % (proc.returncode, (proc.stdout or "")[-200:], (proc.stderr or "")[-200:]))
    # Return code -9 = killed (in Minis: OOM killer, too little RAM
    # for a large IPA -- the same OOM that killed `make` on
    # certcheck.o); -11 = segfault; other codes = zsign error.
    if proc.returncode == -9:
        return False, tr("l10n_zsign_err") + "zsign killed (rc -9, likely out of memory in Minis, input %d MB)" % (_in_size // 1048576)
    if proc.returncode == -11:
        return False, tr("l10n_zsign_err") + "zsign crashed (rc -11 segfault)"
    err = (proc.stderr or proc.stdout or "zsign failed")[-300:]
    return False, tr("l10n_zsign_err") + "rc=%s: %s" % (proc.returncode, err)


_MACHO_MAGICS = (b"\xce\xfa\xed\xfe", b"\xcf\xfa\xed\xfe", b"\xfe\xed\xfa\xce",
                 b"\xfe\xed\xfa\xcf", b"\xca\xfe\xba\xbe", b"\xca\xfe\xba\xbf")


# ---------------- FEATHER full (Phase 6, 2026-11-14-minis-feather6) ----------------
# Ported from the Windows bot (BOT_BUILD 2026-11-13-win-celldance):
# cert library, tweak/dylib injection (prep step), autoreplace,
# cert import, IPA inspect, IPA content browser. Signing still
# goes through the Minis zsign leg (sign_ipa below); the siboot
# path is untouched, and Feather options do not apply to it
# (see tr("feather_siboot_note") on the inspect screen).
# DPAPI: Minis has no DPAPI, so cert passwords fall back to
# the 0600-file plaintext store (store_password) with the
# same warning the Windows bot gives.
_LAST_SIGN_NOTES = []


def _send_sign_notes(chat_id):
    """Send any non-fatal notes stashed by the last sign_ipa() run
    (e.g. ElleKit missing) and clear them."""
    global _LAST_SIGN_NOTES
    notes = list(_LAST_SIGN_NOTES or [])
    _LAST_SIGN_NOTES = []
    for n in notes:
        try:
            send_message(chat_id, n)
        except Exception:
            pass


def resolve_ellekit():
    """Where ellekit.deb really is. ELLEKIT_PATH from .env wins when
    it exists, otherwise ellekit.deb next to bot.py."""
    _ep = ENV.get("ELLEKIT_PATH", "").strip()
    if _ep and os.path.exists(_ep):
        return _ep
    beside = os.path.join(BASE_DIR, "ellekit.deb")
    return beside if os.path.exists(beside) else ""


_SUBSTRATE_OLD_PREFIX = b"/Library/Frameworks/"
_SUBSTRATE_NEW_PREFIX = b"@rpath/"


def _rewrite_substrate_paths(path):
    """Rewrite hardcoded /Library/Frameworks/CydiaSubstrate.framework/
    load paths in a Mach-O (thin or fat) to @rpath/... so the dylib
    links against the framework shipped inside the app bundle.
    Same-length replacement with NUL padding; a command whose new
    path would be longer is left unchanged. Idempotent. Returns the
    number of rewritten load commands."""
    try:
        with open(path, "rb") as f:
            data = bytearray(f.read())
    except Exception:
        return 0
    slices = []
    if len(data) >= 8 and data[:4] in (b"\xca\xfe\xba\xbe", b"\xca\xfe\xba\xbf"):
        try:
            nfat = struct.unpack(">I", bytes(data[4:8]))[0]
            off = 8
            for _ in range(nfat):
                _cpu, _sub, _offset, _size, _align = struct.unpack(">IIIII", bytes(data[off:off + 20]))
                slices.append((_offset, _size))
                off += 20
        except Exception:
            return 0
    else:
        slices.append((0, len(data)))
    changed = 0
    for base, size in slices:
        if base + 4 > len(data):
            continue
        magic = bytes(data[base:base + 4])
        if magic in (b"\xce\xfa\xed\xfe", b"\xcf\xfa\xed\xfe"):
            en = "<"
        elif magic in (b"\xfe\xed\xfa\xce", b"\xfe\xed\xfa\xcf"):
            en = ">"
        else:
            continue
        is64 = magic in (b"\xcf\xfa\xed\xfe", b"\xfe\xed\xfa\xcf")
        try:
            ncmds = struct.unpack_from(en + "I", data, base + 16)[0]
        except Exception:
            continue
        cmd_off = base + (32 if is64 else 28)
        end = base + size
        for _ in range(ncmds):
            if cmd_off + 8 > end or cmd_off + 8 > len(data):
                break
            try:
                cmd, cmdsize = struct.unpack_from(en + "II", data, cmd_off)
            except Exception:
                break
            if cmdsize < 8:
                break
            if cmd in (0x0c, 0x0d, 0x20, 0x80000018, 0x8000001f, 0x80000023):
                try:
                    name_off = struct.unpack_from(en + "I", data, cmd_off + 8)[0]
                except Exception:
                    name_off = 0
                if 0 < name_off < cmdsize:
                    s0 = cmd_off + name_off
                    s1 = data.find(b"\x00", s0, cmd_off + cmdsize)
                    if s1 == -1:
                        s1 = cmd_off + cmdsize
                    old = bytes(data[s0:s1])
                    if old.startswith(_SUBSTRATE_OLD_PREFIX):
                        new = _SUBSTRATE_NEW_PREFIX + old[len(_SUBSTRATE_OLD_PREFIX):]
                        if len(new) <= len(old):
                            data[s0:s0 + len(new)] = new
                            for i in range(s0 + len(new), s1):
                                data[i] = 0
                            changed += 1
            cmd_off += cmdsize
    if changed:
        try:
            with open(path, "wb") as f:
                f.write(data)
        except Exception:
            return 0
    return changed


def _extract_ellekit_framework(deb_path, dest_dir):
    """Extract CydiaSubstrate.framework from ellekit.deb's data.tar
    into dest_dir/CydiaSubstrate.framework/. Returns the framework
    dir path, or None when the file is missing/broken."""
    tf, err = _deb_data_tarfile(deb_path)
    if err or tf is None:
        return None
    out = os.path.join(dest_dir, "CydiaSubstrate.framework")
    found = False
    try:
        with tf:
            for m in tf.getmembers():
                if not m.isfile():
                    continue
                norm = _tar_norm_name(m.name)
                if not norm:
                    continue
                if not norm.startswith("Library/Frameworks/CydiaSubstrate.framework/"):
                    continue
                rel = norm[len("Library/Frameworks/CydiaSubstrate.framework/"):]
                if not rel or os.path.basename(rel) == ".DS_Store":
                    continue
                dest = os.path.join(out, *rel.split("/"))
                try:
                    os.makedirs(os.path.dirname(dest), exist_ok=True)
                    with tf.extractfile(m) as src_f, open(dest, "wb") as dst_f:
                        shutil.copyfileobj(src_f, dst_f)
                    if m.mode:
                        os.chmod(dest, m.mode & 0o7777)
                    found = True
                except Exception:
                    continue
    except Exception:
        return None
    return out if found else None


def _ipa_app_prefix(ipa_path):
    """'Payload/<Name>.app/' for the first top-level .app in the IPA,
    or None."""
    try:
        with zipfile.ZipFile(ipa_path) as z:
            for n in z.namelist():
                if n.startswith("Payload/"):
                    second = n.split("/")[1]
                    if second.endswith(".app"):
                        return "Payload/" + second + "/"
    except Exception:
        pass
    return None


def _repack_ipa_with_extras(input_ipa, output_ipa, extras):
    """Copy an IPA entry-by-entry (streaming, metadata preserved)
    and add extras: [(arcname, fs_path)] — fs_path a file or a
    directory (walked). An extra whose arcname already exists in the
    IPA is skipped. Returns True on success."""
    try:
        with zipfile.ZipFile(input_ipa, "r") as zin:
            names = set(zin.namelist())
            with zipfile.ZipFile(output_ipa, "w", zipfile.ZIP_DEFLATED) as zout:
                for info in zin.infolist():
                    with zin.open(info, "r") as src_f, zout.open(info, "w") as dst_f:
                        shutil.copyfileobj(src_f, dst_f)
                for arcname, fs_path in extras:
                    if os.path.isdir(fs_path):
                        for root, _dirs, files in os.walk(fs_path):
                            for fn in files:
                                full = os.path.join(root, fn)
                                rel = os.path.relpath(full, fs_path)
                                arc = arcname.rstrip("/") + "/" + rel.replace(os.sep, "/")
                                if arc not in names:
                                    zout.write(full, arc)
                                    names.add(arc)
                    elif os.path.isfile(fs_path):
                        if arcname not in names:
                            zout.write(fs_path, arcname)
                            names.add(arcname)
        return True
    except Exception:
        return False


# ---------------------------------------------------------------------------
# Feather prep step (pre-sign): unzip -> edit Info.plist / Mach-O ->
# rezip -> zsign. Modeled on Feather (claration/feather):
# OptionsManager.swift / SigningHandler.swift / MachOUtils.m
# (LiveContainer-derived, Apache-2.0). Pure byte editing, no signing.
# The arm64e slice fixup is ALWAYS applied (Feather does it for
# every sign); the plist keys and the sdk26 patch apply only when
# the matching option is set. Runs on every sign_ipa call, before
# the extras repack and zsign. The input IPA is never modified.
# ---------------------------------------------------------------------------

_CPU_SUBTYPE_ARM64E = 0x00000002
_CPU_SUBTYPE_LIB64 = 0x80000000
_CPUTYPE_ARM64 = 0x0100000C
_LC_BUILD_VERSION = 0x32
_SDK_26_0 = 0x1A0000  # 26.0.0


def _macho_patch_arm64e(data):
    """arm64e slice fixup (MachOUtils LCPatchMachOFixupARM64eSlice):
    FAT binaries only. The first arm64e slice (cputype ARM64,
    cpusubtype exactly CPU_SUBTYPE_ARM64E) gets
    cpusubtype |= CPU_SUBTYPE_LIB64 in BOTH the slice header and
    the fat_arch entry. Returns (patched_bytes, applied)."""
    if len(data) < 8 or data[:4] != b"\xca\xfe\xba\xbe":
        return data, False
    nfat = struct.unpack(">I", data[4:8])[0]
    if nfat < 1 or len(data) < 8 + 20 * nfat:
        return data, False
    out = bytearray(data)
    for i in range(nfat):
        off = 8 + 20 * i
        cputype, cpusubtype, slice_off, _size = struct.unpack(">IIII", data[off:off + 16])
        if cputype == _CPUTYPE_ARM64 and cpusubtype == _CPU_SUBTYPE_ARM64E:
            struct.pack_into(">I", out, off + 4, cpusubtype | _CPU_SUBTYPE_LIB64)
            if slice_off + 12 <= len(data):
                struct.pack_into("<I", out, slice_off + 8, cpusubtype | _CPU_SUBTYPE_LIB64)
            return bytes(out), True
    return data, False


def _macho_patch_sdk26(data):
    """Liquid Glass enable, Mach-O part (MachOUtils LCPatchMachOForSDK26):
    LC_BUILD_VERSION (0x32) sdk -> 26.0.0 in every 64-bit slice
    (fat or thin 64-bit only). Returns (patched_bytes, patched_count)."""
    slices = []
    if len(data) >= 8 and data[:4] == b"\xca\xfe\xba\xbe":
        nfat = struct.unpack(">I", data[4:8])[0]
        for i in range(nfat):
            off = 8 + 20 * i
            if off + 20 > len(data):
                break
            cputype, _sub, slice_off, slice_size = struct.unpack(">IIII", data[off:off + 16])
            if cputype == _CPUTYPE_ARM64 and slice_off + 32 <= len(data):
                slices.append((slice_off, slice_size))
    elif len(data) >= 32 and struct.unpack_from("<I", data, 0)[0] == 0xFEEDFACF:
        slices.append((0, len(data)))
    if not slices:
        return data, 0
    out = bytearray(data)
    count = 0
    for slice_off, slice_size in slices:
        ncmds = struct.unpack_from("<I", data, slice_off + 16)[0]
        pos = slice_off + 32
        end = min(len(data), slice_off + slice_size) if slice_size else len(data)
        for _ in range(ncmds):
            if pos + 8 > end:
                break
            cmd, cmdsize = struct.unpack_from("<II", data, pos)
            if cmdsize < 8 or pos + cmdsize > end:
                break
            if cmd == _LC_BUILD_VERSION and cmdsize >= 24:
                struct.pack_into("<I", out, pos + 16, _SDK_26_0)
                count += 1
            pos += cmdsize
    return bytes(out), count


def _strings_set_name(data, name):
    """Set CFBundleDisplayName in an InfoPlist.strings file
    (binary plist or UTF-16 text). Returns new bytes; on any
    failure returns the input unchanged."""
    try:
        d = plistlib.loads(data)
        if isinstance(d, dict):
            d["CFBundleDisplayName"] = name
            return plistlib.dumps(d, fmt=plistlib.FMT_BINARY)
    except Exception:
        pass
    try:
        text = data.decode("utf-16")
        _safe = name.replace('"', '\\"')
        if "CFBundleDisplayName" in text:
            text = re.sub(r'"CFBundleDisplayName"\s*=\s*"[^"]*";',
                          '"CFBundleDisplayName" = "%s";' % _safe, text, count=1)
        else:
            text = text + '\n"CFBundleDisplayName" = "%s";\n' % _safe
        return text.encode("utf-16")
    except Exception:
        pass
    return data


# ---------------------------------------------------------------------------
# Feather rebuild part 2: entitlements, modify-only, PPQ, inject
# path/folder, disinject, remove-files, auto-replace, persistent
# tweak list. Modeled on Feather (claration/feather):
# OptionsManager.swift (defaults), SigningHandler.swift
# (_mergeEntitlements), TweakHandler.swift (inject path/folder,
# disinject), ConfigurationDictView.swift (auto-replace dicts).
# ---------------------------------------------------------------------------

def _random_ppq_string():
    """Feather's PPQ suffix: a random 6-char string (SigningView
    appends it to the bundle ID as identifier.ppqString)."""
    _alphabet = "abcdefghijklmnopqrstuvwxyz0123456789"
    return "".join(secrets.choice(_alphabet) for _ in range(6))


def _feather_effective_bundle(opts, info):
    """Bundle ID that will be signed: custom or the IPA's own,
    plus '.' + PPQ suffix when PPQ is on (Feather SigningView)."""
    base = (opts or {}).get("custom_bundle_id") or (info or {}).get("bundle_id") or (info or {}).get("bundle") or ""
    if (opts or {}).get("ppq"):
        _sfx = (opts or {}).get("ppq_string") or ""
        if _sfx:
            base = base + "." + _sfx
    return base


def _macho_slices(data):
    """Yield (off, size, is64, endian) for every Mach-O slice in
    data (thin or FAT, little- or big-endian). Mirrors
    _macho_parse's magic handling."""
    if not data or len(data) < 4:
        return
    try:
        if data[:4] in (b"\xca\xfe\xba\xbe", b"\xbe\xba\xfe\xca", b"\xca\xfe\xba\xbf"):
            _be = data[:4] in (b"\xca\xfe\xba\xbe", b"\xca\xfe\xba\xbf")
            _e = ">" if _be else "<"
            _n = struct.unpack_from(_e + "I", data, 4)[0]
            for i in range(min(_n, 64)):
                _off = 8 + i * 20
                if _off + 20 > len(data):
                    break
                _cpu, _sub, _foff, _fsize, _al = struct.unpack_from(_e + "IIIII", data, _off)
                if _foff + 4 > len(data):
                    continue
                # the slice's OWN magic decides its endianness: a
                # FAT header is big-endian, its arm64 slices are not
                _mb = data[_foff:_foff + 4]
                if _mb in (b"\xce\xfa\xed\xfe", b"\xcf\xfa\xed\xfe"):
                    yield (_foff, _fsize, _mb == b"\xcf\xfa\xed\xfe", "<")
                elif _mb in (b"\xfe\xed\xfa\xce", b"\xfe\xed\xfa\xcf"):
                    yield (_foff, _fsize, _mb == b"\xfe\xed\xfa\xcf", ">")
        else:
            _le = struct.unpack_from("<I", data, 0)[0]
            _be = struct.unpack_from(">I", data, 0)[0]
            if _le in (0xfeedface, 0xfeedfacf):
                yield (0, len(data), _le == 0xfeedfacf, "<")
            elif _be in (0xfeedface, 0xfeedfacf):
                yield (0, len(data), _be == 0xfeedfacf, ">")
    except Exception:
        return


def _macho_code_signature(data):
    """(dataoff, datasize) of the first slice's LC_CODE_SIGNATURE,
    absolute in data, or None. data may be just the file header
    (load commands live right after the Mach-O header)."""
    try:
        for _off, _size, _is64, _e in _macho_slices(data):
            _hdr = 32 if _is64 else 28
            if _off + _hdr + 8 > len(data):
                continue
            _ncmds, _sizeof = struct.unpack_from(_e + "II", data, _off + 16)
            _p = _off + _hdr
            for _ in range(min(_ncmds, 512)):
                if _p + 8 > len(data):
                    break
                _cmd, _cs = struct.unpack_from(_e + "II", data, _p)
                if _cs < 8:
                    break
                if _cmd == 0x1D:  # LC_CODE_SIGNATURE
                    _do, _ds = struct.unpack_from(_e + "II", data, _p + 8)
                    return (_off + _do, _ds)
                _p += _cs
            return None
    except Exception:
        return None
    return None


def _macho_read_entitlements(data):
    """The embedded entitlements dict of the first slice that has a
    code signature, or {}. Parses the superblob (slot 7)."""
    try:
        sig = _macho_code_signature(data)
        if not sig:
            return {}
        _off, _size = sig
        if _off + 16 > len(data) or _size < 16:
            return {}
        if struct.unpack_from(">I", data, _off)[0] != 0xfade0cc0:
            return {}
        _count = struct.unpack_from(">I", data, _off + 8)[0]
        for i in range(min(_count, 32)):
            _typ, _eoff = struct.unpack_from(">II", data, _off + 12 + i * 8)
            if _typ == 7:  # CSSLOT_ENTITLEMENTS
                _boff = _off + _eoff
                if _boff + 8 > len(data):
                    return {}
                _blen = struct.unpack_from(">I", data, _boff + 4)[0]
                if _blen < 8 or _boff + _blen > len(data):
                    return {}
                ent = plistlib.loads(data[_boff + 8:_boff + _blen])
                return ent if isinstance(ent, dict) else {}
        return {}
    except Exception:
        return {}


def _macho_disinject(data, paths):
    """Remove LC_LOAD_DYLIB commands (and weak/re-export variants)
    whose path matches any of paths (full path or basename).
    Returns (new_data, removed_count). The command area is
    rebuilt without the deleted commands; the code signature is
    invalidated (re-sign after)."""
    try:
        _paths = set(paths or [])
        if not _paths:
            return data, 0
        _bases = {os.path.basename(p) for p in _paths}
        out = bytearray(data)
        removed = 0
        for _off, _size, _is64, _e in _macho_slices(bytes(out)):
            _hdr = 32 if _is64 else 28
            if _off + _hdr + 8 > len(out):
                continue
            _ncmds, _sizeof = struct.unpack_from(_e + "II", out, _off + 16)
            _p = _off + _hdr
            _del = []
            for _ in range(min(_ncmds, 512)):
                if _p + 8 > len(out):
                    break
                _cmd, _cs = struct.unpack_from(_e + "II", out, _p)
                if _cs < 8:
                    break
                if _cmd in _MACHO_LOAD_DYLIB_CMDS and _cs >= 12:
                    _noff = struct.unpack_from(_e + "I", out, _p + 8)[0]
                    _nstart = _p + _noff
                    _nend = bytes(out).find(b"\x00", _nstart, _p + _cs)
                    _name = ""
                    if 0 <= _nstart < len(out) and _nend > _nstart:
                        _name = bytes(out[_nstart:_nend]).decode("utf-8", "ignore")
                    if _name in _paths or os.path.basename(_name) in _bases:
                        _del.append((_p, _cs))
                _p += _cs
            if not _del:
                continue
            _total = sum(_cs for _, _cs in _del)
            _src = _off + _hdr
            _cmds = bytes(out[_src:_src + _sizeof])
            _new = bytearray()
            _q = 0
            for (_dp, _dc) in _del:
                _rel = _dp - _src
                _new += _cmds[_q:_rel]
                _q = _rel + _dc
            _new += _cmds[_q:]
            out[_src:_src + _sizeof] = bytes(_new) + b"\x00" * _total
            struct.pack_into(_e + "I", out, _off + 16, _ncmds - len(_del))
            struct.pack_into(_e + "I", out, _off + 20, _sizeof - _total)
            removed += len(_del)
        return bytes(out), removed
    except Exception:
        return data, 0


def _macho_add_load_dylib(data, load_path):
    """Insert an LC_LOAD_DYLIB for load_path into each slice's
    command slack (between the end of the load commands and the
    first section — the new command overwrites slack bytes, so
    nothing shifts). Returns (new_data, ok). Only little-endian
    slices with enough slack succeed; anything else fails closed
    (the caller falls back to zsign -l)."""
    try:
        _name = load_path.encode("utf-8") + b"\x00"
        _cmdsize = (24 + len(_name) + 7) // 8 * 8
        out = bytearray(data)
        ok = True
        for _off, _size, _is64, _e in _macho_slices(bytes(out)):
            if _e != "<":
                ok = False
                continue
            _hdr = 32 if _is64 else 28
            if _off + _hdr + 8 > len(out):
                ok = False
                continue
            _ncmds, _sizeof = struct.unpack_from(_e + "II", out, _off + 16)
            _p = _off + _hdr
            _min_sect = None
            for _ in range(min(_ncmds, 512)):
                if _p + 8 > len(out):
                    break
                _cmd, _cs = struct.unpack_from(_e + "II", out, _p)
                if _cs < 8:
                    break
                if _cmd in (0x1, 0x19):  # LC_SEGMENT / LC_SEGMENT_64
                    if _is64:
                        _nsects = struct.unpack_from(_e + "I", out, _p + 64)[0]
                        _sbase, _ssize, _soff = _p + 72, 80, 48
                    else:
                        _nsects = struct.unpack_from(_e + "I", out, _p + 48)[0]
                        _sbase, _ssize, _soff = _p + 56, 68, 40
                    for _i in range(min(_nsects, 256)):
                        _sp = _sbase + _i * _ssize
                        if _sp + _soff + 4 > len(out):
                            break
                        _so = struct.unpack_from(_e + "I", out, _sp + _soff)[0]
                        if _so > 0 and (_min_sect is None or _so < _min_sect):
                            _min_sect = _so
                _p += _cs
            if _min_sect is None:
                ok = False
                continue
            if _min_sect - (_off + _hdr + _sizeof) < _cmdsize:
                ok = False
                continue
            _ins = _off + _hdr + _sizeof
            _cmd = struct.pack(_e + "IIIIII", 0x0C, _cmdsize, 24, 2, 0, 0)
            _cmd += _name + b"\x00" * (_cmdsize - 24 - len(_name))
            out[_ins:_ins + _cmdsize] = _cmd
            struct.pack_into(_e + "I", out, _off + 16, _ncmds + 1)
            struct.pack_into(_e + "I", out, _off + 20, _sizeof + _cmdsize)
        return bytes(out), ok
    except Exception:
        return data, False


def _feather_dylib_load_path(inject_path, inject_folder, base):
    """The LC_LOAD_DYLIB path Feather uses for a tweak
    (TweakHandler.swift): @rpath + /Frameworks/ resolves into
    Frameworks already, so the load-path folder is /; anything
    else keeps the folder."""
    _folder = inject_folder or "/Frameworks/"
    if inject_path == "@rpath" and _folder == "/Frameworks/":
        _folder = "/"
    return (inject_path or "@executable_path") + _folder + base


def _feather_dylib_place(inject_path, inject_folder, base):
    """Where the dylib file goes inside the .app: Frameworks/ when
    the folder is /Frameworks/, else the app root (TweakHandler)."""
    if (inject_folder or "/Frameworks/") == "/Frameworks/":
        return "Frameworks/" + base
    return base


def _read_profile_entitlements(path):
    """Entitlements dict from a .mobileprovision file, or {}."""
    try:
        with open(path, "rb") as f:
            blob = f.read()
        start = blob.find(b"<?xml")
        end = blob.rfind(b"</plist>")
        if start < 0 or end < 0:
            return {}
        prov = plistlib.loads(blob[start:end + len(b"</plist>")])
        ent = prov.get("Entitlements") or {}
        return ent if isinstance(ent, dict) else {}
    except Exception:
        return {}


def _read_profile_team_id(path):
    """Team ID (TeamIdentifier[0]) from a .mobileprovision file,
    or "". TeamIdentifier is a TOP-LEVEL key in the provision,
    not part of the Entitlements dict."""
    try:
        with open(path, "rb") as f:
            blob = f.read()
        start = blob.find(b"<?xml")
        end = blob.rfind(b"</plist>")
        if start < 0 or end < 0:
            return ""
        prov = plistlib.loads(blob[start:end + len(b"</plist>")])
        team = prov.get("TeamIdentifier") or []
        return team[0] if team else ""
    except Exception:
        return ""


def _merge_entitlements(profile_ent, binary_ent, bundle_id, team_id):
    """Feather's _mergeEntitlements (SigningHandler.swift): base is
    the profile entitlements; "*" in values is replaced with the
    new bundle ID, except com.apple.developer.associated-domains
    and application.identifier (left as-is); keychain-access-groups
    come from the BINARY entitlements, filtered to
    ^[A-Z0-9]{10}\\. and rewritten to <team>.<suffix>."""
    merged = dict(profile_ent or {})
    for k, v in list(merged.items()):
        if k in ("com.apple.developer.associated-domains",
                 "application-identifier", "application.identifier"):
            continue
        if isinstance(v, str):
            merged[k] = v.replace("*", bundle_id)
        elif isinstance(v, list):
            merged[k] = [x.replace("*", bundle_id) if isinstance(x, str) else x for x in v]
    if isinstance(binary_ent, dict):
        kag = binary_ent.get("keychain-access-groups")
        if isinstance(kag, list) and kag:
            new_kag = []
            for g in kag:
                if isinstance(g, str) and re.match(r"^[A-Z0-9]{10}\.", g) and team_id:
                    new_kag.append(team_id + "." + g[11:])
                elif isinstance(g, str):
                    new_kag.append(g)
            if new_kag:
                merged["keychain-access-groups"] = new_kag
    return merged


def _ipa_binary_entitlements(ipa_path):
    """The main executable's embedded entitlements (from its code
    signature), or {}. Only the header is read first; the signature
    blob is then seek-read, so a big executable is not loaded."""
    try:
        with zipfile.ZipFile(ipa_path) as zf:
            _app = _ipa_app_prefix(ipa_path)
            if not _app:
                return {}
            _plist = plistlib.loads(zf.read(_app + "Info.plist"))
            _exe = _plist.get("CFBundleExecutable") or ""
            if not _exe:
                return {}
            with zf.open(_app + _exe) as f:
                _head = f.read(1 << 16)
                _sig = _macho_code_signature(_head)
                if not _sig:
                    return {}
                _off, _size = _sig
                if _off < len(_head):
                    _data = _head + f.read(max(0, _off + _size - len(_head)))
                    return _macho_read_entitlements(_data)
                f.seek(_off)
                _blob = f.read(_size)
                return _macho_read_entitlements(_blob)
    except Exception:
        return {}


def _feather_entitlements_summary(opts, info, ipa_path=None):
    """One short line saying which entitlements the sign will use:
    the custom file, the merge preview, or the profile's."""
    opts = opts or {}
    if opts.get("entitlements_name"):
        return tr("feather_ent_summary_custom") % opts["entitlements_name"]
    if opts.get("merge_entitlements"):
        prof = _read_profile_entitlements(PROVISION_PATH) if PROVISION_PATH else {}
        if not prof:
            return tr("feather_ent_summary_noprofile")
        _bin_ent = _ipa_binary_entitlements(ipa_path) if ipa_path else {}
        _team = _read_profile_team_id(PROVISION_PATH) if PROVISION_PATH else ""
        _bundle = _feather_effective_bundle(opts, info) or "?"
        _merged = _merge_entitlements(prof, _bin_ent, _bundle, _team)
        _keys = sorted(_merged.keys())
        _shown = ", ".join(_keys[:4])
        if len(_keys) > 4:
            _shown += " +%d" % (len(_keys) - 4)
        return tr("feather_ent_summary_merge") % (_shown or "—")
    return tr("feather_ent_summary_profile")


AUTOREPLACE_PATH = os.path.join(BASE_DIR, "feather_autoreplace.json")


def _autoreplace_load():
    """Auto-replace pairs: {"identifiers": {old: new},
    "display_names": {old: new}}. Missing/corrupt file = empty."""
    try:
        with open(AUTOREPLACE_PATH, "r", encoding="utf-8") as f:
            d = json.load(f)
        if isinstance(d, dict):
            return {"identifiers": dict(d.get("identifiers") or {}),
                    "display_names": dict(d.get("display_names") or {})}
    except Exception:
        pass
    return {"identifiers": {}, "display_names": {}}


def _autoreplace_save(data):
    try:
        with open(AUTOREPLACE_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        try:
            os.chmod(AUTOREPLACE_PATH, 0o600)
        except Exception:
            pass
        return True
    except Exception:
        return False


def _feather_apply_autoreplace(opts, info):
    """Fill custom_bundle_id / display_name from the auto-replace
    pairs when the current values still match the IPA's own (i.e.
    the user did not type something else). Runs before provisioning
    so the profile is created for the replaced bundle ID. Returns
    True when anything was replaced."""
    ar = _autoreplace_load()
    changed = False
    _b = (info or {}).get("bundle_id") or (info or {}).get("bundle") or ""
    if _b and not (opts.get("custom_bundle_id") or "").strip():
        if _b in ar["identifiers"]:
            opts["custom_bundle_id"] = ar["identifiers"][_b]
            changed = True
    _t = (info or {}).get("title") or ""
    if _t and (opts.get("display_name") or "") in ("", _t):
        if _t in ar["display_names"]:
            opts["display_name"] = ar["display_names"][_t]
            changed = True
    return changed


def _feather_state_load():
    try:
        with open(os.path.join(BASE_DIR, "feather_state.json"), "r", encoding="utf-8") as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _feather_state_save(state):
    try:
        with open(os.path.join(BASE_DIR, "feather_state.json"), "w", encoding="utf-8") as f:
            json.dump(state, f, ensure_ascii=False)
        return True
    except Exception:
        return False


# --- Feather certificates (rebuild part 3) ----------------------
# Imported .p12 + .mobileprovision pairs live in BASE_DIR/certs/
# and are listed in feather_certs.json:
#   {"certs": [{"id", "nickname", "p12", "provision" (paths
#   relative to BASE_DIR), "pw" (store_password), "pw_enc",
#   "team", "subject", "expires" (ISO), "verified" (bool)}],
#   "active_id": <id or None>}
# active_id None means the bot's own Provision-created pair
# (P12_PATH / PROVISION_PATH from .env). The p12 password is
# stored with the SAME store_password() (DPAPI) the bot uses
# for profile passwords — never plaintext when DPAPI exists,
# never in chat or logs.
def _feather_certs_path():
    return os.path.join(BASE_DIR, "feather_certs.json")


def _feather_certs_load():
    try:
        with open(_feather_certs_path(), "r", encoding="utf-8") as f:
            d = json.load(f)
        if isinstance(d, dict):
            d.setdefault("certs", [])
            if not isinstance(d["certs"], list):
                d["certs"] = []
            return d
    except Exception:
        pass
    return {"certs": [], "active_id": None}


def _feather_certs_save(data):
    try:
        tmp = _feather_certs_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        os.replace(tmp, _feather_certs_path())
        try:
            os.chmod(_feather_certs_path(), 0o600)
        except Exception:
            pass
        return True
    except Exception:
        return False


def _feather_certs_dir():
    d = os.path.join(BASE_DIR, "certs")
    os.makedirs(d, exist_ok=True)
    return d


def _feather_cert_find(data, cid):
    for c in data.get("certs") or []:
        if str(c.get("id")) == str(cid):
            return c
    return None


def _feather_cert_abs(rec, key):
    """Absolute path of a stored cert file (relative in the
    store), or "" when it is missing."""
    rel = (rec or {}).get(key) or ""
    if not rel:
        return ""
    p = rel if os.path.isabs(rel) else os.path.join(BASE_DIR, rel)
    return p


def _feather_active_cert():
    """The imported cert record selected as active, or None
    (None also means: use the bot's own Provision pair)."""
    data = _feather_certs_load()
    aid = data.get("active_id")
    if aid is None:
        return None
    return _feather_cert_find(data, aid)


def _feather_active_cert_broken():
    """True when an imported cert is selected but its record or
    its files are gone (deleted/moved in Minis)."""
    rec = _feather_active_cert()
    if rec is None:
        return False
    if not rec:
        return True
    p12 = _feather_cert_abs(rec, "p12")
    prov = _feather_cert_abs(rec, "provision")
    return not (p12 and os.path.exists(p12) and prov and os.path.exists(prov))


def _feather_cert_password(rec):
    """Decrypted p12 password of an imported cert, or None.
    Same DPAPI scheme as profile_password()."""
    if not rec:
        return None
    pw = rec.get("pw", "")
    if not pw:
        return None
    if rec.get("pw_enc"):
        raw = _dpapi_unprotect(base64.b64decode(pw))
        if raw is None:
            return None
        return raw.decode("utf-8", errors="replace")
    return pw


def _feather_active_sign_pair():
    """(p12_path, provision_path, p12_password) the next Feather
    sign should use: the active imported cert, else the bot's
    own pair from .env (today's behaviour)."""
    rec = _feather_active_cert()
    if rec is not None:
        p12 = _feather_cert_abs(rec, "p12")
        prov = _feather_cert_abs(rec, "provision")
        if p12 and os.path.exists(p12) and prov and os.path.exists(prov):
            return (p12, prov, _feather_cert_password(rec))
        return (None, None, None)
    return (P12_PATH, PROVISION_PATH, P12_PASSWORD)


def _feather_openssl():
    """openssl location from PATH. Minis has no Windows install
    path; when openssl is missing the p12 password simply
    cannot be verified (the import warns honestly)."""
    return shutil.which("openssl")


def _feather_cert_read_p12(p12_path, password):
    """Read a .p12 with openssl (password via stdin only, never
    on a command line, never logged). Returns (ok, info, err):
    info = {"subject", "team", "cn", "not_after" (ISO or ""),
    "fingerprint"}; err is "no_openssl" when openssl is missing
    in Minis (then the password cannot be verified at all),
    "bad_password" when the password does not open the file."""
    op = _feather_openssl()
    if op is None:
        return False, None, "no_openssl"
    try:
        pkcs12 = subprocess.run(
            [op, "pkcs12", "-in", p12_path, "-nokeys", "-clcerts", "-passin", "stdin"],
            input=((password or "") + "\n").encode(), capture_output=True, timeout=60)
        pem = pkcs12.stdout
        if pkcs12.returncode != 0 or b"BEGIN CERTIFICATE" not in pem:
            return False, None, "bad_password"
        subj = subprocess.run([op, "x509", "-subject", "-noout"],
                              input=pem, capture_output=True, timeout=60)
        dates = subprocess.run([op, "x509", "-dates", "-noout"],
                               input=pem, capture_output=True, timeout=60)
        fp = subprocess.run([op, "x509", "-fingerprint", "-sha1", "-noout"],
                            input=pem, capture_output=True, timeout=60)
        subj_text = subj.stdout.decode("utf-8", errors="ignore")
        dates_text = dates.stdout.decode("utf-8", errors="ignore")
        team, _cn_team, _ou_team = _cert_team_from_subject(subj_text)
        cn_m = re.search(r"CN\s*=\s*([^,/]+)", subj_text)
        not_after = ""
        for line in dates_text.splitlines():
            if line.strip().lower().startswith("notafter="):
                raw = line.split("=", 1)[1].strip()
                try:
                    dt = datetime.strptime(raw, "%b %d %H:%M:%S %Y %Z")
                    not_after = dt.date().isoformat()
                except Exception:
                    not_after = raw
                break
        fp_m = re.search(r"=([0-9A-Fa-f:]{59})", fp.stdout.decode("utf-8", errors="ignore"))
        return True, {"subject": subj_text.strip(), "team": team or "",
                      "cn": (cn_m.group(1).strip() if cn_m else ""),
                      "not_after": not_after,
                      "fingerprint": (fp_m.group(1).replace(":", "").lower() if fp_m else "")}, ""
    except Exception:
        return False, None, "bad_password"


def _feather_read_provision(path):
    """Full .mobileprovision plist dict, or {}. Same byte-search
    extraction as _read_profile_entitlements."""
    try:
        with open(path, "rb") as f:
            blob = f.read()
        start = blob.find(b"<?xml")
        end = blob.rfind(b"</plist>")
        if start < 0 or end < 0:
            return {}
        prov = plistlib.loads(blob[start:end + len(b"</plist>")])
        return prov if isinstance(prov, dict) else {}
    except Exception:
        return {}


def _feather_cert_expiry_text(exp_iso):
    """'12.03.2027 (ще 120 дн.)' / 'прострочено' / 'невідомо'."""
    if not exp_iso:
        return tr("feather_cert_no_expiry")
    try:
        d = datetime.strptime(str(exp_iso)[:10], "%Y-%m-%d").date()
    except Exception:
        return str(exp_iso)
    left = (d - datetime.now(timezone.utc).date()).days
    disp = d.strftime("%d.%m.%Y")
    if left < 0:
        return "%s (%s)" % (disp, tr("feather_cert_expired_mark"))
    return tr("feather_cert_expires_days") % (disp, left)


def _feather_builtin_summary():
    """(label, active_bool, detail) for the bot's own pair:
    team + expiry from the current PROVISION_PATH, or a
    'none yet' note when no profile exists."""
    active = _feather_active_cert() is None
    _mark = "✅" if active else "•"
    if not PROVISION_PATH or not os.path.exists(PROVISION_PATH):
        return ("%s %s — %s" % (_mark, tr("feather_certs_builtin_name"), tr("feather_certs_builtin_none")),
                active, None)
    prov = _feather_read_provision(PROVISION_PATH)
    team = ""
    try:
        team = (prov.get("TeamIdentifier") or [""])[0]
    except Exception:
        team = ""
    exp = prov.get("ExpirationDate")
    exp_iso = ""
    try:
        # Phase 6 fix: a missing ExpirationDate used to render as
        # the literal string "None" (str(None)); keep it empty so
        # the expiry text falls back to "unknown".
        exp_iso = exp.date().isoformat() if hasattr(exp, "date") else (str(exp) if exp else "")
    except Exception:
        exp_iso = ""
    label = "%s %s — %s, %s" % (_mark, tr("feather_certs_builtin_name"), team or "?",
                             _feather_cert_expiry_text(exp_iso))
    return (label, active, prov)


def _feather_cert_row_label(rec, active):
    """List-row label for an imported cert."""
    return "%s %s — %s, %s" % ("✅" if active else "•",
                               (rec.get("nickname") or "?")[:32],
                               rec.get("team") or "?",
                               _feather_cert_expiry_text(rec.get("expires") or ""))


def _feather_certs_label_map():
    """label -> action for the dynamic rows on the certs screen,
    mirroring _feather_opts_label_map (dynamic labels cannot
    resolve via btn_action)."""
    data = _feather_certs_load()
    active_id = data.get("active_id")
    m = {}
    label, _a, _d = _feather_builtin_summary()
    m[label] = "feather_cert_builtin"
    for c in data.get("certs") or []:
        m[_feather_cert_row_label(c, str(c.get("id")) == str(active_id))] = "feather_cert:%s" % c.get("id")
    return m


def _feather_current_profile_in(profiles):
    """_feather_current_profile over an already-loaded list, so a
    caller can mutate the found record and save THAT list."""
    if not profiles:
        return None
    _pid = job.get("profile_id")
    for p in profiles:
        if p.get("id") == _pid:
            return p
    _aid = job.get("apple_id") or ""
    for p in profiles:
        if _aid and p.get("apple_id") == _aid:
            return p
    if len(profiles) == 1:
        return profiles[0]
    _last = _feather_state_load().get("last_profile_id")
    for p in profiles:
        if p.get("id") == _last:
            return p
    return None


def _feather_current_profile():
    """The profile the current Feather sign will use (job profile,
    else the job's Apple ID, else the single profile, else the
    last-used one), or None when it cannot be told apart."""
    return _feather_current_profile_in(load_profiles())


def _feather_tweaks_dir(profile_id):
    d = os.path.join(BASE_DIR, "feather_tweaks", str(profile_id))
    os.makedirs(d, exist_ok=True)
    return d


def _feather_tweaks_save_current(opts):
    """Remember the current dylib/framework/bundle tweak files for
    the current profile: copies into feather_tweaks/<profile id>/
    and records the names on the profile record. The record is
    mutated and saved from ONE loaded list (a second load would
    give fresh dicts and drop the change)."""
    profiles = load_profiles()
    prof = _feather_current_profile_in(profiles)
    if not prof:
        return False
    d = _feather_tweaks_dir(prof.get("id"))
    names = {"dylibs": [], "frameworks": [], "bundles": []}
    for kind in ("dylibs", "frameworks", "bundles"):
        for src in (opts.get(kind) or []):
            try:
                bname = os.path.basename(src)
                if not bname or not os.path.exists(src):
                    continue
                dst = os.path.join(d, bname)
                if os.path.abspath(src) != os.path.abspath(dst):
                    shutil.copyfile(src, dst)
                if bname not in names[kind]:
                    names[kind].append(bname)
            except Exception:
                pass
    prof["tweaks"] = names
    return save_profiles(profiles)


def _feather_tweaks_prefill(opts, tmpdir):
    """Copy the current profile's remembered tweaks into the job
    tmpdir and prefill them into opts. Returns the count added."""
    prof = _feather_current_profile()
    if not prof:
        return 0
    names = prof.get("tweaks") or {}
    if not isinstance(names, dict):
        return 0
    d = os.path.join(BASE_DIR, "feather_tweaks", str(prof.get("id")))
    n = 0
    for kind in ("dylibs", "frameworks", "bundles"):
        for bname in (names.get(kind) or []):
            src = os.path.join(d, bname)
            if not os.path.exists(src):
                continue
            dst = os.path.join(tmpdir, bname)
            try:
                shutil.copyfile(src, dst)
            except Exception:
                continue
            if dst not in (opts.get(kind) or []):
                opts.setdefault(kind, []).append(dst)
                n += 1
    return n


def _feather_tweaks_clear_current():
    """Forget the current profile's remembered tweaks (files +
    profile record). Returns True when a profile was found."""
    profiles = load_profiles()
    prof = _feather_current_profile_in(profiles)
    if not prof:
        return False
    d = os.path.join(BASE_DIR, "feather_tweaks", str(prof.get("id")))
    shutil.rmtree(d, ignore_errors=True)
    prof["tweaks"] = {"dylibs": [], "frameworks": [], "bundles": []}
    return save_profiles(profiles)


def _feather_prep_ipa(input_ipa, output_ipa, opts):
    """Feather pre-sign step. Returns
    (prepared_path, [temp_dirs], [zsign_dylibs], reason) — 4 values,
    as _feather_build_modified unpacks it: prepared_path is None on
    failure with reason set. zsign_dylibs are the tweaks the bot could
    NOT inject itself (default @rpath + /Frameworks/ combo, or no
    command slack) — the caller passes them to zsign -l instead. Only
    the entries that change are held in memory; everything else streams
    through. The main executable is patched in memory only when it is
    <= 512 MB; a bigger executable keeps the plist edits and skips the
    Mach-O patches (documented limit, not a silent failure — the caller
    still signs). Applies, in order: remove Frameworks/PlugIns
    (rm_files), disinject loaded dylibs, plist options, arm64e + SDK26
    Mach-O patches, bot-side dylib injection (non-default path/folder),
    display-name localisation. The input IPA is never modified."""
    opts = opts or {}
    try:
        _rm = set(opts.get("rm_files") or [])

        def _is_rm(rel):
            _r = (rel or "").rstrip("/")
            for _e in _rm:
                if _r == _e or _r.startswith(_e + "/"):
                    return True
            return False

        with zipfile.ZipFile(input_ipa) as z:
            names = z.namelist()
            app_prefix = None
            for n in names:
                if n.startswith("Payload/") and n.endswith(".app/Info.plist") and n.count("/") == 2:
                    app_prefix = n[:-len("Info.plist")]
                    break
            if app_prefix is None:
                for n in names:
                    if n.startswith("Payload/") and n.endswith(".app/Info.plist"):
                        app_prefix = n[:-len("Info.plist")]
                        break
            if app_prefix is None:
                return False, "no_info_plist", []
            try:
                info = plistlib.loads(z.read(app_prefix + "Info.plist"))
            except Exception:
                return False, "bad_info_plist", []
            # --- plist edits (Feather OptionsManager) ---
            if (opts.get("appearance") or "") in ("Light", "Dark"):
                info["UIUserInterfaceStyle"] = opts["appearance"]
            if opts.get("itunes_files"):
                info["UIFileSharingEnabled"] = True
            if opts.get("promotion"):
                info["CADisableMinimumFrameDurationOnPhone"] = True
            if opts.get("game_mode"):
                info["GCSupportsGameMode"] = True
            if opts.get("ipad_fullscreen"):
                info["UIRequiresFullScreen"] = True
            if opts.get("rm_url_scheme"):
                info.pop("CFBundleURLTypes", None)
            _lg = opts.get("liquid_glass") or ""
            if _lg == "disable":
                info["UIDesignRequiresCompatibility"] = True
            elif _lg == "enable":
                info["UIDesignRequiresCompatibility"] = False
            _disp = (opts.get("display_name") or "").strip()
            if not _disp or _disp in (str(info.get("CFBundleDisplayName") or ""),
                                      str(info.get("CFBundleName") or "")):
                # auto-replace fallback: the IPA's own title matches a
                # display-name pair (the entry points normally fill
                # this in; the prov flow does not)
                _ar = _autoreplace_load()
                _orig = str(info.get("CFBundleDisplayName") or info.get("CFBundleName") or "")
                if _orig in _ar["display_names"]:
                    _disp = _ar["display_names"][_orig]
            if opts.get("force_localize") and _disp:
                info["CFBundleDisplayName"] = _disp
            new_plist = plistlib.dumps(info)
            _exe_name = app_prefix + str(info.get("CFBundleExecutable") or "")
            _exe_data = None
            if _exe_name:
                try:
                    _zinf = z.getinfo(_exe_name)
                    if _zinf.file_size <= 512 * 1024 * 1024:
                        _exe_data = z.read(_exe_name)
                        _exe_data, _fixed = _macho_patch_arm64e(_exe_data)
                        if _lg == "enable":
                            _exe_data, _n = _macho_patch_sdk26(_exe_data)
                        if opts.get("disinject"):
                            _exe_data, _nrm = _macho_disinject(_exe_data, opts.get("disinject"))
                            if _nrm:
                                _LAST_SIGN_NOTES.append("Disinjected %d dylib(s) from the executable." % _nrm)
                except Exception:
                    _exe_data = None
            # --- bot-side dylib injection (non-default path/folder) ---
            _inject_list = []  # (load_path, place_rel, fs_path)
            _zsign_dylibs = []
            for _d in (opts.get("dylibs") or []):
                _base = os.path.basename(_d)
                if not _base:
                    continue
                _path = opts.get("inject_path") or "@executable_path"
                _folder = opts.get("inject_folder") or "/Frameworks/"
                _load = _feather_dylib_load_path(_path, _folder, _base)
                _place = _feather_dylib_place(_path, _folder, _base)
                if _path == "@rpath" and _folder == "/Frameworks/":
                    _zsign_dylibs.append(_d)
                    continue
                if _exe_data is None:
                    _zsign_dylibs.append(_d)
                    continue
                _new, _ok = _macho_add_load_dylib(_exe_data, _load)
                if not _ok:
                    _zsign_dylibs.append(_d)
                    continue
                _exe_data = _new
                _inject_list.append((_load, _place, _d))
            # --- appex injection (@executable_path only; @rpath goes
            # through zsign -P with the fallback dylibs) ---
            _patched = {}
            if opts.get("inject_extensions") and _inject_list:
                _ax_loads = []
                for _load, _place, _d in _inject_list:
                    _path = opts.get("inject_path") or "@executable_path"
                    if _path != "@executable_path":
                        continue
                    _folder = opts.get("inject_folder") or "/Frameworks/"
                    _ax_loads.append("@executable_path/../.." + _folder + os.path.basename(_d))
                if _ax_loads:
                    for _n in names:
                        if not (_n.startswith(app_prefix + "PlugIns/") and _n.endswith(".appex/")):
                            continue
                        if _is_rm(_n[len(app_prefix):]):
                            continue
                        try:
                            _ax_info = plistlib.loads(z.read(_n + "Info.plist"))
                        except Exception:
                            continue
                        _ax_exe = _ax_info.get("CFBundleExecutable") or ""
                        if not _ax_exe:
                            continue
                        try:
                            _ax_data = z.read(_n + _ax_exe)
                        except Exception:
                            continue
                        if len(_ax_data) > 64 * 1024 * 1024:
                            continue
                        for _al in _ax_loads:
                            _ax_new, _ax_ok = _macho_add_load_dylib(_ax_data, _al)
                            if _ax_ok:
                                _ax_data = _ax_new
                        _patched[_n + _ax_exe] = _ax_data
            with zipfile.ZipFile(output_ipa, "w", zipfile.ZIP_DEFLATED) as out:
                for n in names:
                    _rel = n[len(app_prefix):] if n.startswith(app_prefix) else None
                    if _rel is not None and _is_rm(_rel):
                        continue
                    if n == app_prefix + "Info.plist":
                        out.writestr(n, new_plist)
                    elif _disp and opts.get("force_localize") and n.startswith(app_prefix) and n.endswith(".lproj/InfoPlist.strings"):
                        out.writestr(n, _strings_set_name(z.read(n), _disp))
                    elif n == _exe_name and _exe_data is not None:
                        out.writestr(n, _exe_data)
                    elif n in _patched:
                        out.writestr(n, _patched[n])
                    else:
                        _zinf = z.getinfo(n)
                        with z.open(n) as _src, out.open(_zinf, "w") as _dst:
                            shutil.copyfileobj(_src, _dst, 1024 * 1024)
                for _load, _place, _d in _inject_list:
                    _arc = app_prefix + _place
                    if _arc not in names and os.path.exists(_d):
                        out.write(_d, _arc)
        return True, "", _zsign_dylibs
    except Exception as e:
        return False, str(e)[:200], []


def _feather_build_modified(input_path, opts):
    """Run the Feather pre-sign pipeline: dylib substrate rewrite,
    prep (plist/Mach-O/disinject/rm-files/bot-side inject), then
    the ElleKit/frameworks/bundles extras repack — from the
    PREPARED ipa (rebuild-1 repacked from the input, silently
    discarding the prep edits). Returns
    (prepared_path, tmpdirs, zsign_dylibs) or
    (None, [], [], error_text). tmpdirs are the caller's to delete.
    The result is a modified IPA that still needs signing (or is
    the final product in modify-only mode)."""
    opts = opts or {}
    _tmpdirs = []
    try:
        _prep_dir = tempfile.mkdtemp(prefix="tiloader-prep-")
        _tmpdirs.append(_prep_dir)
        _dylibs = list(opts.get("dylibs") or [])
        _frameworks = list(opts.get("frameworks") or [])
        _bundles = list(opts.get("bundles") or [])
        for _d in _dylibs:
            _rewrite_substrate_paths(_d)
        _prepped = os.path.join(_prep_dir, "prepped.ipa")
        _ok, _err, _zsign_dylibs = _feather_prep_ipa(input_path, _prepped, opts)
        if not _ok:
            for _d in _tmpdirs:
                shutil.rmtree(_d, ignore_errors=True)
            return None, [], [], "feather_prep_failed: %s" % _err
        _prepared = _prepped
        _extras = []
        _app_prefix = None
        if _dylibs or _frameworks or _bundles:
            _app_prefix = _ipa_app_prefix(_prepared)
        if _dylibs and _app_prefix:
            _has_sub = False
            try:
                with zipfile.ZipFile(_prepared) as _z:
                    _has_sub = any(n.startswith(_app_prefix + "Frameworks/CydiaSubstrate.framework/") for n in _z.namelist())
            except Exception:
                pass
            if not _has_sub:
                _ek = resolve_ellekit()
                if not _ek:
                    _LAST_SIGN_NOTES.append("ElleKit (ellekit.deb) was not found next to the bot — the tweak was signed without the CydiaSubstrate substrate and may not work. Put ellekit.deb next to bot.py.")
                else:
                    _ek_dir = tempfile.mkdtemp(prefix="ellekit-")
                    _tmpdirs.append(_ek_dir)
                    _fw = _extract_ellekit_framework(_ek, _ek_dir)
                    if _fw:
                        _extras.append((_app_prefix + "Frameworks/CydiaSubstrate.framework", _fw))
                    else:
                        _LAST_SIGN_NOTES.append("ElleKit (ellekit.deb) was not found next to the bot — the tweak was signed without the CydiaSubstrate substrate and may not work. Put ellekit.deb next to bot.py.")
        if _app_prefix:
            for _fw in _frameworks:
                if os.path.isdir(_fw):
                    _extras.append((_app_prefix + "Frameworks/" + os.path.basename(_fw), _fw))
            for _b in _bundles:
                if os.path.isdir(_b):
                    _extras.append((_app_prefix + os.path.basename(_b), _b))
                elif os.path.isfile(_b):
                    _extras.append((_app_prefix + os.path.basename(_b), _b))
        if _extras and _app_prefix:
            _repack_dir = tempfile.mkdtemp(prefix="tiloader-sign-")
            _tmpdirs.append(_repack_dir)
            _repacked = os.path.join(_repack_dir, "prepared.ipa")
            if _repack_ipa_with_extras(_prepared, _repacked, _extras):
                _prepared = _repacked
            else:
                _LAST_SIGN_NOTES.append("The extras (ElleKit/frameworks/bundles) could not be added; the IPA was signed without them.")
        return _prepared, _tmpdirs, _zsign_dylibs, ""
    except Exception as e:
        for _d in _tmpdirs:
            shutil.rmtree(_d, ignore_errors=True)
        return None, [], [], "feather_prep_failed: %s" % str(e)[:200]


def _deb_data_tarfile(deb_path):
    """Open the data.tar inside a .deb (ar + tar, stdlib only).
    Returns (tarfile_or_None, error_key_or_None). data.tar.zst is
    rejected (no zstd in the stdlib); data.tar.lzma is decompressed
    with the lzma module (LZMA-Alone); .gz/.xz/.bz2/plain go through
    tarfile's own sniffing."""
    import io
    import tarfile
    try:
        with open(deb_path, "rb") as f:
            if f.read(8) != b"!<arch>\n":
                return None, "signopts_bad_deb"
            data_member = None
            while True:
                hdr = f.read(60)
                if len(hdr) < 60:
                    break
                try:
                    size = int(hdr[48:58].decode("ascii").strip() or "0")
                except Exception:
                    break
                name = hdr[0:16].decode("ascii", "ignore").strip().rstrip("/")
                body = f.read(size)
                if size % 2:
                    f.read(1)
                if name.startswith("data.tar"):
                    data_member = (name, body)
    except Exception:
        return None, "signopts_no_dylib_in_deb"
    if not data_member:
        return None, "signopts_no_dylib_in_deb"
    name, body = data_member
    if name.endswith(".zst"):
        return None, "signopts_deb_zst"
    try:
        if name.endswith(".lzma"):
            import lzma
            try:
                raw = lzma.decompress(body, format=lzma.FORMAT_ALONE)
            except Exception:
                raw = lzma.decompress(body, format=lzma.FORMAT_XZ)
            tf = tarfile.open(fileobj=io.BytesIO(raw), mode="r:")
        else:
            tf = tarfile.open(fileobj=io.BytesIO(body), mode="r:*")
    except Exception:
        return None, "signopts_no_dylib_in_deb"
    return tf, None


def _tar_norm_name(name):
    """Normalize a tar member path for classification: drop leading
    ./, reject .. components, strip a leading var/jb/ prefix."""
    parts = [p for p in (name or "").replace("\\", "/").split("/") if p not in ("", ".")]
    if ".." in parts:
        return None
    norm = "/".join(parts)
    if norm.startswith("var/jb/"):
        norm = norm[len("var/jb/"):]
    return norm


def _extract_tweak_from_deb(deb_path, dest_dir):
    """Extract a tweak .deb, sorted like Feather's TweakHandler:
    dylibs from Library/MobileSubstrate/DynamicLibraries (and var/jb/
    variants) are injected; frameworks from Library/Frameworks are
    copied into the app's Frameworks/; bundles from Library/
    Application Support are copied into the app bundle. If no
    MobileSubstrate dylib is found, any .dylib in the tar is taken
    (old behaviour). Returns (found, error_key_or_None) with found =
    {"dylibs": [...], "frameworks": [...], "bundles": [...]}."""
    found = {"dylibs": [], "frameworks": [], "bundles": []}
    tf, err = _deb_data_tarfile(deb_path)
    if err or tf is None:
        return found, err
    try:
        with tf:
            members = tf.getmembers()
            ms_dylibs = []
            any_dylibs = []
            for m in members:
                if not m.isfile():
                    continue
                norm = _tar_norm_name(m.name)
                if not norm:
                    continue
                low = norm.lower()
                if low.endswith(".dylib"):
                    if "library/mobilesubstrate/dynamiclibraries/" in low:
                        ms_dylibs.append(m)
                    elif ".framework/" not in low:
                        any_dylibs.append(m)
            for m in (ms_dylibs if ms_dylibs else any_dylibs):
                base = os.path.basename(m.name)
                if not base or base in (".", ".."):
                    continue
                dest = os.path.join(dest_dir, base)
                with tf.extractfile(m) as src_f, open(dest, "wb") as dst_f:
                    shutil.copyfileobj(src_f, dst_f)
                try:
                    if m.mode:
                        os.chmod(dest, m.mode & 0o7777)
                except Exception:
                    pass
                if _is_macho(dest):
                    found["dylibs"].append(dest)
                else:
                    try:
                        os.remove(dest)
                    except Exception:
                        pass
            seen_fw = set()
            for m in members:
                if not m.isfile():
                    continue
                norm = _tar_norm_name(m.name)
                if not norm:
                    continue
                low = norm.lower()
                if not low.startswith("library/frameworks/"):
                    continue
                rest = norm[len("Library/Frameworks/"):]
                top = rest.split("/")[0]
                if not top.lower().endswith(".framework") or "/" not in rest:
                    continue
                if os.path.basename(rest) == ".DS_Store":
                    continue
                dest = os.path.join(dest_dir, top, *rest.split("/")[1:])
                try:
                    os.makedirs(os.path.dirname(dest), exist_ok=True)
                    with tf.extractfile(m) as src_f, open(dest, "wb") as dst_f:
                        shutil.copyfileobj(src_f, dst_f)
                    if m.mode:
                        os.chmod(dest, m.mode & 0o7777)
                except Exception:
                    continue
                fw_dir = os.path.join(dest_dir, top)
                if fw_dir not in seen_fw:
                    seen_fw.add(fw_dir)
                    found["frameworks"].append(fw_dir)
            seen_bd = set()
            for m in members:
                if not m.isfile():
                    continue
                norm = _tar_norm_name(m.name)
                if not norm:
                    continue
                if not norm.lower().startswith("library/application support/"):
                    continue
                rest = norm[len("Library/Application Support/"):]
                if not rest or os.path.basename(rest) == ".DS_Store":
                    continue
                dest = os.path.join(dest_dir, *rest.split("/"))
                try:
                    os.makedirs(os.path.dirname(dest), exist_ok=True)
                    with tf.extractfile(m) as src_f, open(dest, "wb") as dst_f:
                        shutil.copyfileobj(src_f, dst_f)
                    if m.mode:
                        os.chmod(dest, m.mode & 0o7777)
                except Exception:
                    continue
                top = os.path.join(dest_dir, rest.split("/")[0])
                if top not in seen_bd:
                    seen_bd.add(top)
                    found["bundles"].append(top)
    except Exception:
        return found, "signopts_no_dylib_in_deb"
    if not found["dylibs"] and not found["frameworks"] and not found["bundles"]:
        return found, "signopts_no_dylib_in_deb"
    return found, None


# ---- IPA inspection helpers (kept for the rebuild) ----
# Read-only IPA inspection (stdlib only):
# Info.plist values, embedded .dylib files, dylibs the executable
# already loads (LC_LOAD_DYLIB / WEAK / REEXPORT), architectures
# (thin vs fat/universal), extensions, Watch, Files, and whether it
# is already signed (embedded.mobileprovision / _CodeSignature).
# The Feather pause screen that used these was removed 2026-11-09;
# the rebuild will add its own UI on top. Nothing is written to
# the IPA here; signing still goes through sign_ipa /
# provision_thread.
_MACHO_ARCH_NAMES = {
    0x0100000C: "arm64", 0x01000007: "x86_64", 0x0000000C: "arm",
    0x00000007: "x86", 0x01000012: "arm64_32", 0x00000012: "armv7",
    0x00000009: "armv7", 0x0000000B: "armv7s", 0x0100000B: "armv7s",
}
_MACHO_LOAD_DYLIB_CMDS = (0x0C, 0x18, 0x8000001C, 0x1F)


def _macho_parse(data):
    """(archs, loaded_dylib_paths) from one Mach-O blob (thin or fat).
    Returns ([], []) when the blob is not a Mach-O."""
    if not data or len(data) < 4:
        return [], []
    magic = data[:4]
    slices = []
    if magic in (b"\xca\xfe\xba\xbe", b"\xca\xfe\xba\xbf"):
        try:
            n = struct.unpack(">I", data[4:8])[0]
        except Exception:
            return [], []
        for i in range(min(n, 8)):
            off = 8 + i * 20
            if off + 20 > len(data):
                break
            try:
                cputype, _sub, foff, _fsize, _al = struct.unpack(">IIIII", data[off:off + 20])
            except Exception:
                break
            slices.append((cputype, foff, _fsize))
    elif magic in (b"\xce\xfa\xed\xfe", b"\xcf\xfa\xed\xfe", b"\xfe\xed\xfa\xce", b"\xfe\xed\xfa\xcf"):
        try:
            le = magic in (b"\xce\xfa\xed\xfe", b"\xcf\xfa\xed\xfe")
            fmt = "<I" if le else ">I"
            cputype = struct.unpack(fmt, data[4:8])[0]
        except Exception:
            return [], []
        slices.append((cputype, 0, len(data)))
    else:
        return [], []
    archs = []
    loaded = []
    for cputype, foff, fsize in slices:
        archs.append(_MACHO_ARCH_NAMES.get(cputype, "cpu-%#x" % cputype))
        try:
            blob = data[foff:foff + fsize] if foff else data
            if not blob or len(blob) < 28:
                continue
            le = blob[:4] in (b"\xce\xfa\xed\xfe", b"\xcf\xfa\xed\xfe")
            fmt = "<I" if le else ">I"
            is64 = blob[:4] in (b"\xcf\xfa\xed\xfe", b"\xfe\xed\xfa\xcf")
            ncmds = struct.unpack(fmt, blob[16:20])[0]
            hdr = 32 if is64 else 28
            pos = hdr
            for _ in range(min(ncmds, 200)):
                if pos + 8 > len(blob):
                    break
                cmd, cmdsize = struct.unpack(fmt + "I", blob[pos:pos + 8])
                if cmdsize < 8 or pos + cmdsize > len(blob):
                    break
                if cmd in _MACHO_LOAD_DYLIB_CMDS and cmdsize >= 12:
                    name_off = struct.unpack(fmt, blob[pos + 8:pos + 12])[0]
                    start = pos + name_off
                    end = blob.find(b"\x00", start, pos + cmdsize)
                    if 0 <= start < len(blob) and end > start:
                        try:
                            loaded.append(blob[start:end].decode("utf-8", "ignore"))
                        except Exception:
                            pass
                pos += cmdsize
        except Exception:
            continue
    return archs, loaded


def _inspect_ipa(ipa_path):
    """Read-only inspection of an IPA. Returns a JSON-safe dict;
    never includes file contents, passwords, keys, or UDIDs —
    only counts and the app's own metadata."""
    out = {"error": "", "bundle_id": "", "title": "", "name": "",
           "version": "", "build": "", "min_ios": "", "devices": [],
           "files": False, "extensions": [], "watch": False,
           "dylib_files": [], "loaded_dylibs": [], "loaded_dylib_paths": [],
           "frameworks": [], "archs": [],
           "signed": False, "profile_name": "", "profile_expires": "",
           "profile_devices": 0, "size_mb": 0.0,
           "appearance": "", "itunes_files": False, "promotion": False,
           "game_mode": False, "ipad_fullscreen": False,
           "url_scheme": False, "liquid_glass": ""}
    try:
        out["size_mb"] = round(os.path.getsize(ipa_path) / 1024 / 1024, 1)
    except Exception:
        pass
    try:
        with zipfile.ZipFile(ipa_path) as z:
            names = z.namelist()
            app_prefix = None
            for n in names:
                if n.startswith("Payload/") and n.endswith(".app/Info.plist") and n.count("/") == 2:
                    app_prefix = n[:-len("Info.plist")]
                    break
            if app_prefix is None:
                for n in names:
                    if n.startswith("Payload/") and n.endswith(".app/Info.plist"):
                        app_prefix = n[:-len("Info.plist")]
                        break
            if app_prefix is None:
                out["error"] = "no_info_plist"
                return out
            try:
                info = plistlib.loads(z.read(app_prefix + "Info.plist"))
            except Exception:
                out["error"] = "bad_info_plist"
                return out
            out["bundle_id"] = str(info.get("CFBundleIdentifier") or "")
            out["title"] = str(info.get("CFBundleDisplayName") or info.get("CFBundleName") or "")
            out["name"] = str(info.get("CFBundleName") or out["title"])
            out["version"] = str(info.get("CFBundleShortVersionString") or "")
            out["build"] = str(info.get("CFBundleVersion") or "")
            out["min_ios"] = str(info.get("MinimumOSVersion") or "")
            _dev = info.get("UISupportedDevices")
            if isinstance(_dev, list):
                out["devices"] = [str(x) for x in _dev][:10]
            out["files"] = bool(info.get("UISupportsDocumentBrowser") or info.get("UIFileSharingEnabled"))
            out["appearance"] = str(info.get("UIUserInterfaceStyle") or "")
            out["itunes_files"] = bool(info.get("UIFileSharingEnabled"))
            out["promotion"] = bool(info.get("CADisableMinimumFrameDurationOnPhone"))
            out["game_mode"] = bool(info.get("GCSupportsGameMode"))
            out["ipad_fullscreen"] = bool(info.get("UIRequiresFullScreen"))
            out["url_scheme"] = bool(info.get("CFBundleURLTypes"))
            _lg = info.get("UIDesignRequiresCompatibility")
            if _lg is True:
                out["liquid_glass"] = "disable"
            elif _lg is False:
                out["liquid_glass"] = "enable"
            _ext = sorted({n[len(app_prefix + "PlugIns/"):].split("/")[0]
                           for n in names if n.startswith(app_prefix + "PlugIns/") and "/" in n[len(app_prefix + "PlugIns/"):]})
            out["extensions"] = _ext[:10]
            out["watch"] = any(n.startswith(app_prefix + "Watch/") for n in names)
            out["dylib_files"] = sorted({n[len(app_prefix):] for n in names
                                         if n.startswith(app_prefix) and n.lower().endswith(".dylib")})[:20]
            out["frameworks"] = sorted({"Frameworks/" + n[len(app_prefix + "Frameworks/"):].split("/")[0]
                                        for n in names
                                        if n.startswith(app_prefix + "Frameworks/") and "/" in n[len(app_prefix + "Frameworks/"):]})
            out["frameworks"] += sorted({"PlugIns/" + n[len(app_prefix + "PlugIns/"):].split("/")[0]
                                         for n in names
                                         if n.startswith(app_prefix + "PlugIns/") and "/" in n[len(app_prefix + "PlugIns/"):]})
            out["signed"] = (app_prefix + "embedded.mobileprovision") in names or any(
                n.startswith(app_prefix + "_CodeSignature/") for n in names)
            _exe = info.get("CFBundleExecutable")
            if _exe:
                _exe_name = app_prefix + str(_exe)
                try:
                    _zinf = z.getinfo(_exe_name)
                    if _zinf.file_size > 200 * 1024 * 1024:
                        with z.open(_exe_name) as f:
                            _data = f.read(1024 * 1024)
                    else:
                        _data = z.read(_exe_name)
                    _archs, _loaded = _macho_parse(_data)
                    out["archs"] = _archs
                    out["loaded_dylibs"] = sorted({os.path.basename(x) for x in _loaded})[:20]
                    out["loaded_dylib_paths"] = sorted(set(_loaded))[:20]
                except Exception:
                    pass
        _bid, _prov, _err = read_signed_ipa_parts(ipa_path)
        if _prov:
            out["profile_name"] = str(_prov.get("Name") or "")
            _exp = _prov.get("ExpirationDate")
            try:
                out["profile_expires"] = _expiry_utc_str(_exp)
            except Exception:
                out["profile_expires"] = ""
            _devs = _prov.get("ProvisionedDevices")
            out["profile_devices"] = len(_devs) if isinstance(_devs, list) else 0
    except Exception:
        out["error"] = "unreadable"
    return out


def _inspect_ipa_lines(info):
    """Telegram report lines for _inspect_ipa output."""
    if (info or {}).get("error"):
        return ["❌ Could not read the IPA."]
    lines = []
    lines.append("• %s: %s" % ("Bundle ID", info.get("bundle_id") or "—"))
    lines.append("• %s: %s" % ("Name", info.get("title") or info.get("name") or "—"))
    _ver = (info.get("version") or "")
    if info.get("build"):
        _ver = (_ver + " (%s)" % info["build"]) if _ver else info["build"]
    lines.append("• %s: %s" % ("Version", _ver or "—"))
    lines.append("• %s: %s" % ("Min. iOS", info.get("min_ios") or "—"))
    lines.append("• %s: %s" % ("Devices", ", ".join(info.get("devices") or []) or "—"))
    lines.append("• %s: %s" % ("Files", "✅" if info.get("files") else "❌"))
    lines.append("• %s: %s" % ("Extensions", ", ".join(info.get("extensions") or []) or "—"))
    lines.append("• %s: %s" % ("Watch", "✅" if info.get("watch") else "❌"))
    _archs = info.get("archs") or []
    _arch_txt = ", ".join(_archs) if _archs else "—"
    if len(_archs) > 1:
        _arch_txt += " (universal/fat)"
    lines.append("• %s: %s" % ("Architectures", _arch_txt))
    _dys = info.get("dylib_files") or []
    lines.append("• %s (%d): %s" % ("Dylibs in IPA", len(_dys), ", ".join(_dys[:8]) or "—"))
    _ld = info.get("loaded_dylibs") or []
    lines.append("• %s (%d): %s" % ("Loaded dylibs", len(_ld), ", ".join(_ld[:8]) or "—"))
    lines.append("• %s: %s" % ("Signature", "✅" if info.get("signed") else "❌"))
    if info.get("profile_name"):
        _p = info["profile_name"]
        if info.get("profile_expires"):
            _p += " (до %s" % info["profile_expires"]
            if info.get("profile_devices"):
                _p += ", пристроїв: %d" % info["profile_devices"]
            _p += ")"
        lines.append("• %s: %s" % ("Profile", _p))
    lines.append("• %s: %.1f MB" % ("Size", info.get("size_mb") or 0.0))
    return lines


def _prefill_sign_opts(info, existing):
    """Sign options prefilled with the inspected IPA's current
    values. The owner's earlier choices win: only empty text
    fields are filled, and Files follows the IPA as it is."""
    opts = dict(existing or {})
    for k, v in _sign_opts_default().items():
        if k not in opts:
            opts[k] = v
    info = info or {}
    if not (opts.get("display_name") or "").strip():
        opts["display_name"] = (info.get("title") or "")[:64]
    if not (opts.get("version") or "").strip():
        opts["version"] = info.get("version") or ""
    if not (opts.get("min_ios") or "").strip():
        opts["min_ios"] = info.get("min_ios") or ""
    opts["enable_files"] = bool(info.get("files"))
    opts["itunes_files"] = bool(info.get("itunes_files"))
    opts["promotion"] = bool(info.get("promotion"))
    opts["game_mode"] = bool(info.get("game_mode"))
    opts["ipad_fullscreen"] = bool(info.get("ipad_fullscreen"))
    opts["rm_url_scheme"] = bool(info.get("url_scheme"))
    if not (opts.get("appearance") or "").strip():
        opts["appearance"] = info.get("appearance") or ""
    if not (opts.get("liquid_glass") or "").strip():
        opts["liquid_glass"] = info.get("liquid_glass") or ""
    if not (opts.get("ppq_string") or "").strip():
        opts["ppq_string"] = _random_ppq_string()
    return opts


def _expiry_utc_str(value):
    """Normalize any profile ExpirationDate value to the one
    stored format: "YYYY-MM-DD HH:MM:SS", UTC (2026-11-12,
    win-iconstime). The provisioning profile's ExpirationDate
    is a full datetime; storing date-only made the Mini App
    countdown tick to UTC midnight instead of the true expiry
    moment. Accepts datetime (aware or naive), date, ISO
    string, or anything else ("" when unparseable). Naive
    values are UTC — that is what plist dates are."""
    try:
        if value is None:
            return ""
        if isinstance(value, datetime):
            _dt = value
        elif isinstance(value, date):
            _dt = datetime(value.year, value.month, value.day)
        else:
            _dt = _parse_expiry(value)
            if _dt is None:
                return ""
        if _dt.tzinfo is None:
            _dt = _dt.replace(tzinfo=timezone.utc)
        else:
            _dt = _dt.astimezone(timezone.utc)
        return _dt.strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return ""


def _read_profile_bundle(path):
    """Bundle ID a saved .mobileprovision file was created for
    (Entitlements application-identifier minus the Team ID), or
    "" when the file cannot be read. Same byte-search extraction
    as read_signed_ipa_parts uses for embedded profiles."""
    try:
        with open(path, "rb") as f:
            blob = f.read()
        start = blob.find(b"<?xml")
        end = blob.find(b"</plist>")
        if start < 0 or end < 0:
            return ""
        prov = plistlib.loads(blob[start:end + len(b"</plist>")])
        ent = prov.get("Entitlements") or {}
        app_id = ent.get("application-identifier") or ""
        return app_id.split(".", 1)[1] if "." in app_id else app_id
    except Exception:
        return ""


def _profile_covers_bundle(profile_bundle, bundle):
    """True when a profile created for profile_bundle may sign an
    app with this bundle ID: exact match, or a wildcard profile
    (com.example.*) covering it."""
    if not profile_bundle or not bundle:
        return False
    if profile_bundle == bundle:
        return True
    if profile_bundle.endswith(".*") and bundle.startswith(profile_bundle[:-1]):
        return True
    return False




def _is_macho(path):
    try:
        with open(path, "rb") as f:
            return f.read(4) in _MACHO_MAGICS
    except Exception:
        return False


def _is_png(path):
    try:
        with open(path, "rb") as f:
            return f.read(8) == b"\x89PNG\r\n\x1a\n"
    except Exception:
        return False


def _valid_bundle_id(v):
    if not re.match(r"^[A-Za-z][A-Za-z0-9.-]*$", v or ""):
        return False
    parts = v.split(".")
    return len(parts) >= 2 and all(parts) and ".." not in v and "--" not in v


def _valid_version(v):
    return bool(re.match(r"^\d+(\.\d+){0,3}$", v or ""))


def _valid_minios(v):
    if not re.match(r"^\d+(\.\d+){0,2}$", v or ""):
        return False
    try:
        return 8.0 <= float(v) <= 30.0
    except Exception:
        return False


def _extract_dylibs_from_deb(deb_path, dest_dir):
    """Extract .dylib files from a .deb (ar + tar, stdlib only).
    Returns (paths, error_key_or_None). data.tar.zst is rejected:
    the stdlib cannot read zstd."""
    try:
        with open(deb_path, "rb") as f:
            magic = f.read(8)
            if magic != b"!<arch>\n":
                return [], "signopts_bad_deb"
            data_member = None
            while True:
                hdr = f.read(60)
                if len(hdr) < 60:
                    break
                try:
                    size = int(hdr[48:58].decode("ascii").strip() or "0")
                except Exception:
                    break
                name = hdr[0:16].decode("ascii", "ignore").strip().rstrip("/")
                body = f.read(size)
                if size % 2:
                    f.read(1)
                if name.startswith("data.tar"):
                    data_member = (name, body)
        if not data_member:
            return [], "signopts_no_dylib_in_deb"
        name, body = data_member
        if name.endswith(".zst"):
            return [], "signopts_deb_zst"
        import io
        import tarfile
        try:
            tf = tarfile.open(fileobj=io.BytesIO(body), mode="r:*")
        except Exception:
            return [], "signopts_no_dylib_in_deb"
        out = []
        with tf:
            for m in tf.getmembers():
                if not m.isfile() or not m.name.lower().endswith(".dylib"):
                    continue
                base = os.path.basename(m.name)
                if not base or base in (".", ".."):
                    continue
                dest = os.path.join(dest_dir, base)
                with tf.extractfile(m) as src_f, open(dest, "wb") as dst_f:
                    shutil.copyfileobj(src_f, dst_f)
                if _is_macho(dest):
                    out.append(dest)
                else:
                    try:
                        os.remove(dest)
                    except Exception:
                        pass
        if not out:
            return [], "signopts_no_dylib_in_deb"
        return out, None
    except Exception:
        return [], "signopts_no_dylib_in_deb"


def _verify_sign_opts(ipa_path, opts):
    """Check the signed IPA's Info.plist against the requested
    options. Returns (report_lines, ok). A mismatch flips ok so the
    caller does not claim success or send an install link."""
    opts = opts or {}
    _wanted = []
    if opts.get("display_name"):
        _wanted.append("display_name")
    if opts.get("version"):
        _wanted.append("version")
    if opts.get("min_ios"):
        _wanted.append("min_ios")
    if opts.get("enable_files"):
        _wanted.append("enable_files")
    if opts.get("rm_extensions"):
        _wanted.append("rm_extensions")
    if opts.get("rm_watch"):
        _wanted.append("rm_watch")
    if opts.get("rm_uisd"):
        _wanted.append("rm_uisd")
    if opts.get("dylibs"):
        _wanted.append("dylibs")
    if not _wanted:
        return [], True
    names = []
    info = {}
    app_prefix = None
    try:
        with zipfile.ZipFile(ipa_path) as z:
            names = z.namelist()
            for n in names:
                if n.startswith("Payload/") and n.endswith(".app/Info.plist") and n.count("/") == 2:
                    app_prefix = n[: -len("Info.plist")]
                    break
            if app_prefix is None:
                return ["❌ " + tr("signopts_verify_mismatch") % ("Info.plist", "—", "—")], False
            info = plistlib.loads(z.read(app_prefix + "Info.plist"))
    except Exception:
        return ["❌ " + tr("signopts_verify_mismatch") % ("Info.plist", "—", "—")], False
    lines = []
    ok = True

    def _check(label, want, got):
        nonlocal ok
        if want != got:
            lines.append("❌ " + tr("signopts_verify_mismatch") % (label, want, got or "—"))
            ok = False

    _title = info.get("CFBundleDisplayName") or info.get("CFBundleName") or ""
    _ver = info.get("CFBundleShortVersionString") or info.get("CFBundleVersion") or ""
    if "display_name" in _wanted:
        _check(tr("signopts_lbl_name"), opts["display_name"], _title)
    if "version" in _wanted:
        _check(tr("signopts_lbl_version"), opts["version"], _ver)
    if "min_ios" in _wanted:
        _check(tr("signopts_lbl_minios"), opts["min_ios"], str(info.get("MinimumOSVersion") or ""))
    if "enable_files" in _wanted:
        _got = bool(info.get("UISupportsDocumentBrowser")) and bool(info.get("UIFileSharingEnabled"))
        if not _got:
            lines.append("❌ " + tr("signopts_verify_mismatch") % (tr("signopts_lbl_files"), "✅", "❌"))
            ok = False
    if "rm_extensions" in _wanted:
        if any(n.startswith(app_prefix + "PlugIns/") for n in names):
            lines.append("❌ " + tr("signopts_verify_mismatch") % (tr("signopts_lbl_rmext"), "0", "—"))
            ok = False
    if "rm_watch" in _wanted:
        if any(n.startswith(app_prefix + "Watch/") for n in names):
            lines.append("❌ " + tr("signopts_verify_mismatch") % (tr("signopts_lbl_rmwatch"), "0", "—"))
            ok = False
    if "rm_uisd" in _wanted:
        if info.get("UISupportedDevices") is not None:
            lines.append("❌ " + tr("signopts_verify_mismatch") % (tr("signopts_lbl_rmuisd"), "—", "—"))
            ok = False
    if "dylibs" in _wanted:
        for d in (opts.get("dylibs") or []):
            _base = os.path.basename(d)
            if (app_prefix + _base) not in names:
                lines.append("❌ " + tr("signopts_verify_mismatch") % (tr("signopts_lbl_dylib"), _base, "—"))
                ok = False
    if ok:
        lines.append("✅ " + tr("signopts_verify_ok"))
    return lines, ok


def _local_bot_api():
    """True when a local Bot API server (BOT_API_URL) is configured,
    i.e. sends are not capped at the standard 50 MB limit."""
    return BOT_API_BASE.rstrip("/") != "https://api.telegram.org"


def _signopts_send_return(chat_id, output_path, title):
    """Return-mode send: size-checked sendDocument of the signed IPA.
    Returns True when the file was sent. On oversize (no local Bot
    API server) it does NOT attempt the send: it reports the exact
    size and tries the Tailscale OTA install link instead."""
    try:
        _size = os.path.getsize(output_path)
    except Exception:
        _size = 0
    _limit = 2000 * 1024 * 1024 if _local_bot_api() else 50 * 1024 * 1024
    if _size > _limit:
        send_message(chat_id, tr("signopts_return_too_big") % (_size / 1024 / 1024, _limit / 1024 / 1024))
        if effective_tailscale_url():
            send_install_link(chat_id, output_path, "", title)
        return False
    res = send_document(chat_id, output_path, caption=tr("signopts_return_caption"))
    if res and res.get("ok"):
        send_message(chat_id, tr("signopts_return_sent"))
        return True
    send_message(chat_id, tr("signopts_return_failed"))
    return False


def _signopts_status():
    if not resolve_zsign():
        return tr("status_notfound")
    have = _zsign_flags()
    missing = sorted({"I", "M", "S", "E", "W", "U", "P"} - have)
    if not missing:
        return tr("signopts_status_all")
    return tr("signopts_status_limited") % " ".join("-%s" % f for f in missing)


def _sign_opts_summary_lines():
    opts = job.get("sign_opts") or {}
    lines = []
    lines.append(tr("signopts_mode_current") % (tr("signopts_mode_return") if opts.get("return_mode") else tr("signopts_mode_install")))
    if opts.get("custom_bundle_id"):
        lines.append("• Bundle ID: %s" % opts["custom_bundle_id"])
    if opts.get("display_name"):
        lines.append("• %s: %s" % (tr("signopts_lbl_name"), opts["display_name"]))
    if opts.get("version"):
        lines.append("• %s: %s" % (tr("signopts_lbl_version"), opts["version"]))
    if opts.get("min_ios"):
        lines.append("• %s: %s" % (tr("signopts_lbl_minios"), opts["min_ios"]))
    if opts.get("icon_path"):
        lines.append("• 🖼 %s" % os.path.basename(opts["icon_path"]))
    for d in (opts.get("dylibs") or []):
        lines.append("• 🧩 %s" % os.path.basename(d))
    for _key, _lbl in (("weak_dylib", "signopts_tgl_weak"), ("inject_extensions", "signopts_tgl_injectext"),
                       ("enable_files", "signopts_tgl_files"), ("rm_extensions", "signopts_tgl_rmext"),
                       ("rm_watch", "signopts_tgl_rmwatch"), ("rm_uisd", "signopts_tgl_rmuisd")):
        lines.append("• %s: %s" % (tr(_lbl), "✅" if opts.get(_key) else "❌"))
    return lines


def _show_signopts(chat_id, via, message_id=None, ret=None):
    if ret:
        job["signopts_return"] = ret
    job["step"] = "signopts"
    job["via"] = via
    opts = job.get("sign_opts") or {}
    _text = tr("signopts_title") + "\n" + "\n".join(_sign_opts_summary_lines())
    _text += "\n" + tr("signopts_tweak_warn")
    if opts.get("custom_bundle_id"):
        _text += "\n" + tr("signopts_custom_note")
    _acts = [
        (btn("signopts_mode_install"), "signopts_mode:install"),
        (btn("signopts_mode_return"), "signopts_mode:return"),
        (btn("signopts_set_bundle"), "signopts_set:bundle"),
        (btn("signopts_set_name"), "signopts_set:name"),
        (btn("signopts_set_version"), "signopts_set:version"),
        (btn("signopts_set_minios"), "signopts_set:minios"),
        (btn("signopts_set_icon"), "signopts_set:icon"),
        (btn("signopts_add_dylib"), "signopts_set:dylib"),
        (btn("signopts_add_deb"), "signopts_set:deb"),
    ]
    for _key, _lbl in (("enable_files", "signopts_tgl_files"), ("rm_extensions", "signopts_tgl_rmext"),
                       ("rm_watch", "signopts_tgl_rmwatch"), ("rm_uisd", "signopts_tgl_rmuisd"),
                       ("weak_dylib", "signopts_tgl_weak"), ("inject_extensions", "signopts_tgl_injectext")):
        _acts.append(("%s: %s" % (tr(_lbl), "✅" if opts.get(_key) else "❌"), "signopts_tgl:" + _key))
    if opts.get("icon_path"):
        _acts.append((tr("signopts_rm_icon"), "signopts_rm_icon"))
    for _i, _d in enumerate(opts.get("dylibs") or []):
        _acts.append(("✖ 🧩 %s" % os.path.basename(_d), "signopts_rm_dylib:%d" % _i))
    _acts.append((btn("signopts_clear"), "signopts_clear"))
    _acts.append((btn("signopts_done"), "signopts_done"))
    _acts.append((btn("menu"), "menu"))
    show_screen(chat_id, _text, _acts, via, message_id, wide=True)


def _iloader_roots():
    """Folders where desktop iloader keeps cert.pem/key.pem/profiles.
    Windows: %APPDATA% / %LOCALAPPDATA%. Linux (Tauri): ~/.local/share
    and ~/.config (XDG_DATA_HOME / XDG_CONFIG_HOME when set).
    ILOADER_DIR in .env/environment adds a custom folder."""
    roots = []
    for base in ("APPDATA", "LOCALAPPDATA"):
        root = os.environ.get(base, "")
        if root:
            roots.append(os.path.join(root, "me.nabdev.iloader"))
    if os.name != "nt":
        home = os.path.expanduser("~")
        roots.append(os.path.join(os.environ.get("XDG_DATA_HOME", os.path.join(home, ".local", "share")), "me.nabdev.iloader"))
        roots.append(os.path.join(os.environ.get("XDG_CONFIG_HOME", os.path.join(home, ".config")), "me.nabdev.iloader"))
    _extra = ENV.get("ILOADER_DIR", "").strip()
    if _extra:
        roots.append(_extra)
    return roots


def find_iloader_pairs():
    """Find cert.pem + key.pem pairs in the same iloader folder.
    Returns list of (folder, cert_path, key_path). No file contents
    are read or logged, only paths and dates via openssl."""
    roots = _iloader_roots()
    pairs = []
    for root in roots:
        for dirpath, _dirs, files in os.walk(root):
            if "cert.pem" in files and "key.pem" in files:
                pairs.append((dirpath, os.path.join(dirpath, "cert.pem"), os.path.join(dirpath, "key.pem")))
    return pairs


def cert_dates(cert_path):
    try:
        proc = subprocess.run(["openssl", "x509", "-in", cert_path, "-noout", "-dates"],
                              capture_output=True, text=True, timeout=30)
        return proc.stdout.strip().replace("\n", ", ")
    except Exception:
        return ""


def find_sidestore_profiles():
    roots = _iloader_roots()
    profiles = []
    for root in roots:
        for dirpath, _dirs, files in os.walk(root):
            for name in files:
                if name.startswith("com.SideStore.SideStore.") and name.endswith(".mobileprovision"):
                    profiles.append(os.path.join(dirpath, name))
    return profiles


def create_p12_and_profile():
    """Bot creates p12 + profile itself, from the iloader cache
    on Linux. No manual script, no files sent anywhere.
    Returns a Ukrainian status message. Uses P12_PASSWORD from
    .env as the p12 password; if it is empty, it cannot build
    a p12 and tells the user to set it in .env first."""
    global P12_PATH, PROVISION_PATH
    if not P12_PASSWORD:
        return tr("l10n_create_need_p12pw")
    pairs = find_iloader_pairs()
    if not pairs:
        return tr("l10n_create_no_pairs")
    # Use the newest pair by cert file time.
    pairs.sort(key=lambda p: os.path.getmtime(p[1]), reverse=True)
    folder, cert_path, key_path = pairs[0]
    out_p12 = os.path.join(BASE_DIR, "iloader.p12")
    try:
        proc = subprocess.run(["openssl", "pkcs12", "-export", "-inkey", key_path,
                               "-in", cert_path, "-out", out_p12,
                               "-passout", "pass:" + P12_PASSWORD],
                              capture_output=True, text=True, timeout=120)
    except Exception as e:
        return tr("l10n_openssl_start_fail") % e
    if proc.returncode != 0 or not os.path.exists(out_p12):
        return tr("l10n_openssl_p12_fail")
    P12_PATH = out_p12
    msg = [tr("l10n_p12_done"),
           tr("l10n_p12_pair_folder") % folder[-12:],
           tr("l10n_p12_cert_line") % cert_dates(cert_path),
           tr("l10n_p12_file_line")]
    profiles = find_sidestore_profiles()
    if profiles:
        profiles.sort(key=os.path.getmtime, reverse=True)
        chosen = profiles[0]
        dest = os.path.join(BASE_DIR, os.path.basename(chosen))
        try:
            shutil.copyfile(chosen, dest)
            PROVISION_PATH = dest
            msg.append(tr("l10n_profile_copied") % os.path.basename(chosen))
        except Exception as e:
            msg.append(tr("l10n_profile_copy_fail") % e)
    else:
        msg.append(tr("l10n_profile_not_in_cache"))
    msg.append(tr("l10n_create_next"))
    return "\n".join(msg)


