# ---------------- FEATHER LIBRARY (clean rebuild, part 4) 2026-11-09 ----------------
# Signed apps from installed_apps.json with an expiry pill per row,
# search + scope filter, bulk delete, per-app info sheet, and
# check-for-updates against the enabled Programs repo sources.
# Sections: "signed" = records from a source (preset/ipatool/
# programs — re-downloadable), "imported" = records the user sent
# as a file (kind == "import", kept as originals/<bundle>.ipa).
# The shared last-signed.ipa is never deleted by a library delete:
# it belongs to the last sign, not to one record.


def _feather_lib_records(scope="all", query=""):
    """Registry records filtered by scope + search text.
    scope: all | signed (source kind != import) | imported
    (kind == import). Query matches title or bundle ID."""
    _recs = load_installed()
    _q = (query or "").strip().lower()
    out = []
    for r in _recs:
        if not isinstance(r, dict):
            continue
        _kind = ((r.get("source") or {}).get("kind") or "")
        if scope == "signed" and _kind == "import":
            continue
        if scope == "imported" and _kind != "import":
            continue
        if _q and _q not in (str(r.get("title") or "") + " " + str(r.get("bundle") or "")).lower():
            continue
        out.append(r)
    return out


def _feather_lib_row_label(rec):
    """One library row: title + expiry pill, 🔴 when the profile
    expires within 48h or already expired."""
    _pill, _soon = _feather_lib_expiry_pill(rec)
    _title = (rec.get("title") or rec.get("bundle") or "?")[:32]
    return "%s%s %s" % ("🔴 " if _soon else "", _title, _pill)


def _feather_lib_scope_label(scope):
    """Scope filter button label, with ✅ on the active scope."""
    _active = (job.get("lib_scope") or "all") == scope
    return btn("feather_lib_scope_" + scope) + (" ✅" if _active else "")


def _feather_lib_ipa_path(rec):
    """An IPA on disk for a registry record: the kept unsigned
    original first (originals/<bundle>.ipa), then the signed file
    when its bundle matches. Returns '' when none exists."""
    _src = rec.get("source") or {}
    _orig = _src.get("original_path", "")
    if _orig and os.path.exists(_orig):
        return _orig
    _bundle = rec.get("bundle") or ""
    _safe = re.sub(r"[^A-Za-z0-9._-]", "", (_bundle or "app").replace(" ", ""))
    _cand = os.path.join(BASE_DIR, "originals", (_safe or "app") + ".ipa")
    if os.path.exists(_cand):
        return _cand
    _signed = rec.get("signed_path", "")
    if _signed and os.path.exists(_signed):
        try:
            _bid, _v, _t = read_ipa_info(_signed)
            if _bid == _bundle:
                return _signed
        except Exception:
            pass
    return ""


def _feather_lib_info_lines(rec):
    """Per-app info sheet: Info / Certificate / Bundle /
    Executable. Version, min iOS, architectures and entitlements
    come from the IPA on disk when it exists, else 'недоступно'."""
    lines = []
    _bundle = rec.get("bundle") or ""
    _title = rec.get("title") or _bundle or "?"
    lines.append(tr("feather_lib_info_name") % _title)
    lines.append(tr("feather_lib_info_bundle") % (_bundle or "—"))
    _ipa = _feather_lib_ipa_path(rec)
    _info = _inspect_ipa(_ipa) if _ipa else {}
    _ver = (_info.get("version") or "")
    if _info.get("build"):
        _ver = (_ver + " (%s)" % _info["build"]) if _ver else _info["build"]
    _na = tr("feather_lib_info_na")
    lines.append(tr("feather_lib_info_version") % (_ver or _na))
    lines.append(tr("feather_lib_info_minios") % (_info.get("min_ios") or _na))
    lines.append(tr("feather_lib_info_archs") % (", ".join(_info.get("archs") or []) or _na))
    _size = _info.get("size_mb") or 0
    lines.append(tr("feather_lib_info_size") % (("%.1f MB" % _size) if _size else _na))
    _signed = (rec.get("signed_at") or "")[:10]
    lines.append(tr("feather_lib_info_signed") % (_signed or _na))
    _exp = rec.get("profile_expires") or ""
    _pill, _soon = _feather_lib_expiry_pill(rec)
    lines.append(tr("feather_lib_info_exp") % ((_exp[:10] + " " + _pill) if _exp else _pill))
    lines.append(tr("feather_lib_info_appleid") % (rec.get("apple_id") or _na))
    lines.append(tr("feather_lib_info_profile") % (rec.get("profile_id") or _na))
    if _ipa:
        _ent = _ipa_binary_entitlements(_ipa) or {}
        if _ent:
            lines.append(tr("feather_lib_info_ent") % ", ".join(sorted(str(k) for k in _ent.keys())))
        else:
            lines.append(tr("feather_lib_info_ent") % tr("feather_lib_info_ent_none"))
    else:
        lines.append(tr("feather_lib_info_ent") % _na)
    return lines


def _feather_lib_delete_bundle(bundle, keep_files=None):
    """Remove one record from installed_apps.json + delete its
    kept original IPA. The shared last-signed.ipa is never
    deleted (it belongs to the last sign, not this record).

    keep_files: None = follow the "Clear Customizations on
    Uninstall" setting (default behaviour); True = keep the
    original IPA (Remove record only); False = always delete the
    files (My Apps › Delete, an explicit user order that
    outranks the setting)."""
    _recs = load_installed()
    _rec = next((r for r in _recs if r.get("bundle") == bundle), None)
    if _rec is None:
        return False
    _files = []
    _orig = (_rec.get("source") or {}).get("original_path", "")
    if _orig and os.path.exists(_orig):
        _files.append(_orig)
    _safe = re.sub(r"[^A-Za-z0-9._-]", "", (bundle or "app").replace(" ", ""))
    _cand = os.path.join(BASE_DIR, "originals", (_safe or "app") + ".ipa")
    if os.path.exists(_cand) and _cand not in _files:
        _files.append(_cand)
    save_installed([r for r in _recs if r.get("bundle") != bundle])
    # Clear Customizations on Uninstall (User Customizations,
    # default ON): with it OFF only the record is removed and
    # the kept original IPA stays, so the app can be re-signed
    # later without re-downloading.
    _drop = (not bool(_uc_get("clear_uninstall"))) if keep_files is None else (not keep_files)
    if _drop:
        for _f in _files:
            try:
                os.remove(_f)
            except Exception:
                pass
    # The cached icon belongs to this record too.
    try:
        os.remove(_appicon_cache_path(bundle))
    except Exception:
        pass
    # Delete completed: refresh every live widget card.
    _widgets_push_all()
    return True


def _feather_ver_newer(new, old):
    """True when version string `new` is newer than `old`
    (numeric dotted compare; non-numeric parts ignored)."""
    def _parts(v):
        out = []
        for p in re.split(r"[.\-+_]", str(v or "")):
            try:
                out.append(int(p))
            except Exception:
                pass
        return out or [0]
    _n, _o = _parts(new), _parts(old)
    _n += [0] * (len(_o) - len(_n))
    _o += [0] * (len(_n) - len(_o))
    return _n > _o


def _feather_lib_source_apps():
    """All apps from the enabled repo sources: cached repo first,
    live fetch (and cache save) when no cache. One pass per call,
    so a multi-app update check fetches each source once.
    FlekStore is skipped: its placeholder bundle IDs can never
    match a real app."""
    data = _programs_sources_load()
    _repo_srcs = [s for s in _programs_enabled_sources(data) if (s.get("kind") or "repo") == "repo"]
    _by_id = {}
    _need_fetch = []
    for src in _repo_srcs:
        _sid = src.get("id")
        _apps, _when = _programs_cache_load(_sid)
        if _apps is not None:
            _by_id[_sid] = _apps
        else:
            _need_fetch.append(src)
    if _need_fetch:
        try:
            import concurrent.futures as _cf
            def _fetch_one(s):
                _d, _raw, _err = _programs_fetch_repo(s.get("url") or "", timeout=12)
                if _err or not _d:
                    return s.get("id"), []
                _programs_cache_save(s.get("id"), _raw)
                _a = _d.get("apps") or []
                _programs_normalize_flat_apps(_a)
                return s.get("id"), _a
            with _cf.ThreadPoolExecutor(max_workers=6) as _ex:
                for _sid_res, _apps_res in _ex.map(_fetch_one, _need_fetch, timeout=18):
                    _by_id[_sid_res] = _apps_res
        except Exception:
            pass
    apps = []
    for src in _repo_srcs:
        apps.extend(_by_id.get(src.get("id")) or [])
    return apps


def _feather_lib_find_update(bundle, installed_version, apps=None):
    """Newest version newer than the installed one, from a
    pre-fetched app list (or a fresh source pass when None).
    Returns (app_dict, version_dict) or None."""
    if apps is None:
        apps = _feather_lib_source_apps()
    for app in apps:
        if not isinstance(app, dict):
            continue
        if (app.get("bundleIdentifier") or "") != bundle:
            continue
        _ver = _programs_latest(app)
        if not _ver:
            return None
        _vstr = str(_ver.get("version") or "")
        if _vstr and _feather_ver_newer(_vstr, installed_version):
            return app, _ver
        return None
    return None


def _feather_show_library(chat_id, via, message_id=None):
    """Library: signed apps from installed_apps.json with an
    expiry pill per row, scope filter, search, bulk delete."""
    job["step"] = "feather_library"
    job["via"] = via
    _scope = job.get("lib_scope") or "all"
    _query = job.get("lib_query") or ""
    _all = load_installed()
    _recs = _feather_lib_records(_scope, _query)
    lines = [tr("feather_library_title") % (tr("feather_lib_scope_name_" + _scope), len(_all), len(_recs))]
    if _query:
        lines.append(tr("feather_library_search_title") % (_query, len(_recs)))
    acts = []
    if not _all:
        lines.append(tr("feather_library_empty"))
    for r in _recs:
        _lbl = _feather_lib_row_label(r)
        lines.append(_lbl)
        acts.append((_lbl, "feather_lib_info:%s" % r.get("bundle")))
    for _s in ("all", "signed", "imported"):
        acts.append((_feather_lib_scope_label(_s), "feather_lib_scope:%s" % _s))
    acts.append((btn("feather_lib_search"), "feather_lib_search"))
    if _query:
        acts.append((btn("feather_lib_search_clear"), "feather_lib_search_clear"))
    acts.append((btn("feather_lib_check_updates"), "feather_lib_check_updates"))
    if _recs:
        acts.append((btn("feather_lib_bulk"), "feather_lib_bulk"))
    acts.append((btn("feather"), "feather"))
    show_screen(chat_id, "\n".join(lines), acts, via, message_id, wide=True)


def _feather_show_library_bulk(chat_id, via, message_id=None):
    """Bulk delete: tap rows to select, then one confirm."""
    job["step"] = "feather_library_bulk"
    job["via"] = via
    _sel = set(job.get("lib_sel") or [])
    _recs = _feather_lib_records(job.get("lib_scope") or "all", job.get("lib_query") or "")
    lines = [tr("feather_library_bulk_title") % len(_sel)]
    acts = []
    for r in _recs:
        _b = r.get("bundle") or ""
