def _feather_show_lib_info(chat_id, via, bundle, message_id=None):
    """Per-app info sheet: Info / Certificate / Bundle /
    Executable + refresh, update check, delete."""
    rec = next((r for r in load_installed() if r.get("bundle") == bundle), None)
    if not rec:
        send_message(chat_id, tr("feather_lib_not_found"))
        _feather_show_library(chat_id, via, message_id)
        return
    job["step"] = "feather_library_info"
    job["via"] = via
    job["lib_view_bundle"] = bundle
    lines = ["📱 %s" % (rec.get("title") or bundle)] + _feather_lib_info_lines(rec)
    acts = []
    if _refresh_source_ok(rec):
        acts.append((btn("refresh_install"), "refresh_install:%s" % bundle))
    acts.append((btn("widget_app"), "widget_app:%s" % bundle))
    acts.append((btn("feather_lib_update"), "feather_lib_update:%s" % bundle))
    if _feather_lib_ipa_path(rec):
        acts.append((btn("ipa_browse"), "ipa_browse_lib:%s" % bundle))
    acts.append((btn("feather_lib_delete"), "feather_lib_del:%s" % bundle))
    acts.append((btn("feather_library"), "feather_library"))
    show_screen(chat_id, "\n".join(lines), acts, via, message_id, wide=True)


# IPA CONTENT BROWSER (2026-11-11-win-ipadn-ipa) ---------------
# Lists the files inside an IPA (ZIP central directory only,
# nothing is extracted to list) and extracts a tapped file:
# small files go to chat as a document, large ones are saved
# under extracted/ on the PC. Owner-only, ZIP-slip safe.
IPA_BROWSE_PAGE = 20


def _ipa_browse_list(ipa_path):
    """(entries, error): entries = [(name, size)] sorted with
    Payload/ first, then alphabetical. Reads only the ZIP
    central directory (stdlib zipfile). error is
    "missing" | "bad" | None."""
    if not ipa_path or not os.path.exists(ipa_path):
        return [], "missing"
    try:
        with zipfile.ZipFile(ipa_path) as z:
            entries = [(i.filename, i.file_size) for i in z.infolist()
                       if not i.filename.endswith("/")]
    except (zipfile.BadZipFile, OSError, ValueError):
        return [], "bad"
    entries.sort(key=lambda e: (0 if e[0].startswith("Payload/") else 1, e[0].lower()))
    return entries, None


def _ipa_browse_safe_name(name):
    """True when a ZIP entry name is safe to extract: no
    absolute path, no '..' segment, no drive letter, no NUL."""
    if not name or "\x00" in name:
        return False
    _n = name.replace("\\", "/")
    if _n.startswith("/") or re.match(r"^[A-Za-z]:", _n):
        return False
    if any(p == ".." for p in _n.split("/")):
        return False
    return True


def _ipa_browse_save_large(tmp_path, base):
    """Move an extracted file into extracted/ beside bot.py
    (unique name on collision), return the full PC path."""
    _dir = os.path.join(BASE_DIR, "extracted")
    os.makedirs(_dir, exist_ok=True)
    _stem, _ext = os.path.splitext(base)
    _dest = os.path.join(_dir, base)
    _n = 1
    while os.path.exists(_dest):
        _n += 1
        _dest = os.path.join(_dir, "%s_%d%s" % (_stem, _n, _ext))
    shutil.move(tmp_path, _dest)
    return _dest


def _ipa_browse_show(chat_id, via, message_id=None):
    """Render the current browser page from job['ipa_browse'].
    Entry labels carry a unique index prefix, so Reply taps
    resolve through last_actions (see handle_text)."""
    _st = job.get("ipa_browse") or {}
    _entries = _st.get("entries") or []
    _page = int(_st.get("page") or 0)
    _pages = max(1, (len(_entries) + IPA_BROWSE_PAGE - 1) // IPA_BROWSE_PAGE)
    _page = max(0, min(_page, _pages - 1))
    _st["page"] = _page
    job["step"] = "ipa_browse"
    job["via"] = via
    _start = _page * IPA_BROWSE_PAGE
    _chunk = _entries[_start:_start + IPA_BROWSE_PAGE]
    _lines = [tr("ipa_browse_title") % (_st.get("title") or "app.ipa", len(_entries),
              _programs_fmt_size(_st.get("ipa_size") or 0), _page + 1, _pages)]
    acts = []
    for _i, (_name, _size) in enumerate(_chunk):
        _idx = _start + _i
        _label = ("%d. %s (%s)" % (_idx + 1, _name, _programs_fmt_size(_size)))[:120]
        _lines.append(_label)
        acts.append((_label, "ipa_browse_file:%d" % _idx))
    if _page + 1 < _pages:
        acts.append((btn("ipa_browse_more"), "ipa_browse_more"))
    acts.append((btn("ipa_browse_back"), "ipa_browse_back"))
    show_screen(chat_id, "\n".join(_lines), acts, via, message_id, wide=True)


def _ipa_browse_open(chat_id, via, ipa_path, title, origin, message_id=None):
    """Open the browser for one IPA file. origin: 'inspect' or
    'lib:<bundle>' — where Back returns to."""
    _entries, _err = _ipa_browse_list(ipa_path)
    if _err == "missing":
        send_message(chat_id, tr("ipa_browse_no_ipa"))
        return
    if _err == "bad":
        send_message(chat_id, tr("ipa_browse_bad_ipa"))
        return
    if not _entries:
        send_message(chat_id, tr("ipa_browse_empty"))
        return
    try:
        _size = os.path.getsize(ipa_path)
    except Exception:
        _size = 0
    job["ipa_browse"] = {"path": ipa_path, "title": title,
                         "entries": _entries, "page": 0,
                         "origin": origin, "ipa_size": _size}
    _ipa_browse_show(chat_id, via, message_id)


def _ipa_browse_back(chat_id, via, message_id=None):
    """Back from the browser to the screen it was opened from."""
    _st = job.get("ipa_browse") or {}
    _origin = _st.get("origin") or "inspect"
    job["ipa_browse"] = {}
    if _origin.startswith("lib:"):
        _feather_show_lib_info(chat_id, via, _origin[4:], message_id)
    else:
        _feather_show_inspect(chat_id, via, message_id)


def _ipa_browse_extract(chat_id, via, index, message_id=None):
    """Extract one listed entry. Small files (50 MB cap, or
    2000 MB with a local Bot API server) are sent as a document
    and the temp file is deleted; large ones are saved under
    extracted/ and the full PC path is reported. ZIP-slip
    unsafe entries and symlinks are refused; the file is
    streamed out of the archive, never read whole into RAM,
    and is only ever written inside the temp dir / extracted/."""
    _st = job.get("ipa_browse") or {}
    _entries = _st.get("entries") or []
    _path = _st.get("path") or ""
    if not _entries or not _path or not os.path.exists(_path):
        send_message(chat_id, tr("ipa_browse_stale"))
        return
    try:
        _idx = int(index)
        _name, _size = _entries[_idx]
    except (ValueError, IndexError, TypeError):
        send_message(chat_id, tr("ipa_browse_stale"))
        return
    if not _ipa_browse_safe_name(_name):
        send_message(chat_id, tr("ipa_browse_bad_entry"))
        return
    _tmpdir = ""
    try:
        with zipfile.ZipFile(_path) as z:
            try:
                _info = z.getinfo(_name)
            except KeyError:
                send_message(chat_id, tr("ipa_browse_stale"))
                return
            if (_info.external_attr >> 16) & 0o170000 == 0o120000:
                send_message(chat_id, tr("ipa_browse_bad_entry"))
                return
            _base = os.path.basename(_name.replace("\\", "/"))
            if not _base:
                send_message(chat_id, tr("ipa_browse_bad_entry"))
                return
            _tmpdir = tempfile.mkdtemp(prefix="tiloader-ipa-")
            _tmp = os.path.join(_tmpdir, _base)
            with z.open(_info, "r") as _src, open(_tmp, "wb") as _dst:
                shutil.copyfileobj(_src, _dst, 1024 * 1024)
        _size = os.path.getsize(_tmp)
        _limit = 2000 * 1024 * 1024 if _local_bot_api() else 50 * 1024 * 1024
        if _size <= _limit:
            _res = send_document(chat_id, _tmp, caption=_name)
            if _res and _res.get("ok"):
                send_message(chat_id, tr("ipa_browse_sent") % (_name, _programs_fmt_size(_size)))
            else:
                _saved = _ipa_browse_save_large(_tmp, _base)
                send_message(chat_id, tr("ipa_browse_send_failed") % _saved)
        else:
            _saved = _ipa_browse_save_large(_tmp, _base)
            send_message(chat_id, tr("ipa_browse_saved") % (_programs_fmt_size(_size), _programs_fmt_size(_limit), _saved))
    except zipfile.BadZipFile:
        send_message(chat_id, tr("ipa_browse_bad_ipa"))
    except Exception as e:
        send_message(chat_id, tr("ipa_browse_extract_failed") % str(e)[:120])
    finally:
        if _tmpdir:
            shutil.rmtree(_tmpdir, ignore_errors=True)


