    if action == "botlog_copy":
        _tail = ""
        try:
            with open("/tmp/bot.log", "r", encoding="utf-8", errors="ignore") as _lf:
                _tail = "".join(_lf.readlines()[-35:])
        except Exception as _le:
            _tail = "log read error: %s" % _le
        if not _tail.strip():
            _tail = "(empty)"
        if len(_tail) > 3500:
            _tail = _tail[-3500:]
        import html as _html
        send_message(chat_id, "<pre>%s</pre>" % _html.escape(_tail), parse_mode="HTML")
        return
