    if action == "kill_restart":
        if not is_owner(chat_id):
            send_message(chat_id, tr("owner_only"))
            return
        _me = os.getpid()
        _killed = 0
        try:
            for _d in os.listdir("/proc"):
                if not _d.isdigit():
                    continue
                _pid = int(_d)
                if _pid == _me:
                    continue
                try:
                    with open("/proc/%d/cmdline" % _pid, "rb") as _cf:
                        _cl = _cf.read().replace(b"\x00", b" ").decode("utf-8", errors="ignore")
                    if ("telegram_iloader_bot.py" in _cl or
                            os.path.basename(SIBOOT_EXE or "siboot") in _cl or
                            "telegram-iloader-" in _cl):
                        os.kill(_pid, 9)
                        _killed += 1
                except Exception:
                    pass
        except Exception:
            pass
        send_message(chat_id, "🧹 Прибив зайвих процесів: %d. Перезапускаю бота..." % _killed)
        time.sleep(0.8)
        os.execv(sys.executable, [sys.executable, os.path.abspath(__file__)])
        return
